/* 令和7年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r07.committeeSessions.push(...[{"id":"r07-20250304-3","meetingId":"r07-c-budget","date":"2025年3月4日","dateIso":"2025-03-04","committee":"予算特別委員会","time":"午前 ９時３０分～午後 ５時３９分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を187件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"ゆきた副委員長","kind":"質問","question":"１人当たりの質問時間は、２０分のいずれかとし、答弁時間も含めて１日につき１０分となります。残り時間がなくなった時点で振鈴を２回鳴らしますので、質問の途中でありましても、直ちに取りやめていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"まつざわ委員","kind":"質問","question":"無駄をなくすというところにあまり着目し過ぎてしまうと、新規事業を実施する際には視野を狭めてしまわないか、大変心配しています。","respondent":"加島財政課長","answer":"令和７年度予算案におきましては、ハード整備、それから学校改築推進経費に係る歳出を支えてまいりたいと考えております。適切な歳出規模の事業を当初予算から組むことができていると考えております。","id":"exchange-002"},{"speaker":"まつざわ委員","kind":"確認","question":"今の話で、積み立てた基金をしっかり正確に使っているということの確認が取れました。これに伴って庁舎整備全体の資金、また財源の構成というのはどうなっていくのか、説明するよう求めました。","respondent":"加島財政課長","answer":"区負担５５３億円のうち、起債により約４１３億円を調達いたします。それから、庁舎整備基金から約１４０億円を繰入れすることにより、区負担分の財源を確保してまいる計画です。","id":"exchange-003"},{"speaker":"まつざわ委員","kind":"質問","question":"負担のバランスというのですか、負担の平準化というのですか、そういうものを図るという部分では意味があると考えます。区の借入れとなるため、私たち区民の中には心配に思われる方もいらっしゃると考えますが、返済計画等の概要といったことについて説明するよう求めました。","respondent":"加島財政課長","answer":"減債基金に計画的な積立てを行うことによって、元金の償還、将来の償還に対応してまいりたいと考えております。こちらを新庁舎整備、今後は減債基金に積み立ててまいりますので、区民に何か過大な負担をかけることはないかと考えております。","id":"exchange-004"},{"speaker":"まつざわ委員","kind":"確認","question":"区民に負担がかからないことの確認が取れました。新庁舎ですけれども、総事業費が７００億円余と聞いていますが、これは想定より上がったものではないか尋ねました。","respondent":"小林新庁舎建設担当課長","answer":"設計者や発注者の支援をいただいておりますコンストラクション・マネジャーらと広く検討を進めてきましたが、予算として提案するものです。発注後の物価高騰への対応につきましては、関係課と調整し合いながら、契約変更の手続を行うことになるかと考えているところです。","id":"exchange-005"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"庁舎として求められる環境面、また防災面は、どのように考えているのでしょうか。他自治体の庁舎建設の事例と比較して、特に品川区ならではといった特徴があるのか、説明するよう求めました。","respondent":"小林新庁舎建設担当課長","answer":"環境や防災面の対応ですが、現庁舎と比較してより向上させたものとして検討を進めているところですので、その考えには変わりはないところです。","id":"exchange-006"},{"speaker":"まつざわ委員","kind":"意見","question":"しかし一方で、補助２６号線、あそこが開発されてしまうと、補助２６号線を歩く人が少なくなるということが懸念されているかと思っています。庁舎跡地の活用検討をどのように考えているのか説明するよう求めました。","respondent":"泉広町事業調整担当課長","answer":"こちらは、着手の時期にかかわらず、区民ニーズの実現と区民負担の軽減に向けまして、引き続き検討を進めてまいります。今年度の６月まで開催してまいりました、跡地の活用検討委員会の検討の結果を踏まえながら、また魅力の向上に向けて取り組んでまいります。","id":"exchange-007"},{"speaker":"まつざわ委員","kind":"質問","question":"広町が品川区の中心になりますように、また品川区の象徴となる庁舎建設が、妥協を一切許さない、しっかりした施設になるように願いまして、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"新妻委員","kind":"質問","question":"８５ページ、４９ページ・８３ページ、関連して伺ってまいります。初めに、４９ページ・８１ページに記載されております予算額が、ともにマイナス補正となっておりますので、この内容を示すよう求めました。","respondent":"藤村子ども育成課長","answer":"マイナス補正の金額につきましては、工事契約の落差額分という形になっております。","id":"exchange-009"},{"speaker":"新妻委員","kind":"質問・要望","question":"高齢者が多く住まわれている都営住宅の１階に開設されるということで、多世代交流の観点から、住民との交流が持てることを要望してまいりました。","respondent":"藤村子ども育成課長","answer":"委員のご説明のとおり、今回の八潮の子育て支援施設におきましては、多世代交流という観点も踏まえて運営していきたいと考えております。イベント等でのキッチンカーの活用などといった観点も含めて運営もしていきたいと考えております。","id":"exchange-010"},{"speaker":"新妻委員","kind":"質問・要望","question":"ぜひよろしくお願いします。地元の地域の人も、もし何かそういう声が上がっているようでありましたら声をここでお聞かせいただきたいのですが、いかがか尋ねました。","respondent":"今井八潮まちづくり担当課長","answer":"今年の１月に東京都と覚書を締結いたしまして、品川区として都営住宅における買物弱者支援事業ということで実施させていただいているところです。","id":"exchange-011"},{"speaker":"新妻委員","kind":"質問・要望","question":"この施設だけではなく八潮地域周辺もアピールしていただきながら、多くの方を施設へと誘導してほしいと求めましたが、見解を伺います。","respondent":"藤村子ども育成課長","answer":"本施設のみならず、近隣の施設と連携して、なるべく多くの集客ができるように展開してまいりたいと考えています。プチレーブと連携した施設内でのパンの販売といった、福祉施設との連携というところも、しっかり検討してまいりたいと思います。","id":"exchange-012"},{"speaker":"新妻委員","kind":"質問・要望","question":"多くのマンションが建ち並んだ海辺の地域にもしっかりと開設してほしいということを要望し続けてまいりましたが、現在、お聞きしたいと思います。","respondent":"中島保育施設運営課長","answer":"病児保育施設につきましては、昨年の９月に説明会を開催いたしました。新規開設にも当然注力しておりますが、併せましてベビーシッターの周知も進めてまいりたいと思います。","id":"exchange-013"},{"speaker":"新妻委員","kind":"質問・要望","question":"確実に３件増やしていただくこと、また、区民が利用しやすい体制を整えていただきたいことを要望して質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"ひがし委員","kind":"質問","question":"最初に、ベビーシッター利用支援事業についてお伺いいたします。令和６年度当初予算の考え方として想定の人数と金額についてお伺いいたします。","respondent":"芝野保育入園調整課長","answer":"今、当初予算の考え方についてのご質問をいただきました。当初の想定を上回る２,６８０人、３億６,０００万円程度の利用が見込まれることなどから、今回の補正予算を計上しています。","id":"exchange-015"},{"speaker":"ひがし委員","kind":"質問","question":"すごく需要の高まりを感じております。具体的にどのような方が利用しているのか、利用時間帯など、分かる範囲で説明するよう求めました。","respondent":"芝野保育入園調整課長","answer":"利用時間につきましては、１０時から１７時までの日中の利用が多く、夜間利用は全体の数％程度となっております。保護者のリフレッシュや、お子さんの病院の通院など、日常生活上の突発的な事情による一時的利用というのが多いものと認識しております。","id":"exchange-016"},{"speaker":"ひがし委員","kind":"質問・要望","question":"共働き世帯の増加に伴って、育児に対する不安や負担を軽減するためにも、このような支援が今後ますます求められていると考えています。児童１人につきひと年度当たり１４４時間、東京都のベビーシッター登録制度について、登録団体とその方法について説明するよう求めました。","respondent":"芝野保育入園調整課長","answer":"東京都のベビーシッター利用助成事業における認定事業者ですが、現在、３０事業者が登録されているところです。したがいまして、現状、個人としての登録は今できない形となっています。","id":"exchange-017"},{"speaker":"ひがし委員","kind":"意見","question":"双子などの場合には２人のベビーシッターを手配する必要があるなど、実際に現場の声としてどのような声が届いているのかお聞かせください。この需要の高まりに対する対応策、利用者目線の改善も今後必要だと思いますが、区の見解も説明するよう求めました。","respondent":"芝野保育入園調整課長","answer":"意見交換の場というのがかなりありまして、そちらを通じて声を聞いているような状況で、人材育成等の研修というものも実施しているです。こちらも東京都の動きを注視させていただきまして、よりベビーシッター事業を推進していけるように、区としても対応していきたいと思います。","id":"exchange-018"},{"speaker":"ひがし委員","kind":"質問・要望","question":"何か東京都の要件が緩和される、また団体だけではなくて個人の方でも、ぜひ区としても都に伝えていってほしいと考えています。利用につながっていない方の分析を行い、誰一人取り残さない子育て支援の要望をしておりますが、現在の進捗状況などについて説明するよう求めました。","respondent":"石橋品川保健センター所長","answer":"引き続き、利用促進および状況把握を実施してまいります。今回の事業は一部減額補正ということにはなりましたが、しっかりと計画どおり適切に実施してまいりたいと思います。","id":"exchange-019"},{"speaker":"ひがし委員","kind":"確認","question":"国の補助金が少し減額になっているので心配していたところなのですけれども、今ご答弁の中で、しっかりと実施していくということが確認できました。今後もしっかりとこの事業を進めていただき、誰一人取り残さない子育て支援を行ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問","question":"９７ページ、小山三丁目第２地区再開発事業補助金について伺います。７億７,７６０万円の皆減ですが、まずこの地区の想定事業費と補助金投入総額は幾らなのか伺いたいと思います。","respondent":"中道都市開発課長","answer":"想定事業費および補助金の金額ですが、今現在、この地区におきましては、地域の方々で今そういったまちづくりを検討している最中というところで、総事業費または補助金といったところは今現在、検討中というところで聞いております。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問","question":"こちらは都市計画決定もされておりまして、この時点で想定事業費も補助金総額も答弁しないというのはおかしいと私は思うのですけれども、もう一回お伺いします。","respondent":"中道都市開発課長","answer":"事業費につきましては、今現在、準備組合の総会等の中で様々議論されているという状況です。区にはまだ正式な報告というのは届いていないという状況です。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問","question":"７億７,７６０万について、皆減した理由を伺います。予算説明書の節の区分の欄に、「補償、補填及び賠償金」と書かれているのですが、これはどういう意味なのか、伺いたいと思います。","respondent":"中道都市開発課長","answer":"今年度、建築設計または権利変換といった形を実施する回答のあったことから予算計上を行ったものですが、予算の皆減を申請したというものになります。補助金等の区分ですけれども、今回、市街地再開発事業の中で、区から補助金を申請するという形で区分しています。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"伺いたいのですけれども、小山三丁目第１・第２地区でも従前評価というのは行われたのか、改めて伺います。こちらの２地区というのは都市計画手続に入って、手続に入るのは区ですけれども、都市計画決定が行われたのか確認したいと求めました。","respondent":"中道都市開発課長","answer":"生活体系を考える際には、やはりそうした視点というのが、非常に地権者の方々が興味を持つ内容であるというところからです。地域の方々が今後進めるか進めないか、またはどのようにまちづくりの将来像を担っていくのかといったところを検討しているという形で進んでいるです。","id":"exchange-024"},{"speaker":"安藤委員","kind":"確認","question":"分かりました。小山三丁目第１・第２地区でも従前評価が行われて、これらの２地区というのは都市計画手続に入って、確認したいと求めました。","respondent":"中道都市開発課長","answer":"準備組合から、そういった形で、小山三丁目第１地区、第２地区ともに、モデル的な権利変換というのをご提示しながら進んでいるということは聞いてあります。","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問","question":"もめて合意にも至らず、前提条件が大きく変わった以上、この都市計画決定そのものを廃止することを考えるべきなのではないかと私は思うのです。廃止すべき、というのも１つの選択肢に入ってくるのではないかと私は思うのですけれども、いかがか尋ねました。","respondent":"中道都市開発課長","answer":"地区内の方々でまちづくりの将来像を検討しながら、またはどのような形で課題を整理していくかというようなところを検討している事業となります。","id":"exchange-026"},{"speaker":"筒井委員","kind":"質問","question":"私からは、３６ページ、特別区民税、特別区たばこ税、３８ページ、特別区財政調整交付金、地方特例交付金など、歳入全般についてお伺いいたします。６９ページの区民保養所経費、９７ページ、武蔵小山駅周辺地区再開発事業についてお伺いいたします。","respondent":"吉野税務課長、加島財政課長","answer":"納税義務者が、当初の見込みが８万６,０００人だったところが８万８,０００人と、２,０００人増になっております。特別区財政調整交付金ですけれども、こちらの伸びにつきましては、今回、調整税３税の伸びが大きかったところです。特別区たばこ税なのですけれども、こちらは実績見合いで減収という形になっております。","id":"exchange-027"},{"speaker":"筒井委員","kind":"質問","question":"ただ、一方で人口減少という問題がありますので、大体どの程度で頭打ちが来るのかということは、お分かりになるでしょうか。示すよう求めました。","respondent":"吉野税務課長、加島財政課長","answer":"そうですね。３０代・４０代の部分が減っておりますが、こちらが増えて、１人当たりのいわゆる税額がかなり増えてきているというような現象になります。今、総合実施計画を策定しておりますが、そこのところが１つのターニングポイントになってくるかと考えております。特例交付金の実績減というところなのですけれども、こちらは減税補填分についての実績減となります。","id":"exchange-028"},{"speaker":"筒井委員","kind":"質問","question":"２０５１年が人口のピークということで、それまでは、やはり増加の傾向が続くのかと思います。では、比較的健全な財政状況、ある程度、余裕のある運営ができるのかと思いますけれども、その辺りのご所見をお伺いいたします。","respondent":"加島財政課長","answer":"それから都区財政調整につきましても、この間、５５.１％から５６％へ、配分割合の変更がございました。少子化と高齢化が同時進行してまいりますので、そこから生じてくる課題というものについて対応できるような財政基盤を築いていかなければならない。","id":"exchange-029"},{"speaker":"筒井委員","kind":"質問","question":"健全な財政を、引き続きどうぞよろしくお願いします。続いて区民保養所について伺いますけれども、今回、７７７万円ほど減になっておりますけれども、その理由を示すよう求めました。","respondent":"宮澤地域活動課長","answer":"今年度、伊東市にあります品川荘につきまして、空調設備の老朽化に伴いまして更新工事を実施したところです。工事の影響によりまして、９月から１月まで休館対応したことによりまして、宿泊助成の実績が減った部分を減額補正しているものです。","id":"exchange-030"},{"speaker":"筒井委員","kind":"質問","question":"３０年程度経っているかと思いますけれども、事務事業評価を見ますと、稼働率が少し落ちているのかと思います。保養所を運営するにあたり、課題というのは何かお考えがありますか尋ねました。","respondent":"宮澤地域活動課長","answer":"委員がご指摘のとおり、品川荘、光林荘ともに、３０年近くの築年数が経ってきているところで、老朽化が進んでいるです。老朽化に伴う更新工事等が必要な時期というのは来ておりますので、そういったところを実施していくのかというところが課題となっているところです。","id":"exchange-031"},{"speaker":"筒井委員","kind":"質問・要望","question":"切りのいいところで、この事業を廃止するということもぜひご検討いただきたいと思っているのですけれども、この点はいかがなのか。","respondent":"宮澤地域活動課長","answer":"今年度につきまして、関係部署が集まりまして、現状や課題の洗い出しというのを進めてきているところです。今後の方向性につきましては、引き続き検討を進めていくです。","id":"exchange-032"},{"speaker":"筒井委員","kind":"質問","question":"続いて、武蔵小山駅周辺地区再開発事業に移りますけれども、７億７,８００万円程度の減の理由。これは、都市開発法の３分の２以上の同意が得られなかったという理由でよろしいのか尋ねました。","respondent":"中道都市開発課長","answer":"今現在、地域の方々が、まちづくりの議論を交わしている最中というところで、まだまだそういったまちづくりを進めるといった形での様々な同意に至っていないということについて、準備組合の報告がございましたので、今回、予算を皆減したです。","id":"exchange-033"},{"speaker":"筒井委員","kind":"質問","question":"不動産価格高騰について、なかなか再開発の同意が得にくくなるという事象が増えてくると思うのですけれども、その辺りはいかがお考えなのでしょうか。これから２０５１年と言いますけれども、その点も含めて、今後の再開発についてどのようにお考えなのか示すよう求めました。","respondent":"中道都市開発課長","answer":"いただいたご意見を準備組合にお伝えして丁寧な対応を取るなど、皆様のまちづくりの中で円滑に進むよう取り計らっていきたいと考えています。地域の方々に今後どのようなまちにしていくのかというところを考えていただきながら、また、丁寧に対応していきたいと考えています。","id":"exchange-034"},{"speaker":"せらく委員","kind":"質問","question":"今後については、今、３施設、開設へ向けて協議をしていらっしゃると先ほどお聞きしました。今年度の受入れ可能数と病児保育利用者数を、前年と比較してお聞かせいただけますか尋ねました。","respondent":"中島保育施設運営課長","answer":"今年度につきましては３施設でございまして、定員が合計１７名、年間の受入れ可能人数が４,０８０人です。実績としましては、１月末現在の数字ですが、１,１１７人という実績です。","id":"exchange-035"},{"speaker":"せらく委員","kind":"質問","question":"ベビーシッターについて続いてお聞きしたいのですけれども、当初予算よりも大幅に、１億円を超える予算を追加しているということになります。区としては、シッターの病児受入れについては、どのようにお感じになっていらっしゃいますか尋ねました。","respondent":"芝野保育入園調整課長","answer":"ベビーシッター利用助成支援事業をご利用いただいて、ベビーシッターを派遣させていただいて、病児保育の対応をさせていただいているのが現状です。","id":"exchange-036"},{"speaker":"せらく委員","kind":"質問・要望","question":"病児保育に加えてベビーシッターを利用するという選択肢が今あるとは思っておりますので、確認させていただきました。病児保育送迎事業として、今、試行実施をしていることを確認しました。","respondent":"中島保育施設運営課長","answer":"保護者の利便性も向上することは十分認識できるところですが、今、それでお預かりするという形にさせていただいているところです。現状の病児保育施設のご意見や、先行の自治体の事例などもお聞きしながら、検討してまいりたいと思います。","id":"exchange-037"},{"speaker":"せらく委員","kind":"質問・要望","question":"一対一の保育という部分を使いやすくしていただきたいと、以前、私も仲間たちと都へ要望したことがあります。多子世帯の利用について、最後、ご答弁をお願いいたします。","respondent":"芝野保育入園調整課長","answer":"ベビーシッター、多子世帯の利用状況ですが、正確な数字は分かりかねるところではあるのですが、令和５年度の実績が、１,８３０人中、大体６００世帯程度、ご兄弟がいる方がご利用されているというような、ざっくりとしたデータですが、当課で把握しています。","id":"exchange-038"},{"speaker":"横山委員","kind":"質問","question":"私からは、６６ページ、人事管理費、１０３ページ、品川図書館職員給与費についてお伺いいたします。１点目に、品川図書館職員給与費についてお伺いいたします。","respondent":"宮尾人事課長","answer":"こちらは、各目で計上させていただいている職員給与費につきましては、まず職員数の変動に対応するものです。その関係で職員数の変動が生じることに対応するもの、それからもう一点が、人事委員会の勧告に伴う給与改定に対応するもの。","id":"exchange-039"},{"speaker":"横山委員","kind":"提案","question":"読書習慣を身につけることによって、より複雑なことに耐える力を育てていくことができるのではないでしょうか。読書離れの根本である、新しい子ども読書推進計画を進めていただきたいと考えますが、区のお考えを説明するよう求めました。","respondent":"河内品川図書館長","answer":"背景ですが、当該計画におきまして、区民の方へアンケートを実施しております。区立学校の５年生と８年生にアンケートを実施いたしました。","id":"exchange-040"},{"speaker":"横山委員","kind":"質問・要望","question":"２点目に、人事管理費についてお伺いいたします。今後も引き続き１４日以上の割合を増やすなど、年次有給休暇の取得促進を進めていただきたいと要望いたしますが、いかがか尋ねました。","respondent":"宮尾人事課長","answer":"一昨年度前、令和４年度が同じく１５.０日、それから１０日以上が７４％でございましたので、若干でありますが向上していると考えます。今後も、休暇の計画的な取得を含め、職員の働きやすい環境づくりに努めてまいりたいと思います。","id":"exchange-041"},{"speaker":"横山委員","kind":"意見","question":"今回、予算特別委員長のお話の中で、「楽しくやっていきましょう」というお話がありまして、私はすごくすばらしいと思いました。何というのでしょう、自己実現やリフレッシュなどの時間、大切なものを大切にしていただくということでお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-042"},{"speaker":"こしば委員","kind":"確認","question":"私からは、９５ページ、下水道管改修事業についてお伺いいたします。答弁は、空洞調査や、ＡＩを活用した路面点検の結果を再確認し、異常がないことを確認したとの答弁であったと認識しております。","respondent":"北原河川下水道課長","answer":"下水道管整備後、老朽化が進んでいるエリアにおきまして、都下水道局が事業を行っているものの一部を下水道局から受託して実施しているものです。工事を実施するに当たりまして、下水道局が実施する下水道管の調査に基づき設計検討を行った結果、減額を行っているものになります。","id":"exchange-043"},{"speaker":"こしば委員","kind":"確認","question":"調査により健全性を確認できたということを理解いたしました。点検により健全性が確認された下水管というのは、点検の頻度を上げていくことも必要ではないかと思いますが、お答えをお願いいたします。","respondent":"北原河川下水道課長","answer":"東京都下水道局で実施しているものでございまして、腐食するおそれが高い下水道管については５年に１度、補修等を行っているものと伺っています。本日出た意見については、都下水道局に伝えてまいりたいと考えております。","id":"exchange-044"},{"speaker":"こしば委員","kind":"質問・要望","question":"その一部を品川区が受託しているですが、やはり東京都との連携が必要不可欠になってくるわけです。品川区で、東京都に対しまして下水道事業の拡充等を要望していると思うのですが、東京都に要望していることについて教えてほしいと求めました。","respondent":"北原河川下水道課長","answer":"東京都への要望についてですけれども、２３区では品川区長が会長となりまして、特別区下水道事業促進連絡会というものを組織しておりまして、浸水対策の実施、老朽化対策の整備促進、耐震化の促進など、要望を都知事宛てに行っている状況になります。","id":"exchange-045"},{"speaker":"こしば委員","kind":"質問・要望","question":"１９５０年代後半から東京オリンピックを過ぎまして、１９７０年代と認識しておりますが、それから５０年、６０年と時間が経過しております。補強工事の進捗、品川区の状況について教えていただきたいのと、また今後の見通しについても併せて教えてほしいと求めました。","respondent":"北原河川下水道課長","answer":"老朽化が特に進んでおります目黒川の左岸側のエリアを中心に事業を進めておりまして、それ以降に実施するエリアで、事業着手に向けた検討を開始している段階と伺っております。","id":"exchange-046"},{"speaker":"こしば委員","kind":"質問・要望","question":"憂慮されております。広報しながわなどありますけれども、そういった媒体を使ってぜひ進めてほしいと求めましたが、見解を教えてほしいと求めました。","respondent":"北原河川下水道課長","answer":"下水道局が進めている事業ということもありますので、今の段階で何ができるかというのはお答えしづらいところもありますが、情報共有をやっていける方法がないかということは検討してまいりたいと思います。","id":"exchange-047"},{"speaker":"こしば委員","kind":"質問","question":"これは本来は民有地のものですので、当然、私道・公道によって不利益を被るということがまた変わってくるというのはおかしいと思います。","respondent":"森建築課長","answer":"私道整備助成の中で、下水道管を直すこともできます。","id":"exchange-048"},{"speaker":"つる委員","kind":"質問・要望","question":"５５ページ、１０５ページ、学校給食無償化について伺っていきたいと思います。品川区の平均世帯所得が分かれば教えていただきたいのと、転入人口ではどういう世代、またどういう所得層の方々が増えてきているのか説明するよう求めました。","respondent":"吉野税務課長、崎村企画課長","answer":"３０代、４０代の方たちなのですけれども、増えている状況です。４０代、４９歳ですと７００人といった形で、大分増えているところです。人口動態の特徴というところで少し補足しますと、品川区は今、人口が増加傾向にあるというところで、その多くが単身者の転入となっております。中でも、２０歳から２９歳の単身者の転入が圧倒的に多いという状況です。","id":"exchange-049"},{"speaker":"つる委員","kind":"提案","question":"２０代から２９歳、提案もさせていただいている中で、ベーシックサービスの展開をやっていただいている。２０代から２９歳のいわゆる若者や単身者、今後どういったことが考えられるのかというところも１つ、伺いたいと思いますとの意見を述べました。","respondent":"崎村企画課長","answer":"２３区、こういったファミリー世帯については、特に近隣３県への転出が増えているような状況です。今後検討をしていかなければいけない部分かとは思いますけれども、令和７年度についても、引き続き検討していかなければいけないと考えております。","id":"exchange-050"},{"speaker":"つる委員","kind":"質問","question":"ある一定の年代となると、やはり対応していかなくてはいけないことなのかなとは思いますので、また別の場所でも伺っていきたいと思います。次に、庁舎管理費に関連してなのですが、エレベーターの保守に関連して伺いたいと思います。","respondent":"佐藤経理課長","answer":"大きい事故があったという経緯も踏まえまして、メーカーに関係するメンテナンス会社を主としまして契約を進めておるところです。長期的・継続的な保守が求められるというところで、随意契約で結んでおります。","id":"exchange-051"},{"speaker":"つる委員","kind":"質問","question":"別表第１の（１９）の、昇降機等の保守についてというところであると思います。金額については、幾らまで随意契約でいけるのか説明するよう求めました。","respondent":"佐藤経理課長","answer":"課長への権限の移譲の部分ですけれども、エレベーターの保守に関しましては、金額ではなくて契約内容に基づいて課長に権限を移譲しているという形です。","id":"exchange-052"},{"speaker":"つる委員","kind":"質問","question":"そういったものが１３０万円とあり、その他だと５０万円などという表示があるのですが、今ご答弁がありました。これは民間企業ですから、時間がないですが、ご提言ほしいと求めました。","respondent":"佐藤経理課長","answer":"繰り返しになりますけれども、エレベーターに関しては非常に安全性が強く求められる設備だと思いますので、今後とも安全をまず第一に考えて、契約形態については考えていきたいと思います。","id":"exchange-053"},{"speaker":"おぎの委員","kind":"質問","question":"品川区のガバメントクラウドの事業者、また移行の進捗と、既に移行した事業部署の状況、今後のスケジュールについてお伺いします。品川区は令和５年度からガバメントクラウドの早期移行団体検証事業公募に参加しておりましたが、併せてお聞きします。","respondent":"横田デジタル推進課長","answer":"令和６年度の標準化といたしまして、住民基本台帳、印鑑、国民健康保険、年金、選挙人名簿管理をガバメントクラウドに移行しております。品川区におきましては、早期移行団体として、この５事業につきまして、国と協力しながら検証しています。","id":"exchange-054"},{"speaker":"おぎの委員","kind":"質問","question":"ありがとうございました。今、移行後の事業は特に問題なく進められているということでよろしいか尋ねました。","respondent":"横田デジタル推進課長","answer":"こちらも、早期移行した５事業につきましては、特に問題なく現在、稼働しております。","id":"exchange-055"},{"speaker":"おぎの委員","kind":"質問","question":"クラウドの事業者はどちらか尋ねました。","respondent":"横田デジタル推進課長","answer":"失礼いたしました。全事業、ＡＷＳを予定しております。","id":"exchange-056"},{"speaker":"おぎの委員","kind":"質問・要望","question":"品川区はＡＷＳということで、アマゾンということを確認いたしました。アマゾンはアメリカの企業であり、アメリカの法律によってアメリカ政府がデータへのアクセスを求める可能性があります。","respondent":"横田デジタル推進課長","answer":"そのため、情報流出の懸念は少ないと考えております。令和７年度中までに参加できるような条件を満たすのであれば、その辺りはクリアできるのかと考えております。","id":"exchange-057"},{"speaker":"おぎの委員","kind":"質問","question":"最後に、国内企業の育成についてお伺いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"吉田委員","kind":"質問・要望","question":"それから４３ページの０歳児見守り・子育てサポート事業、それから６７ページ、情報公開等経費について伺います。制度を何とか使えるようにしていただける方向だといいと思うのですけれども、検討されているのかどうか、その点について伺いたいと思います。","respondent":"芝野保育入園調整課長","answer":"マッチングには対応しておりませんので、利用の申込みをして、今の段階ではマッチングには対応はしていないという状況であります。","id":"exchange-059"},{"speaker":"吉田委員","kind":"質問・要望","question":"登録された方は１００％使っておられるのか、その辺についての分析はどうされているのか、伺いたいと思います。それから、前に質問したときは、しっかり研修をしていると伺っております。","respondent":"石橋品川保健センター所長","answer":"配る配達支援員の方の役割というところの負担というところのお話になりますが、こちらは現在、人数がしっかり足りているところで実施しています。","id":"exchange-060"},{"speaker":"吉田委員","kind":"質問・要望","question":"いい制度にだんだん育っていっているということが確認できました。それで、適切な支援につながっているということであれば、それから支援を受ける方からの評価のお声というのは、今のところ、どうか尋ねました。","respondent":"石橋品川保健センター所長","answer":"２月に利用者アンケートを、本年度の分も実施させていただきました。支援員の方が一人も今、継続していろいろお話を聞けるということで、かなり評価の高いお声はいただいていると認識しております。","id":"exchange-061"},{"speaker":"吉田委員","kind":"質問・要望","question":"１つだけ申し上げておきたいのは、支援につなげることが目的だという、そこだけはぜひ押さえておいていただきたいということを要望しておきます。これはどう考えても理不尽だと思うのですけれども、見解を伺います。","respondent":"與那嶺戦略広報課長","answer":"ただ、こちらも過去の質疑の中でもご答弁申し上げているとおり、まず原則としては、運用上、１か月程度での設定という形で考えているところです。こちらの公開箇所については再度整理していますので、完了次第、お示しできるように進めてまいりたいと考えております。","id":"exchange-062"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひ期限を切ってほしいと求めました。ぜひ、しっかりこの制度をつくっていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"與那嶺戦略広報課長","answer":"おっしゃるとおり、時間がそれぞれかかってしまっているところは、先ほども申し上げたように、大変申し訳ないです。様々制度を運用している他自治体等も含めて、こちらも研究していくべきところかと思ってありますので、こちらについては今後の研究課題とします。","id":"exchange-063"},{"speaker":"吉田委員","kind":"質問・要望","question":"それで、私たちが最終的に求めているのは、期限を切って、書面が出せなかったら、その時点で公開決定としてほしいと思います。しっかりその期日までに弁明書なり再弁明書なりを出していただきたいと思うのですけれども、その辺についていかがでしょう。","respondent":"與那嶺戦略広報課長","answer":"条例に定めてあるとおり、基本的には原則として公開としながらも、公開できない情報というところを個別に定めているところです。超えないというよりは、そこの制度の中で公開範囲が決定されるべきところですので、そこは切り離して考えていくべきことと考えています。","id":"exchange-064"},{"speaker":"吉田委員","kind":"質問・要望","question":"だから、そこが平等でないというのは制度の問題で、公開すべき内容かどうかということと違うのではないですか。非公開の理由があるのだったら、期日も守るべきではないか尋ねました。","respondent":"與那嶺戦略広報課長","answer":"これは先ほども申し上げさせていただいたとおり、時間がかかっているところについては申し訳ないところはあります。今後どのように制度を運用していくかというところについては、他自治体などの運用なども勉強させていただきながら考えてまいりたいと考えています。","id":"exchange-065"},{"speaker":"吉田委員","kind":"質問・要望","question":"それを専門とする窓口があると、私以外にも、情報公開請求をする方たちもそれを求めておられます。そういう窓口をつくっていただきたいと思うのですけれども、そうすると少し整理がつくかと思うのですが、その点についてお考えを説明するよう求めました。","respondent":"與那嶺戦略広報課長","answer":"一方……。","id":"exchange-066"},{"speaker":"のだて委員","kind":"質問","question":"私からは、１０５ページの補助教材費保護者負担軽減事業、８３ページの区立保育園費の育児休業代替等人材派遣について伺います。今回、補正で１,０００万円、減額となっている理由を伺います。","respondent":"柏木学務課長","answer":"補助教材費保護者負担軽減事業の減額の理由ですが、こちらは、当初予算では、各学校・各学年の補助教材費の最高額で予算を計上しています。実際、今年度、執行してまいりまして、上限までいかない学校が当然多くあったという部分で、今回、減額補正をしています。","id":"exchange-067"},{"speaker":"のだて委員","kind":"質問","question":"学校の裁量はあるとは思うのですけれども、学校によって差が生まれているという現状の改善が必要ではないでしょうか。伺います。","respondent":"柏木学務課長","answer":"学校が取りまとめていないというものもありますので、物、学校によって違いはあります。実施して１年がたちまして、現在、学校の意見も聞きながら検討しています。","id":"exchange-068"},{"speaker":"のだて委員","kind":"質問","question":"補正において１億２,０００万円余を増額したということで、その理由と派遣人数は何人なのかを伺います。それで、今年度、育休・産休を取った人数と、病休を取った人数、それぞれの全保育士に対する割合を伺います。","respondent":"中島保育施設運営課長、宮尾人事課長","answer":"こちら、当初は、幼保一体施設も含めて産休代替「等」として、部分休、時短を含めた職員の運営体制などの兼ね合いで、７１人を予定しておりました。現時点で育休を取っている保育士は９３名いるところです。病気休暇に関しましては全体の数字になってしまうのですが、２月の時点で、職員全体でですが、１２２名です。","id":"exchange-069"},{"speaker":"のだて委員","kind":"質問","question":"これだけいる中で産休・育休が９３人いるということで、これは実際に補充できているのかどうか、伺いたいと思います。空いたままという状況になっていないのかどうか、伺います。","respondent":"中島保育施設運営課長","answer":"今回、補正で上げさせていただいた人数は、担任のできる派遣保育士１７名分です。全体としましては、正規職員と派遣、そして臨時的任用職員、そして会計年度任用職員を組み合わせて、全体で区の保育園を円滑に運営しています。","id":"exchange-070"},{"speaker":"のだて委員","kind":"質問","question":"空きがないのかということで伺ったのですが答えるよう求めました。","respondent":"中島保育施設運営課長","answer":"失礼いたしました。空きはしっかり対応し、派遣保育士、会計年度任用職員、臨時的任用を含めまして、しっかりと、穴はないように実施しています。","id":"exchange-071"},{"speaker":"のだて委員","kind":"質問","question":"やはり、分かっている場合は正規で補充するようにすべきだと思いますけれども、いかがでしょうか。少なくとも臨時的任用職員か会計年度任用職員ということで補充すべきだと思いますが、いかがか尋ねました。","respondent":"中島保育施設運営課長","answer":"復帰がなかなか難しかったという場合もありまして、そういうときには派遣を使うなど、柔軟な対応をしています。少し短期間に入るような形の場面もありますが、極力、園に運営の支障がないように対応してまいりたいと思います。","id":"exchange-072"},{"speaker":"のだて委員","kind":"質問・要望","question":"そこはぜひ正規でやってほしいと求めましたし、ぜひ正規を基本に補充してほしいと求めましたし、正規でやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-073"},{"speaker":"中塚委員","kind":"質問・要望","question":"２１日の本会議にて、選択的夫婦別姓について議論を尽くすことを国会および政府に求める意見書が採択され、私は反対しました。訓練実施前から中止を求める意見が区にも寄せられていると伺っております。","respondent":"伊藤災害対策担当課長","answer":"第２会場である、平面からですので人数は確認はできませんでしたけれども、大勢の方が集まっていらっしゃったのかという認識です。「国民保護訓練は憲法９条に反する」、「戦争を起こさせないためには、もっと別のことがあるのではないか」などという声を受けてあります。","id":"exchange-074"},{"speaker":"中塚委員","kind":"質問","question":"救出救助、除染活動とは、品川区の平和宣言に反する事態だとは思わないのか伺います。宣言に反する事態を想定する訓練に品川区は参加すべきではないと思いますが、いかがか尋ねました。","respondent":"伊藤災害対策担当課長","answer":"は訓練の概要ですけれども、今回の訓練想定につきましては、東京都から依頼を受けまして、東京都の想定で実施したという内容です。平素から起こり得るであろう災害に関する地震や風水害といった訓練と同様に必要な訓練だと認識しておりますし、私としては思っているところです。","id":"exchange-075"},{"speaker":"中塚委員","kind":"質問","question":"私が聞いたのは訓練の概要や目的ではなくて、こうした想定が平和宣言に反するものではないかと伺いました。答えるよう求めました。","respondent":"伊藤災害対策担当課長","answer":"ただいまの委員のご質問ですけれども、先ほども申し上げましたとおり、品川区の宣言に反するものではないと感じてあります。","id":"exchange-076"},{"speaker":"中塚委員","kind":"質問","question":"こうした訓練の想定は、まさに平和宣言に反する事態だと私は思いますが、何がどう思わないのか、しっかりお答えください。どう考えても宣言に反すると思いますが、いかがか尋ねました。","respondent":"伊藤災害対策担当課長","answer":"繰り返しになりますけれども、今回、品川区の宣言に反するとは考えておりません。それが、ミサイルの落下であると判明したため、国民保護訓練につながったという内容であると認識しています。","id":"exchange-077"},{"speaker":"中塚委員","kind":"質問","question":"訓練の想定は宣言に反するとはなぜ思わないのか、伺いたいと思います。他国であれ、日本であれ、どの国であっても、宣言に反する事態やその訓練は許されないと私は思いますが、いかがか尋ねました。","respondent":"勝亦総務課長","answer":"非核平和都市品川宣言ですけれども、品川区はこちらの宣言をいたしまして、ちょうど４０年です。恒久的な平和な世界を目指している中でも、そういった現実を見つめるという部分については、非核平和宣言と反するものではないと考えています。","id":"exchange-078"},{"speaker":"中塚委員","kind":"質問・要望","question":"こうしたものへの参加をやめるよう強く要望したいと思います。排除の声もあったのですけれども、それは後日また質問したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-079"},{"speaker":"せお委員","kind":"質問","question":"８５ページ、病児保育新規開設運営補助経費、１０５ページ、就学人口増に伴う教室整備を伺います。施設が減って説明会を行うという流れが昨年あったわけですけれども、それに伴って、品川区病児保育事業実施要綱は変更がありましたか尋ねました。","respondent":"中島保育施設運営課長","answer":"要綱につきましては、１施設閉鎖になりましたので、その閉鎖に伴いまして、見直しています。","id":"exchange-080"},{"speaker":"せお委員","kind":"確認","question":"東京都の令和７年度予算案には、先ほどもお話がありましたけれども、ベビーシッターを活用した病児保育に係る検証事業を新たに実施とあります。","respondent":"中島保育施設運営課長","answer":"その間、しっかり、就労支援の観点から病児保育を進めてまいりたいと考えています。現状周知に努めているところですが、区の独自支援などにつきましては、引き続き考えてまいりたいと考えています。","id":"exchange-081"},{"speaker":"せお委員","kind":"質問・要望","question":"課題の抽出などを進めていただければと、今後のことを要望して、次に移ります。続けて、これは私の中ではここに関連しているのですけれども、校内別室指導のための教室、お部屋などは、全校、準備されている状況なのか尋ねました。","respondent":"荒木学校施設担当課長、丸谷教育総合支援センター長","answer":"こちらにつきましては、本年度予定しておりました第三日野小学校の普通教室増設対応を取りやめたことによるものです。不登校児童・生徒が利用する校内別室指導を行う部屋についてですけれども、専用の部屋がない学校については、会議室やパソコン室、多目的室等を、開いている時間等を工夫しながら活用しています。","id":"exchange-082"},{"speaker":"せお委員","kind":"質問・要望","question":"品川区もそのような考え方と方向性を明確にしてほしいと要望いたします。約１０年ぐらい前の改築が終了した学校などは、示してほしいと考えているのですが、その辺の見解を説明するよう求めました。","respondent":"荒木学校施設担当課長","answer":"昨今は、特別支援教育の充実化や多様な学びに対応できるような室の配置、将来的にも教育施策や区民ニーズの変化に対応できるよう。品川区の学校づくりに関しましても、効果的に外部に発信する手法についても検討してまいりたいと思います。","id":"exchange-083"},{"speaker":"せお委員","kind":"質問・要望","question":"ご答弁にもありましたが、本当に時代に合った、あと児童・生徒に合った学校整備を進めていっていただきたいと要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-084"},{"speaker":"塚本委員","kind":"質問","question":"初めに１０５ページの校庭整備からなのですけれども、これは１点だけ、学校を管理する学校側としての認識というか見解を最初に伺いたいと思います。人工芝のグラウンドの上などで火器を使うということに対して、どういった見解なのか、お伺いしたいと思います。","respondent":"荒木学校施設担当課長","answer":"基本的には人工芝はプラスチック製の素材でできておりますので、火を使うことは厳禁としております。一定程度、そういった際は、人工芝の周辺に火を使えるようなスペースを設けて実施していただいているところです。","id":"exchange-085"},{"speaker":"塚本委員","kind":"質問","question":"続いて７７ページの、戸越地区児童発達支援センター等整備で、２,６００万円の減ということになっています。今年９月開設予定ですけれども、まず、この減額補正の理由を説明するよう求めました。","respondent":"佐藤障害者施策推進課長","answer":"減額補正の内容についてのご質問です。本年９月の開設を見込んでいるところで、設計段階で材料費の物価上昇率等を見込んで予算化していたものですが、工事費が減ということになりまして。","id":"exchange-086"},{"speaker":"塚本委員","kind":"意見","question":"公共事業が多く増額になっている中で、今回減になったというところについて、もう少し詳しいご説明をほしいと求めました。","respondent":"長尾施設整備課長","answer":"近年ですと物価上昇が見込まれますので、その部分に関しては一定の割合を乗じて、予算化するというところで進めております。令和６年度の予算につきましても、発注前の詳細な見積りをした時点で、実際の予算化したときの金額よりも一定程度落ちたというところが実態です。","id":"exchange-087"},{"speaker":"塚本委員","kind":"質問","question":"今後の施設整備で見積りをしていく上で参考になるのであれば、１つの知見として活用していければという思いで質問をさせていただきました。１つ、どういったものをこの施設の中で実現しようとしているのかを、より具体的な形でお伺いしたいと思います。","respondent":"藤村子ども育成課長","answer":"大原児童センターと児童発達支援センターの中でのインクルージョンということでご質問いただきました。学習支援というか、宿題の支援というか、障害の有無にかかわらずご利用いただけるような施設というのを目指してまいりたいと考えております。","id":"exchange-088"},{"speaker":"塚本委員","kind":"質問","question":"いわゆる障害者支援のほうから言うところのインクルージョンというところでのご見解は何かありますでしょうか。そこを少しお伺いしたいと思います。","respondent":"松山障害者支援課長","answer":"大原児童発達支援センターには、いわゆるインクルーシブひろばベルも内包するということになっております。今後、児童発達支援センター内に児童センターも設けることにより、そして地域との交流というものができるような拠点にしていきたいと考えております。","id":"exchange-089"},{"speaker":"塚本委員","kind":"意見","question":"多分、区内初、もしかしたら東京や全国でも珍しい施設になってくるのだと思います。１つの施設の中で、１つの指定管理者によって運営していくという中で、そういった施設としてやってほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-090"},{"speaker":"やなぎさわ委員","kind":"質問","question":"品川区の介護職員居住支援手当なのですけれども、こちらは１億６,０００万円ほどの減額となっております。その理由をお伺いいたします。","respondent":"菅野高齢者福祉課長","answer":"私からは、品川区介護職員居住支援手当の減額の理由をご説明します。執行残が発生するため、今回、減額補正とさせていただきました。","id":"exchange-091"},{"speaker":"やなぎさわ委員","kind":"質問","question":"恐らく想定の７割ぐらいなのかと思うのですけれども、具体的になぜ、執行率というか、申請が７割程度だったのかということの分析というのは、区でされていますか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"約７割ぐらいということなのですが、８月からの実施であったということが、まず１つあります。各事業者にアンケートを実施したときに寄せられた声を確認させていただいたところ、全国規模の法人の場合、実施率が低かったと分析しております。","id":"exchange-092"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"そのほかに例えば、全国規模の事業所は、格差が出てしまうからあえて申請しないということを伺いました。申請を忘れている、取組を強化していただきたいのですけれども、何か今のところでお考えになっているような施策というか方針があるのか。","respondent":"菅野高齢者福祉課長","answer":"このアンケートにつきましても、ポータルサイトを通じて実施させていただいたところ、寄せられたという結果となっております。勤務時間が少なかった、あとは、ほかの職種との関係で支給ができなかったなどの声もいただいております。","id":"exchange-093"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"私が現場で伺っているのと結構、２０時間介護職員であれば、これはオーケーなのです。物すごくいい事業だと思いますので、ぜひこういったところも柔軟に検討してほしいと求めましたけれども、いかがか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"区も、来年度も同じように事業を実施させていただいて、事業者からいろいろな声が今後寄せられると思います。その辺りのところは今後検討していきたいと思います。","id":"exchange-094"},{"speaker":"やなぎさわ委員","kind":"質問","question":"７０歳の高齢の方が、９０代のお母様を介護していて、日曜日にヘルパーがなかなか見つからないのだとお聞きしました。今期の見込みの実績がもし分かれば、お伺いしたいのですが、いかがか尋ねました。","respondent":"松山障害者支援課長","answer":"グループホームの有資格者助成の今期の見込みですが、１事業者・２件です。","id":"exchange-095"},{"speaker":"やなぎさわ委員","kind":"質問","question":"職員１人につき毎月１０万円、非常に事業所としてはありがたいものなのですけれども、やはり申請にハードルがあるです。事業者の声を聞きながら、緩和を検討していただけるとおっしゃっていたのですけれども、その後の状況はいかがか尋ねました。","respondent":"松山障害者支援課長","answer":"要件緩和につきまして検討いたしましたところ、サービスの質を確保する観点から、現行の要件による助成は継続しつつも、加えまして、中・重度の障害者の方が入居をさらに進めるために、来年度から事業所に対する新たな助成を考えることといたしました。","id":"exchange-096"},{"speaker":"やなぎさわ委員","kind":"質問","question":"初耳なのですけれども、ぜひその要件をお伺いしてもよろしいですか。恐らくプレス発表がないと思うので、お願いします。","respondent":"松山障害者支援課長","answer":"中・重度の入居者数、そして障害支援区分に応じて、事業所へ運営費の助成を考えております。区分３の方については月４万５,０００円と、障害支援区分につきまして助成額を設けまして、事業者を支援してまいります。","id":"exchange-097"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"何でプレス発表がなかったのかというのと、周知をしっかりしていただきたいのですけれども、その辺はいかがでしょうか。お伺いいたします。","respondent":"松山障害者支援課長","answer":"この事業につきましては、大変いい事業と自負しておりますが、プレスにつきましては、総合的に区としてプレスしたものですので、今後この事業につきまして周知に努めてまいります。","id":"exchange-098"},{"speaker":"松永委員","kind":"確認","question":"初めに６９ページの区民施設経費、７７７万７,０００円の減額について伺いたいと思います。利用状況の中で、品川区内、そして区外、外国人の方についての統計を取っていれば、そのことについても併せて伺いたいと思います。","respondent":"宮澤地域活動課長","answer":"その後、宿泊者は減少してきておりまして、コロナ前、令和元年は１,８３５名という状況。コロナ後につきましては、一般利用のうち団体に限って貸しておりまして、令和５年度は約８０名という形です。","id":"exchange-099"},{"speaker":"松永委員","kind":"質問・要望","question":"年々、利用状況がよい方向に向かえればいいかと考えていますが、先ほどのご答弁の中で、そうではないということは確認できました。そうしたところのアンケート調査の結果というのがありましたら教えていただきたいのと、そうした理由について、分かれば説明するよう求めました。","respondent":"宮澤地域活動課長","answer":"宿泊されていたり、家族連れで来たりということで、それぞれの目的で旅行をされていると認識しています。アンケートにつきましては、貸付先の事業者で、そのアンケート結果も９割弱がおおむね満足という回答をいただいていると聞いております。","id":"exchange-100"},{"speaker":"松永委員","kind":"質問","question":"そこで、料金設定について伺いたいと思います。誰もが利用できるような施設であるべきと私は考えますけれども、今後、一般の方も利用できるということでよろしいか尋ねました。","respondent":"宮澤地域活動課長","answer":"平日であれば６,５００円という料金設定になっておりますけれども、近隣の宿泊施設と比較しましても、大変安く泊まれる形となっております。コロナ前の時点からも、なかなかそこが難しいとは、事業者からお話は聞いているところです。","id":"exchange-101"},{"speaker":"松永委員","kind":"質問","question":"ホームページ等を拝見させていただきましたが、ホームページのアクセス数については統計などは取られているのでしょうか。ホームページにヒットさせやすくするための口コミなど、区が行える範囲のＳＮＳの活用など、今後の取組についてお知らせほしいと求めました。","respondent":"宮澤地域活動課長","answer":"事業者で、品川荘であればインスタグラムを使って、現地からのお料理の写真等々、発信しています。区といたしましても、ＳＮＳの活用など、効果的な周知の方法については検討していきたいと考えております。","id":"exchange-102"},{"speaker":"松永委員","kind":"質問・要望","question":"次に８７ページの、猫の適正飼養および活動支援事業、６５０万円減について伺います。このことについて、猫の講習会ということを行っていると思いますけれども、どういった内容になるのか尋ねました。","respondent":"赤木生活衛生課長","answer":"今年度につきましては、直近ですと１１月に地域猫の啓発の関係の講習会を実施しております。今週末も第２回目というところで実施する予定で、そういう、そもそも地域猫活動とは何ぞやというところの部分につきましてご説明させていただいて。","id":"exchange-103"},{"speaker":"松永委員","kind":"意見","question":"こうしたトラブルを解決するためには、地域・まちの声と理解というのがとても大事になってきますので、こうした講習会については、町会・自治会でも「やってくれ」という声があれば、ぜひ引き受けていただければと考えていますが、区の考えを示すよう求めました。","respondent":"赤木生活衛生課長","answer":"町会からの要望というところでの講習会の実施ですが、もしご要望等いただけるようであれば、こちらでどのような形で実施していくかについても検討はしていきたいと考えております。","id":"exchange-104","title":"町会・自治会支援"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"最初に５３ページ、コンクリートブロック塀等安全化支援事業についてお伺いいたします。平成３０年から、人命を守るため安全性が確認できない公道の、今お分かりになるのであれば現在までの件数をお示ししてほしいと求めました。","respondent":"森建築課長","answer":"コンクリートブロック塀の助成の目標数値ですけれども、目標は今年度、５０件でございました。実績といたしましては、本日までで３０件となっています。","id":"exchange-105"},{"speaker":"高橋（伸）委員","kind":"確認","question":"安全性の確認ができない、道路沿いのコンクリートブロック塀を確認しながら、できないがあると思うのです。そういうことで言うと、今現在、「今年度は例えば荏原ブロックを、限定してやっています」などという考え方でよろしいのか尋ねました。","respondent":"森建築課長","answer":"品川区内を５区画に分けまして、５か年で区内全域にチラシを配っております。１年当たり約７００枚程度お配りさせていただいて、今までで２,６００枚から２,７００枚、お配りしています。","id":"exchange-106"},{"speaker":"高橋（伸）委員","kind":"確認","question":"職員の方が歩いていろいろとやっていっておられることは確認させていただきました。こういったことをやって取り組んでおられるのならば改めてご答弁をお願いしたいのと、そのオーナーにポスティングをする、その辺はいかがか尋ねました。","respondent":"森建築課長","answer":"教育委員会の教育総合支援センターで行っているとは思うのですけれども、ブロック塀の状態について等を含めて、通学路の安全性を高めてまいりたいと考えています。","id":"exchange-107"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"次に９１ページ、創業・スタートアップ等支援経費についてお伺いいたします。課長も相当、この１年間ご苦労があったかと思うのですけれども、まず最初に感想を述べてほしいと求めました。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"地域も巻き込んで、それから品川区内だけでなく各全国の拠点都市とも連携してやっていくという、結構大きなミッションを掲げてやってきたところです。","id":"exchange-108"},{"speaker":"高橋（伸）委員","kind":"質問","question":"昨年ですか、２０１２年にスタートアップ支援、連携していくということで今後どういうふうにやっていくのか。ぜひとも福岡市だけでなく、今後どういうふうに取り組んでいくのか、方向性をお示ししてほしいと求めました。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"この取組は来年度も継続してやっていきたいと考えております。発信力の高い区長に、そういったところを活用しながら、このスタートアップの取組について幅広く発信していきたいと考えております。","id":"exchange-109"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひ今後、今までの入賞者、参加していただいた方への伴走支援をしていただきたいと要望して終わりにしたいと思います。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-110"},{"speaker":"石田（し）委員","kind":"質問","question":"８３、８５ページ、各保育園運営費について、そして８１ページ、しながわネウボラネットワーク事業についてお伺いします。改めて、いわゆる保育士等の給与アップについて、どのようなものが運営費に盛り込まれているのか説明するよう求めました。","respondent":"佐藤保育事業担当課長","answer":"今、委員からお話しいただきました運営費の増額補正についてですが、こちらは、お話しいただきましたように、処遇改善の加算の増額ということで、４月に遡って各事業者に支払われる分です。","id":"exchange-111"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"今、いろいろ制度改正がどんどん行われている中で、保育園に対するどういった相談体制を区が持っているのか。その辺を説明するよう求めました。","respondent":"佐藤保育事業担当課長","answer":"我々としても、３月に精算を予定しているのですけれども、保育士の処遇を改善するために使うことというのを周知してお知らせしています。制度における相談体制ですが、毎月、何か質問等あった際には丁寧な対応をいつでもできるように体制を整えているところです。","id":"exchange-112"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"相談体制というか、制度が変わったときに区に確認したら、すぐ対応してもらえるというような体制づくりが必要だと思います。特にこういった制度が変わるときはしっかりと対応してほしいと求めましたが、その辺、もう一度ご答弁ほしいと求めました。","respondent":"佐藤保育事業担当課長","answer":"制度の改正というものの背景に、非常に細かい事務作業というのがあるので、それを簡略化したいという国の意向もあります。我々としてもしっかりと丁寧に、私立保育園園長会等がありますので、そうした機会を使いながら丁寧に説明していきたいと考えております。","id":"exchange-113"},{"speaker":"石田（し）委員","kind":"質問","question":"続きまして、ネウボラについてです。品川区が考えるネウボラについて、どのように区として考えているのか説明するよう求めました。","respondent":"染谷子ども家庭支援センター長","answer":"それから児童福祉側の子ども家庭支援センターで、それぞれバトンタッチ型ということで、ネウボラネットワーク全体を構成しています。この４月からは、より連携を強めて、ネウボラネットワーク全体として切れ目のない支援を実施していきたいと考えているところです。","id":"exchange-114"},{"speaker":"石田（し）委員","kind":"質問","question":"「どうですか」と言われたらそうでもないし、相談ができる体制づくりをつくっていかないと、やる意味がないのではないかと思う。ここで改めて、おむつ定期便も含めて、品川区のネウボラ対策というのをどうするのかというのを説明するよう求めました。","respondent":"石橋品川保健センター所長","answer":"私から、妊娠期のネウボラ相談というところのネットワークについてご説明します。妊娠８か月頃の面談や、確かに対応する職員や支援員は違うのですが、専門職と連携を取って実施しているところになります。","id":"exchange-115"},{"speaker":"こんの委員","kind":"質問","question":"私からは、９７ページ、大井町駅周辺地区再開発事業、１０５ページ、校舎等整備、空調改修工事費について伺いたいと思います。具体的に１つ申し上げると、そういう声を聞いたのですけれども、まずその点についてご認識されていらっしゃいますか尋ねました。","respondent":"荒木学校施設担当課長","answer":"こちらは、保護者から学校にご連絡がありまして、学校を通じて庶務課でも認識しているところです。その対応につきましては、フィルターの清掃を実施し、現在は改善されているという認識です。","id":"exchange-116"},{"speaker":"こんの委員","kind":"質問","question":"１,８７０万円減額になっているので、減額というのはどういう状況だったのかというのを、参考までに伺いたいと思います。抜本的に、いずれにしても計画的にされているのは認識しているのですけれども、その辺の工事の内容というのも示すよう求めました。","respondent":"荒木学校施設担当課長","answer":"工事内容ですが、基本的には、全面的にフルリニューアルをする更新工事となっています。耐用年数をおおむね１５年程度と、空調機は計画しているのですけれども、この耐用年数が過ぎたものに関して計画的に改修を進めているというものです。","id":"exchange-117"},{"speaker":"こんの委員","kind":"確認","question":"全面改修という形でリニューアル、しかも１５年程度を経過したものという基準でされているということを確認いたしました。こうしたことが、なかなか修繕に至っていないのかという現状が見えるのですが、その辺のところを説明するよう求めました。","respondent":"荒木学校施設担当課長","answer":"委員がご指摘のとおり、改築を予定している学校につきましては、一定程度、修繕を遅らせた上で改築に進んでいるという状況があります。","id":"exchange-118"},{"speaker":"こんの委員","kind":"質問・要望","question":"その箇所だけの修繕ではなくて、抜本的にやはり替えていかなくてはいけないという現状を、よくよく見極めて対応してほしいと求めました。この点については、いかが考えていますか尋ねました。","respondent":"荒木学校施設担当課長","answer":"は外部からの気温、日射といったところの遮蔽という効果がありますので、現在は改築に合わせて取り組んでいるところです。なかなか取り組むのが難しいという現状はあるのですけれども、可能な限り、対応を検討してまいりたいと思います。","id":"exchange-119"},{"speaker":"こんの委員","kind":"質問・要望","question":"バリアフリーの考え方が国でも示されている中で、品川区としてはＪＲに相談を、また要望を継続していきますということでした。区民の利便性とというところで、さらに要望していくというお考えなのか、その点をもう一度確認したいと求めました。","respondent":"中道都市開発課長","answer":"現在も引き続き、鉄道事業者とは意見交換を交わして、さらなるバリアフリー化について検討しているという状況です。「ＯＩＭＡＣＨＩ ＴＲＡＣＫＳ」が１年後に開業しますけれども、また、新たな歩行者ルートを見ていきたいと考えています。","id":"exchange-120"},{"speaker":"鈴木委員","kind":"提案","question":"この３項目が計上されていないのですけれども、今年度、特にこの３項目が増収になった理由を区としてどう捉えているのかを伺いたいと思いますとの意見を述べました。","respondent":"加島財政課長","answer":"年度途中までの収入実績を見込みまして、令和７年度末までの予測を立てて、最終補正で増額を組んだものです。先ほど減額がマイナス９.５億円、増額補正が６７.２億円、子どもの未来応援基金への積立てなどに活用させていただいているところです。","id":"exchange-121"},{"speaker":"鈴木委員","kind":"質問","question":"一般的な標準税率の、１０％の場合は地方消費税２.２％、このうち品川区に入る消費税分というのは何％なのかを伺いたいと思います。増えているのか、減っているのか、その点についても伺えたらと思います。","respondent":"加島財政課長、吉野税務課長","answer":"この区の収入となるうち、２２分の１０を一般財源、２２分の１２を社会保障の財源として充てしています。こちらは法律に基づく対応です。非課税世帯の件なのですけれども、令和５年度と令和６年度を比べまして、ほぼ一緒の数字になっております。４万３,０００世帯になっております。","id":"exchange-122"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それなので、これだけ今まで近年にない増収になっているわけですから、これは区民に対して還元すべきではないかと思います。今年、打ち切るのではなくて継続ということもできるのではないかと思いますけれども、いかがか尋ねました。","respondent":"吉野税務課長、小林地域産業振興課長","answer":"非課税世帯の割合ですけれども、２０％前後になっております。電気代・ガス代の高騰ということを踏まえまして、政府の激変緩和措置が秋の時期に終了するということになったことも踏まえて対策・実施いたしました。資金繰り支援も含めて、助成金も含めて、進めてまいりたいと考えております。","id":"exchange-123"},{"speaker":"鈴木委員","kind":"意見","question":"この補正予算に対しての態度を表明したいと思います。１１８億円という増収分は、特に貧困で苦しむ方のためにも還元すべきだということで、反対という表明をしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-124"},{"speaker":"田中委員","kind":"質問・要望","question":"９１ページ、８７ページ、産後ケア事業に関連してお伺いしたいと思います。２,２１３億円、令和６年度予算、ウェルビーイング予算１.０の評価をお聞かせほしいと求めました。","respondent":"加島財政課長","answer":"子育て支援、今年度実施した、区民の幸福度が前年度比で７.９％上昇するという成果が得られたものと評価しております。","id":"exchange-125"},{"speaker":"田中委員","kind":"質問","question":"先日、企画経営部長、財政課長から、令和６年度の補正予算案についての説明と、令和７年度の当初予算案の説明を頂きました。私は説明の後に部長にお伺いしたのですけれども、令和７年度は、そこをお伺いしたいと思います。","respondent":"久保田企画経営部長","answer":"これは、プレス発表とは違いまして、詳しくプレス発表の前に事前に説明するという趣旨でやらせていただいたです。そういった意味では我々としましては、プレス発表も含めて、事業の内容も詳しく議会にご説明させていただいたという位置づけです。","id":"exchange-126"},{"speaker":"田中委員","kind":"質問・要望","question":"しっかりと情報発信することで、そういったものに対する理解を得て、そういうことがないように行っていただきたい。区議会事務局の関係でお伺いしたいのですけれども、どういうことからそういう紙面になってしまったのか、お伺いしたいと思います。","respondent":"大澤区議会事務局長","answer":"区議会だよりの内容につきましては、広報会議で検討されて掲載されているものですので、事務局からの見解というよりは、広報会議での決定ということになってあります。","id":"exchange-127"},{"speaker":"田中委員","kind":"質問・要望","question":"議会に対して、あのような新年度予算に対するしっかりとした説明をしたことを、プレスにも発表するという、本来はそうあるべきだと考えています。本来はそうあるべきだと考えていますが、プレス発表の在り方について、お聞かせほしいと求めました。","respondent":"與那嶺戦略広報課長","answer":"プレス発表については、品川区が新年度予算において発表する内容について、メディアを通じて区民や世間に発表していく形です。そういった形でこれまで進めてきたところですので、事前の議会への説明というところ、そちらについては今後の検討かと思います。","id":"exchange-128"},{"speaker":"田中委員","kind":"意見","question":"議事録に載せるということの１つの意味合いもあるのかもしれませんけれども、これは私は、ここで改めて何十分もかけて説明する必要もないとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-129"},{"speaker":"えのした委員","kind":"質問","question":"令和６年度に行われた決算特別委員会でもお伺いいたしましたが、水族館は、魅力ある品川区の施設として価値を高めることが期待されています。今後の進め方を、なぜ見直しをするのか、改めて理由をお伺いいたします。","respondent":"大友公園課長","answer":"この状況を踏まえまして、より効果的かつ効率的な整備運営手法の再検討を実施するものです。見直しに当たりましては、しながわ水族館のより一層の魅力向上に向けて、さらなる民間活力の導入も検討してまいります。","id":"exchange-130"},{"speaker":"えのした委員","kind":"確認","question":"確認が取れました。物価高騰による影響を受けてとのことであるようですが、水族館のリニューアルにおいての影響はどのようなものか、お伺いいたします。","respondent":"大友公園課長","answer":"建設資材の高騰は、３年で約３割増となっております。生物飼育のための設備機器が必要となることから、特注品の設備の割合が大きくなり、物価高騰の影響をより一層受けているところです。","id":"exchange-131"},{"speaker":"えのした委員","kind":"確認","question":"そこでお伺いいたします。リニューアルのオープンはいつ頃になるのか尋ねました。","respondent":"大友公園課長","answer":"は来年度、整備運営手法の検討を行いまして、併せてリニューアルオープン時期を含めたスケジュールの見直しも行う予定です。今後、その検討を踏まえまして、リニューアルオープンの時期など、スケジュールについて結果をご報告したいと考えております。","id":"exchange-132"},{"speaker":"えのした委員","kind":"質問","question":"そこでお伺いいたします。これは課題として、リニューアルオープンを遅らせれば、さらに事業費は上昇するのではないか尋ねました。","respondent":"大友公園課長","answer":"物価高騰を予測することは、かなり難しいところではあります。今後も物価の高騰が続くことも想定されますが、より効果的かつ効率的な整備運営手法を見直すことで、事業費の削減を図っていければと考えています。","id":"exchange-133"},{"speaker":"えのした委員","kind":"質問","question":"今まで人気のあったイルカショーやイルカ展示は行わないとしておりますが、しながわ水族館リニューアルの方向性について見直しをするのでしょうか。ご見解をお伺いします。","respondent":"大友公園課長","answer":"基本的には、しながわ水族館リニューアルの方向性についての内容を変えることは考えておりません。リニューアルに当たっては、方向性で示した内容を、より効果的かつ効率的に実現できる手法を検討してまいります。","id":"exchange-134"},{"speaker":"えのした委員","kind":"提案","question":"質問・提案、また会派視察では、福井県の坂井市の越前松島水族館に伺いました。ご見解をお伺いいたしますとの意見を述べました。","respondent":"大友公園課長","answer":"いただきました体験のご提案などを踏まえまして、引き続き、より魅力のある次世代型水族館の実現に向けて取り組んでまいりたいと考えています。併せて、大井競馬場をはじめとした周辺施設との連携強化を進めてまいりたいと考えています。","id":"exchange-135"},{"speaker":"えのした委員","kind":"質問・要望","question":"そこでお伺いいたします。リニューアルオープンは期待するところではありますが、リニューアルの延長に伴って、現状の水族館はどうなるのか尋ねました。","respondent":"大友公園課長","answer":"水族館の運営上、必要となる維持・修繕等々を行いまして、そのまま運営してまいりたいと考えているところです。引き続き、しながわ水族館の魅力を発信する企画や展示を実施するなど、より魅力のあるしながわ水族館の運営に努めてまいりたいと考えております。","id":"exchange-136"},{"speaker":"えのした委員","kind":"質問・要望","question":"ご答弁ありがとうあります。まだオープン時期も決まっていないということですから、魅力のある水族館の運営を期待・要望して質問をしますが、まだ時間が少し余りましたので。","respondent":"大友公園課長","answer":"しながわ水族館のリニューアルに邁進しています。よりよい水族館になるような検討機会を与えられたというところで、よい水族館になるよう、検討を進めてまいりたいと考えている所存です。","id":"exchange-137"},{"speaker":"若林委員","kind":"確認","question":"７７ページの生活介護については、まずは増額の理由を確認します。","respondent":"松山障害者支援課長、東野福祉計画課長","answer":"私からは、生活介護の増額の理由です。当初は前年度実績の利用者４９６人を見込みまして予算を組んでおりましたが、今後も増える見込みであるため、補正を計上するものです。こちらは、当初の見込みが、月１,５００件の稼働ということで見込んでおりました。現在のところ、令和６年１２月現在で約１,１００件というところで、見込みが少し多過ぎたかというところでの減額となっております。","id":"exchange-138"},{"speaker":"若林委員","kind":"質問・要望","question":"生活介護は既に４９６人の予定を大幅に超えそうだというところで、重症心身障害者のことについて数字をいろいろ確認させてほしいと求めました。","respondent":"松山障害者支援課長、東野福祉計画課長","answer":"重症心身障害者という定義が大島分類という定義で成っておりますので、区分等ではなく、実際に一件一件、ケースを当たりましてお調べしないと、把握できないものです。月対応でいきますと、年間で３７０件設置している、廃止が１７０件ほどあるというような状況となっております。","id":"exchange-139"},{"speaker":"若林委員","kind":"確認","question":"事前の確認が不十分だったかもしれません。こういった１,５００件などという予算立て、件数は、１委託先ではもう無理だと表した答弁なのか尋ねました。","respondent":"東野福祉計画課長","answer":"令和７年度予算は、実は月１,５００件という形で組んでいるところです。今、受託している事業者が今後どういう形で対応できるかというところにつきましても、委託の仕方については考えていければと思っているところです。","id":"exchange-140"},{"speaker":"若林委員","kind":"質問・要望","question":"予算も組まれているということで、また改めて確認するかもしれませんけれども、さらに拡充していくと。それ以外に申請されている窓口というのはあるのか尋ねました。","respondent":"東野福祉計画課長","answer":"支え愛・ほっとステーションで受けているのが１６７件、在宅介護支援センターで受けているのが２０３件という形になってあります。","id":"exchange-141"},{"speaker":"若林委員","kind":"質問・要望","question":"居住する方の安心も含めて、ぜひ広げていっていただきたいサービスの一つだというのも、委員会でご紹介させていただいたと思います。例えば住宅部門との連携で、そういったことの充実・拡充というのも図っていただきたいと要望いたしますが、お考えを説明するよう求めました。","respondent":"東野福祉計画課長","answer":"住宅部門とも連携を取りまして、拡充を図っていければと考えています。","id":"exchange-142"},{"speaker":"西本委員","kind":"質問","question":"誰が子どもの面倒を見るのですか。そのことに関して、この支援について、もう一度答えるよう求めました。","respondent":"中島保育施設運営課長","answer":"病児保育につきまして、やはり最終的には病気のお子さんを保護者の方がご自宅で看病するというのは非常に大事だと思っています。それを両立するという現実もありますので、そこに区もしっかりと対応して、保護者の方の就労支援も含めて施策を進めてまいりたいと考えています。","id":"exchange-143"},{"speaker":"西本委員","kind":"質問・要望","question":"これはどうなのでしょうか。その辺をお伺いします。","respondent":"勝亦総務課長、吉岡政策推進担当課長、平原防災課長、飛田子育て応援課長","answer":"国際友好協会の荏原町への移転についてお答えします。こちらについては個人のプライバシーに関わる部分ですので、報告の時期というのは、来たるべきというところで報告する形になるかと思います。転売されているということについては大変遺憾なものですけれども、法令上、これを止めることはできないものです。子育て世帯へのお米支援プロジェクトの件です。見込みが甘かったかということですが、その分、応募申込み総数が増加したのかなと判断しております。","id":"exchange-144"},{"speaker":"西本委員","kind":"質問","question":"これはおかしくないですか。そういうのをよしとしてやるのか尋ねました。","respondent":"吉岡政策推進担当課長、平原防災課長、飛田子育て応援課長","answer":"公正証書遺言作成の件ですけれども、作成があったからといって直ちに報告するということを申し上げたつもりはございません。１５件のネット販売を確認しておりますけれども、現在の段階といたしましては、１９万世帯分が終了している状況です。今回、お米配布と一緒にアンケートを取った結果、ぜひ食べ盛りの高校生にもという声が多数ありました。","id":"exchange-145"},{"speaker":"澤田委員","kind":"確認","question":"私からは、８３ページ、ベビーシッター利用支援事業費、８７ページ、不妊治療等支援事業についてお伺いしたいと思います。１億円を超える増額補正が行われており、それだけニーズが多いということは、本日、質疑の中で何度も確認されたところであります。","respondent":"芝野保育入園調整課長","answer":"先ほどお答えさせていただきました６００世帯という数値なのですが、国の国民生活基礎調査の家庭の状況を勘案して出した推計値です。２人以上の世帯が全体の５１％ということになっておりますので、兄弟で利用されている家庭のニーズはあるものと認識しております。","id":"exchange-146"},{"speaker":"澤田委員","kind":"質問","question":"１０時まで預かってくださいますが、様々課題があるともお聞きしています。すまいるスクールに合わないお子さんなどについては、どのようにお考えか尋ねました。","respondent":"藤村子ども育成課長","answer":"そういった形で親御さんには来館時にメールが行くような形のシステムも考えておりますので、すまいるスクール双方で、安心安全の環境を提供できればと考えております。","id":"exchange-147"},{"speaker":"澤田委員","kind":"質問・要望","question":"どうしても無理だ、私からの要望として、今後ご検討ほしいと求めました。続きましては、８７ページ、不妊治療等支援事業についてお伺いいたします。","respondent":"若生健康課長","answer":"今年度７月から開始しました生殖補助医療による不妊治療医療費の助成件数が、当初の見込みより少なかったことになります。一方、実際は初年度ということもありまして、半年ほどは実績がそこまで伸びなかったということで、大幅な減額補正に至ったところです。","id":"exchange-148"},{"speaker":"澤田委員","kind":"質問・要望","question":"ぜひこれからも、より一層、この事業の周知に力を入れていただきたいと考えています。例えばＬＩＮＥやしながわこどもぽけっとなどを活用してほしいと求めましたけれども、いかがか尋ねました。","respondent":"若生健康課長","answer":"事業開始時に、周知に努めてまいりましたが、Ｘでも情報を発信しているところです。今後も、ご提案のしながわこどもぽけっとも含めて、積極的に周知に努めてまいります。","id":"exchange-149"},{"speaker":"高橋（し）委員","kind":"質問","question":"３６ページ、歳入で特別区税、特別区民税についてお伺いします。そこで、この数字でまず正しいのかということと、数字のことなのでお分かりになる範囲で、正しいのかお伺いします。","respondent":"吉野税務課長","answer":"委員のご指摘のとおりだと思います。","id":"exchange-150"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"なぜ区民税に占める割合を確認させていただいたかと申しますと、問題は区民税に占める割合がどうかということだと思うのです。区民の皆さんになかなか届いていないということですので、さらに説明して認識していただく手段も必要と考えますが、いかがか尋ねました。","respondent":"吉野税務課長","answer":"委員のご指摘のとおり、５０.９億円というのは看過できない状態です。ＳＮＳも当然なのですけれども、広報でも同じように、ＳＮＳを見られない方に対しての広報をしていきたいと考えております。","id":"exchange-151"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"区民の皆様も今、１２万件ということがありましたけれども、自分ごととして考えていただきたい。そして、易しく分かりやすい内容で図解も入れて広報するべきだと思いますが、いかがか尋ねました。","respondent":"吉野税務課長","answer":"来年度なのですけれども、特設サイトというものを作成する予定でおります。今、委員のおっしゃられた内容につきましても、もう少し分かりやすい内容を加味していきたいと考えております。","id":"exchange-152"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"「２３区として」という人ごとの表現ではなく、難しい用語も使わずに、特別区長会が非常に資料を活用して詳しく調べてきていただいています。その点も含めて表現していただきたいと思うのですが、改めてもう一度、いかがか尋ねました。","respondent":"吉野税務課長","answer":"やはり、何というのでしょうか、この制度自体の周知といいますか、そういったところ。どこが悪いのかといったところも含めて、やはり周知していかなければいけないと考えていますので、分かりやすい内容にしたいと考えております。","id":"exchange-153"},{"speaker":"高橋（し）委員","kind":"質問","question":"様々な広報の方法を、今後も、ＳＮＳという一歩踏み込んだところをやっていただいたので、多くの方に周知されたと思います。今後、区としてどのように対処していくのか、お伺いします。","respondent":"吉野税務課長","answer":"先ほどと答弁が重なってしまいますけれども、今回のふるさと納税についての課題といったところを増やすとともに、あと、品川区としての魅力の発信というところで、いわゆる返礼品といったところの開発をさらに進めていきたいと考えております。","id":"exchange-154"},{"speaker":"高橋（し）委員","kind":"意見","question":"魅力発信ということは、ずっとお話ししていただいているわけですけれども、近々、令和７年度は、令和６年度の金額を経てどういった方向か、もう少し具体的にお話しいただけるとよろしいかと思いますとの意見を述べました。","respondent":"吉野税務課長","answer":"来年度も同じように、区内の企業にまたご協力いただいて、こういった体験型の返礼品を増やす予定です。それから、あと、物に対しての返礼品も増やしていきたいと考えております。","id":"exchange-155"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"２３区、大変な状態になっていることを、区民の方に訴えていってほしいと求めました。これは要望でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-156"},{"speaker":"松本委員","kind":"質問","question":"ただ廃止すべきと言って、そうですか」となるかといったら、今日は少し違う観点からも聞いていきたいと思います。まず理由をお伺いしたいのと、特権的なものについては見直しを検討すべきと考えているのですが、いかがか尋ねました。","respondent":"宮澤地域活動課長","answer":"高齢化が進む中で、利用者の層としまして、７０歳以上の高齢者というのがメインターゲットです。メインターゲット層をより宿泊助成しまして、施設の利用促進を図っていき、保養所に多くの区民の方に泊まっていただくことで稼働していくです。","id":"exchange-157"},{"speaker":"松本委員","kind":"質問","question":"しかも賃金が安いという方たちが大変だと考えていますので、ここはご事情は分かるのですけれども、見直してほしいというのが私の考えです。これは今も同じという認識でよろしいのか、伺います。","respondent":"宮澤地域活動課長","answer":"光林荘の校外学習施設の利用につきましては、おおむね４月下旬から１０月末まで利用されているです。","id":"exchange-158"},{"speaker":"松本委員","kind":"質問","question":"では１週間のうち、移動教室で使われているのは何日かといったら、多分３日間なのです。夏季は林間学校があるので、ほぼ毎日使われているのですけれども、ここは事実でよろしいか尋ねました。","respondent":"柏木学務課長","answer":"移動教室は２泊３日で実施しておりまして、そういう形で実施しておりまして、移動教室を夏季施設で使用している状況です。","id":"exchange-159"},{"speaker":"松本委員","kind":"質問","question":"４月後半から９月ぐらいまでは使っているということなのですが、１１月から翌年の３月までは、休業という形になっています。紅葉がきれいなところですけれども、１１月から休みを取っているのはなぜなのか尋ねました。","respondent":"宮澤地域活動課長","answer":"４月から冬季の部分を含めて、今年度に入りまして４月から１２月までの間に、３００名ぐらいが泊まっているという実績があります。本当に、少人数で泊まられると、全館を稼働しますと光熱費等々がかかりますので、そういったところから団体での利用をお願いしています。","id":"exchange-160"},{"speaker":"松本委員","kind":"質問","question":"今のお話だと、紅葉の時期に団体でも受け入れていないというところは、なぜなのかというのはよく分からないところはあります。これはもう普通の団体客を含めて、受け入れたくないというのが本音ではないかと思うのですが、いかがか尋ねました。","respondent":"宮澤地域活動課長","answer":"運営事業者等をヒアリングする中で、実際、正直なところというところで言われておりますのが、やはりコロナ後、なかなかまとまった団体での利用がないと、やはり収支というのが非常に難しいというところは、お声として聞いているところです。","id":"exchange-161"},{"speaker":"松本委員","kind":"意見","question":"これはもう、区民保養所というよりも、学校の子どもたちのための教育宿泊施設というほうが適切な施設になってくるのではないかと思うのです。これをずっと「区民保養所」と言うと、また少し視点がぼやけてくるのではないかと思いますが、ここはいかがでしょうとの意見を述べました。","respondent":"宮澤地域活動課長","answer":"民間に貸し付けているというところで協定を結んで行っておりまして、その協定の期限というのが令和１０年３月となっております。校外学習施設というところでの利用が多い光林荘というところがありますので、そういったところも含めて検討を進めていくです。","id":"exchange-162"},{"speaker":"松本委員","kind":"質問・要望","question":"今日の質疑で、ほぼ、やはり子どもたちの教育施設なのかなというところが、ある程度分かったのではないかと思いますので、今後の施設の在り方は、また別の機会でやらせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-163"},{"speaker":"須貝委員","kind":"質問","question":"ところで、品川区の新庁舎計画はどうでしょうか。説明するよう求めました。","respondent":"小林新庁舎建設担当課長","answer":"今回、発注時までのいわゆる上昇率というのは一定程度見込んだ形で予算要求していますので、まず発注という観点で申し上げますと。近年の人件費の高騰等につきましては、やはり続いているところですので、一定程度の上昇はあるのかなとは考えてあります。","id":"exchange-164"},{"speaker":"須貝委員","kind":"質問","question":"インフレの進行が速くなったこともあり、もうじき日銀においては金利を上げ、円高にして物価を抑えると私は思います。新庁舎建設は大変高いという状況ならば、私はこの工事を延期するべきではないかと思うのですが、お考えを説明するよう求めました。","respondent":"小林新庁舎建設担当課長","answer":"建設業界で働く方、そこの部分について価格が今後下がっていくというところは、なかなか想定し得ないところかなと思ってあります。そういった観点から申し上げますと、新庁舎につきましても、早く着工して早期に竣工させるということが一番合理的だと考えるところです。","id":"exchange-165"},{"speaker":"須貝委員","kind":"質問","question":"スクラップ・アンド・ビルドですか、お金をきちんと使って、区民のために還元するということを基本としていたわけです。五百億円も増えるだろうと想定できる金額の事業を推し進めるというのは、私は今やるべきではないかと思うのですが、ご見解を説明するよう求めました。","respondent":"小林新庁舎建設担当課長","answer":"これらを進めていく中では、これらを根本的に解決するためには、全面的な建て替えというのが必要だと区としては認識しています。特に建設で働く方々の、そういった中では、早く着工して早く竣工させるということには変わりないと考えているところです。","id":"exchange-166"},{"speaker":"須貝委員","kind":"意見","question":"もう８００億円、１,０００億円に向かっています。でも、皆さんの税金を考えたら、私はそこは考え直すべきだと思うのですが、ご見解を説明するよう求めました。","respondent":"小林新庁舎建設担当課長","answer":"今回の予算の中でも、やはり我々、実施設計を進めていく中で様々広く検討してきたところです。当然これは認識はしていますが、その他もろもろ、老朽化している部分が多々あるところです。","id":"exchange-167"},{"speaker":"須貝委員","kind":"質問","question":"でも、これは３００億円、４００億円を超えても構わないのですか。いいのか尋ねました。","respondent":"加島財政課長","answer":"今、それから安全を確保した上での効率的な施工の実施等によりまして、新庁舎整備課と共に進めてまいりたいと考えております。今申し上げたような透明性の高い事業運営と、それから厳格な予算の管理によって、施工を進めてまいりたいと考えております。","id":"exchange-168"},{"speaker":"須貝委員","kind":"質問","question":"でも、何で役所は進めるのですか。それは自分の金ではないからか尋ねました。","respondent":"小林新庁舎建設担当課長","answer":"お金を無駄にしながら工事発注するつもりはございませんけれども、適切な庁舎を、コスト管理をしていきながら進めてまいりたいと考えています。","id":"exchange-169"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"先日の共産党の代表質問で子どもの国民健康保険料の無料化を求めましたけれども、区は、独自の実施は考えていません」という答弁でした。国は適切ではないと言っていますが、禁止はしていないと思いますけれども、禁止はしていないという認識でいいか、確認したいと求めました。","respondent":"池田国保医療年金課長","answer":"国では禁止していないということでのお答えをしているところでございまして、保険料の賦課につきましては、国の法律によりまして基準があります。それを超えての各自治体での保険料の賦課はいけないということは決まっているところです。","id":"exchange-170"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"これは国がやるべきだと考えているということでしょうか。伺います。","respondent":"池田国保医療年金課長","answer":"特定の対象者にあらかじめ画一的な基準を設けて減免することは、明確に法令違反ではないと。私どもは、こちらのものについては国がやるものですので、国に対する要望までということでさせていただいているところです。","id":"exchange-171"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そして、無料化は２億円ちょっとで実施できるということで、区もそれは答弁されております。そして軽減策を、子育て支援としてしてほしいと求めましたけれども、いかがか尋ねました。","respondent":"池田国保医療年金課長","answer":"まず、なぜ未就学児の保険料について５割しか軽減しなかったかというところがありますけれども、５割軽減というところまでのものでございました。","id":"exchange-172"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"これは求めておきたいと思います。背景には、認定が軽く出るということがあるのではないかと思いますけれども、いかがか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"基金が、令和６年度末基金見込額で２４億円と、見込みよりも保険給付費のほうが少なかったということが大きな原因だと思います。第８期においては、今後は見込みが増えていき、こちらは推測しております。","id":"exchange-173"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですので、ぜひ、しっかりサービスを使っていただきたい。そのためにも認定はしっかり出してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-174"},{"speaker":"大倉委員","kind":"提案","question":"５８ページ、７７ページ、障害者グループホーム整備助成等について伺います。先ほどもご提案がほかの委員からありましたが、区民により分かりやすく周知していってほしいと求めましたので、ぜひとの意見を述べました。","respondent":"大友公園課長、柏木学務課長、吉野税務課長、佐藤障害者施策推進課長","answer":"そちらの収入等と運営の中で検討するというところの手法の中では、ＰＦＩの手法というところもあります。耕地面積の２５％を有機農地とするという大きな方針、それを踏まえ、有機給食を推進する農林水産省の方針があります。来年度なのですけれども、少し答弁が重なってしまいますが、来年度も魅力的な発信を引き続き行っていきたいと思います。こちらは、新規設置による施設整備への補助についてというところでの整備助成になりますが。","id":"exchange-175"},{"speaker":"大倉委員","kind":"質問・要望","question":"使ってもらうのが難しいというところで、より声を聞きながら、使いやすい制度にしていっていただきたいというところを要望します。昨年か、障害のある方が入れるような施設などもぜひ進めていっていただきたいということで、会派として重点要望としても求めてきたところです。","respondent":"柏木学務課長、松山障害者支援課長","answer":"学校給食は文部科学省の、国が定めております摂取基準に基づいて、バランスのよい食事ということで提供しているものです。ただ今後、それをさらにレベルアップできるように、研修等を通じて総合的に進めていきたいと考えています。入居者数と障害支援区分に応じまして、受け入れた事業所へ運営費を助成するものです。こちらの助成を通じて、より重度障害者の方が入居促進できるように進めてまいります。","id":"exchange-176"},{"speaker":"あくつ委員","kind":"質問・要望","question":"具体的な内容を教えてほしいということで、相談者の方に改めて伺いましたところ、ご友人の中からかなりたくさんの意見を集めていただきました。少なくとも大井町以東、東側での設置を求められていますが、交渉において、要望に沿うような立地の施設と交渉されているのか。","respondent":"中島保育施設運営課長","answer":"改めて貴重なご意見をたくさんいただきまして、この事業の重要性を強く認識したところです。２施設が医療機関併設型で、１施設が保育所型で、協議させていただいているところです。","id":"exchange-177"},{"speaker":"あくつ委員","kind":"提案","question":"確認しますと、両方対応の施設が９つ、全ての施設の事前登録がスマートフォン・パソコンによる電子申請で一括で可能になっています。これは、利用者の負担軽減のために、利用の一括登録という導入の検討を、ぜひお願いしたいのですけれども、いかがか尋ねました。","respondent":"中島保育施設運営課長","answer":"お子様のことをお聞きしたり、施設での注意事項などもお伝えするということも兼ねておりまして、行わせていただいております。病児保育施設の意見も聞きながら、今後、課題も把握しながら検討してまいりたいと思います。","id":"exchange-178"},{"speaker":"あくつ委員","kind":"質問・要望","question":"次に、予約システムについても伺います。先ほど申し上げた一括登録とともに、手軽な予約システムの導入をご検討ほしいと求めましたが、いかがか尋ねました。","respondent":"中島保育施設運営課長","answer":"現状、実際にお預かりする際には、クリニックで前日に診療してもらったりという形で、丁寧に今、受入れをしています。利便性の向上・改善につながるというご提案ですので、病児保育施設との意見交換を通じまして、重ねて検討してまいりたいと思います。","id":"exchange-179"},{"speaker":"あくつ委員","kind":"質問・要望","question":"昨年ご要望させていただいて、一律４万円ということで、これでほぼ実質無償化になったのかなと思います。もう一点、昨年ご要望させていただいたのが、今の現況、品川区は償還払いについて。","respondent":"芝野保育入園調整課長","answer":"私立幼稚園補助金の法定代理受領のご質問ですが、法的な問題では特段問題がないということで、クリアされるという形になっております。保護者の経済的負担の軽減や利便性というのを促進する意味からも、各園のご意見をお聞きしながら検討を進めてまいりたいと思います。","id":"exchange-180"},{"speaker":"あくつ委員","kind":"質問・要望","question":"昨年も検討して、やるということだったのですけれども、ぜひこれは一刻も早くやっていただきたい。みんなが足並みそろえて全ての園がやらなければいけないということではないということも確認していますので、残りについては今までと同じですので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-181"},{"speaker":"西村委員","kind":"質問","question":"順番に、６５ページ、基金積立金、その後、１０ページ、民生費、児童福祉費から、子どもの未来応援基金について伺ってまいりたいと思います。国の考え方に基づくものだと思いますが、その背景と保育施設の種別ごとに、どのくらいの規模の上昇が図られたのか答えるよう求めました。","respondent":"佐藤保育事業担当課長","answer":"背景ですけれども、こちらは保育士の処遇改善というのを国が実施していることによりまして、公定価格の単価が増加されたものです。地域型保育事業におきましては、運営費を１億３,０００万円ほど増額としています。","id":"exchange-182"},{"speaker":"西村委員","kind":"質問","question":"さきの文教委員会で子どもの未来応援基金についてのご報告がありましたので、こちらの点を伺ってまいりたいと思います。ヤングケアラー事業などの事業を選ばれた理由と、区民の方からいただいた２５億円という大きなご寄附の活用に向けての使途や計画を説明するよう求めました。","respondent":"藤村子ども育成課長","answer":"より大きい視点から子育て支援を考えまして、支援から抜け落ちている子どもたちにスポットを当てて、特定財源も考慮しつつ検討いたしました。このような事業に充てることで、区全体の幸福度の向上につながると考えておりまして、今後もそういった事業での活用を計画しております。","id":"exchange-183"},{"speaker":"西村委員","kind":"意見","question":"区内事業の中で、この基金をどの事業にどう使うか、優先順位と根拠をもう少しお聞かせほしいと求めました。同時に、廃止によって充当された金額は本来は奨学金目的のものですけれども、こちらをどのようにご活用される予定かを説明するよう求めました。","respondent":"藤村子ども育成課長","answer":"こちらは、経済的に困難を抱える家庭の子どもが進学の道を諦めることがないように支援するという目的から設置された基金です。つきまして、旧基金は廃止と同時に新基金に充当いたしまして、新基金の原資として活用していきたいと考えております。","id":"exchange-184"},{"speaker":"西村委員","kind":"質問・要望","question":"最大３億７,３００万円の支出が見込まれる中で、計算しますと約１０年程度でなくなってしまうのではないかと懸念しております。ほかの事業も始めればさらに早くなる可能性がありますが、基金残高を少しでも維持するために方策があれば、お考えを説明するよう求めました。","respondent":"藤村子ども育成課長","answer":"各年度の予算編成の中で検討しているものですが、１点目として、使用予定のない基金残高の短期債等での運用というのを考えております。基金残高の積み増しを図るというところで、こちらを基軸に、まずは運営していきたいと考えております。","id":"exchange-185"},{"speaker":"西村委員","kind":"質問・要望","question":"運用益の確保やクラウドファンディングも組み合わせて、持続可能な仕組みをぜひ構築してほしいと求めましたが、寄附見込みや、クラウドファンディングで賄える規模なのか、寄附を集めるのか、そんなに集まるのか、どうなのかと思いますが。","respondent":"藤村子ども育成課長","answer":"子育て応援課で実施しておりますクラウドファンディングでも、各種無償化など、先進的な子育て施策に取り組んでおりますので。寄附をするなら品川区というような機運が高まっていけばいいのかなと考えておりますので、そうなるように努めてまいりたいと思います。","id":"exchange-186"},{"speaker":"西村委員","kind":"質問・要望","question":"最後に、最終補正予算書に記載されている令和６年度末基本見込額を見ると、少なくとも令和５年度決算時の現在高を維持していく必要があると考えます。区の基金積立てに関する考え方と今後の見通しを示すよう求めました。","respondent":"加島財政課長","answer":"その目的に応じて積立て・繰入れを行っておりますので、現在高のみをもって即座に財政の悪化を示すものではないと認識しております。区民の不安を解消し、生きづらさを解消いたしまして、幸せの実現に交渉できる施策をやってまいりたいと考えております。","id":"exchange-187"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/619855?Template=document&Id=7001#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":132869,"voices":433}},{"id":"r07-20250305-3","meetingId":"r07-c-budget","date":"2025年3月5日","dateIso":"2025-03-05","committee":"予算特別委員会","time":"午前 ９時３０分～午後 ７時１５分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を173件整理しています。","topics":[{"id":"topic-01","title":"令和７年度品川区一般会計予算","agenda":"令和７年度品川区一般会計予算","exchanges":[{"speaker":"西本委員","kind":"質問・要望","question":"けれども、２月５日の朝には新聞報道がなされております。この説明をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"石田（し）委員","kind":"確認","question":"それも本人に確認をしたのか。本人の意向も何も確認しないで、丁寧な対応ではないと思いますけれども、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"石田（し）委員","kind":"質問","question":"そうであれば、初めにその説明をすればよかったのではないですか。だから、私はそこをきちんと説明をしていただいてからスタートすればいいのではないですかという話ですから、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"石田（し）委員","kind":"提案","question":"そこは丁寧に説明すればいいのではないですかというのが私の提案です。全然それはいいですけれども、今後のことも考えて、やはりしっかりそこは丁寧にしたほうがいいのではないですかというのが私の発言ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"石田（秀）委員長","kind":"質問・要望","question":"ですから、無所属の方が８人いらっしゃる方々に、ご説明をした。これが今日もう１回こういうことがあったときに、お約束はできないけれども、ご意見としていただいておく。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"石田（し）委員","kind":"確認","question":"そもそも動議が出されて、その動議をまずどうするかということも確認をしなければいけないですね。何の説明もなく、そうですかと進めるかと言ったら、そうではないではないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"無所属の人たち、ないではないですか。そこはぜひ確認をしてほしいと求めましたけれども、これを最後にしますから、ぜひ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"こしば委員","kind":"質問","question":"統計は推測する上でも大きな手がかりとなりますので、また幾つか教えてもらいたいと思います。区民税を納めますと、区民の収入と、また、少し高齢化世代の話をしていきたいので、その世代との関連性について教えてほしいと求めました。","respondent":"吉野税務課長","answer":"昨日も少し答弁させていただいたのですけれども、３０歳から５９歳まで、いわゆる５０代までの方たちがかなり増えております。３０歳ですと１,７４８名増、４０歳代ですと１,１００名増、５０歳ですと２２８名増となっている現状です。","id":"exchange-008"},{"speaker":"こしば委員","kind":"質問","question":"世帯との関連性をお聞きしたかったので、そこら辺、分かれば説明するよう求めました。","respondent":"吉野税務課長","answer":"世帯でいきますと、１人世帯の数が大体５８％ほど、１３万８世帯あります。２人世帯が４万７,０００世帯、２０％余の状況です。","id":"exchange-009"},{"speaker":"こしば委員","kind":"質問","question":"平均年収も５５０万円以上で、２人世帯という、行政サービスを比較的受けることが少ない区民が一定数区内にいらっしゃることも確かです。この中で多様な世代には当然にＤＩＮＫｓという方々も含まれると思いますが、その辺り、教えていただけますか尋ねました。","respondent":"崎村企画課長","answer":"子どものいない世帯、ＤＩＮＫｓのご紹介がございましたけれども、当然そういった世帯も品川区に住んでいらっしゃるというふうに認識はしております。","id":"exchange-010"},{"speaker":"こしば委員","kind":"質問","question":"魅力的なまちを考えるに当たりまして、５年前のシティプロモーションを思い出しました。その辺りで、また、人口増加というところで、将来の見通しについて、教えてほしいと求めました。","respondent":"崎村企画課長","answer":"かなり交通の利便性が高いということで、今年度の世論調査においても、「住み続けたい」と回答いただいた率が９割を超えているような状況です。","id":"exchange-011"},{"speaker":"こしば委員","kind":"質問・要望","question":"この課題解消のため、区の取組を求める声もあると思います。現状にそういった住宅、あらかじめ周知をしていくことも必要ではないかなと思いますが、その辺りのお考えを教えてほしいと求めました。","respondent":"崎村企画課長","answer":"様々特有といいますか、子どもがいないことによってスムーズに進まないというような課題が出てくるのかなというふうに認識しております。終活の支援の取組として、社会福祉協議会が実施しているサービスについて無償化を図るですとか、また。","id":"exchange-012"},{"speaker":"こしば委員","kind":"質問・要望","question":"引き続き取り組んでほしいと求めました。品川区で住んでいきたいと思えるようなことにつながってくると思いますので、引き続きよろしくお願いしまして、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"新妻委員","kind":"確認","question":"１３５ページ、１７１ページ、時間がある限り伺ってまいります。なぎさ会館が廃止を検討していくということを表明されたのは、この事務事業評価の結果についてが初めてかどうかということを確認したいと求めました。","respondent":"築山戸籍住民課長","answer":"なぎさ会館の廃止の方向性については、今回の事務事業評価の結果が最初です。","id":"exchange-014"},{"speaker":"新妻委員","kind":"質問","question":"１つの区の施設が廃止していくということはとても大きいと考えていますので、具体的に１つ１つお聞きしたいと思います。最後に、経費増加を鑑みて、本事業は３年以内に廃止を検討とありますが、具体的にどのように検討が進められていくのか示すよう求めました。","respondent":"築山戸籍住民課長","answer":"併せて保冷庫も、現在、２４個ありますが、令和１２年度に４４個となる予定です。進め方につきましては、検討会を実施し、丁寧に進めていきたいというふうに考えております。","id":"exchange-015"},{"speaker":"新妻委員","kind":"質問・要望","question":"３年間かけて検討ということですので、具体的にいつぐらいに検討会を立ち上げてということをお考えなのか。そしてまた、議会への報告はどのようにしていただけるのかお知らせほしいと求めました。","respondent":"築山戸籍住民課長","answer":"検討会につきましては、早ければ年度初めの４月以降にスタートさせたいと考えています。３年以内ということで事業評価はしておりますが、時期につきましては、状況を見ながらもう少し早い段階での判断ということも考えております。","id":"exchange-016"},{"speaker":"新妻委員","kind":"質問・要望","question":"３年間という検討期間を示されましたけれども、場合によっては、早く閉鎖ということもあり得るということを確認させていただきました。丁寧に進めていただきたいことを要望いたしまして、この質問を終わりたいと思います。","respondent":"五十嵐保健予防課長","answer":"男性のＨＰＶワクチンの１月末現在の接種につきまして、まずご説明します。詳しい情報などは、国や東京都なども上げておりますので、ホームページのほうにリンクなどを張って周知はさせていただきたいと考えています。","id":"exchange-017"},{"speaker":"ひがし委員","kind":"質問・要望","question":"１２７ページ、１２９ページの東京ユースヘルスケア推進事業、青少年育成活動について伺います。１０区の区長とともに同性パートナーに関する権利や制度等の検討を求める要望書を総務省および厚生労働省に申し入れを行ったと把握しております。","respondent":"築山戸籍住民課長","answer":"昨年９月に、事実婚と同様の表記をした長崎県大村市に対して、再考を求めるよう国の見解が示されました。そのため、区が独自に続柄を設定することは困難であるという判断をせざるを得なくなったために、今回、国の要領改正等の要望をしています。","id":"exchange-018"},{"speaker":"ひがし委員","kind":"質問・要望","question":"この続柄だけではなくて、制度としても整っていないというところで、国にもしっかりと伝えていっていただきたいなというふうに思っております。今後も継続して、同性カップルの権利獲得に向けて行動を起こしてほしいと考えていますが、今後の展開についても説明するよう求めました。","respondent":"築山戸籍住民課長","answer":"今後の展開です。国の動向に注視するとともに、他自治体とも情報共有を図りながら、区としてできることについて考えていきたいと考えております。","id":"exchange-019"},{"speaker":"ひがし委員","kind":"質問・要望","question":"前回の決算特別委員会でも区としてできる取組をということで幾つか要望していますので、総務費の際に再度確認をさせてほしいと求めました。どのような結果が出て実施するに至ったのか、また、モデル校の３校はどこを予定しているのか伺います。","respondent":"藤村子ども育成課長","answer":"そういった場で２回ほどしっかり課題を伺った上で、ご説明の上、進めているような形になっております。こちらにつきましては教育委員会と連携して、居場所の状況のみならず、通学の際の安全配慮にも努めてまいろうというふうに考えております。","id":"exchange-020"},{"speaker":"ひがし委員","kind":"質問・要望","question":"配置の基準としては、校門に１人、居場所に２人、委託業者を配置するとなっておりますが、朝食の提供は誰が行うのでしょうか。利用する生徒の想定人数についてもお伺いいたします。","respondent":"藤村子ども育成課長","answer":"例えば、トラブルがあった場合に対応していくというところもありますので、庁舎等からの距離感も踏まえて決定していきたいと考えています。多いときでも２０人ぐらいいらっしゃるというようなものがございましたので、現在のところ、２０人想定というところで考えております。","id":"exchange-021"},{"speaker":"ひがし委員","kind":"質問","question":"食の提供に対する事故発生時の対応はどのようになっているのかお伺いいたします。食事提供する際のエピペンの配置、使用方法の指導も必須だと考えていますが、区の見解を伺います。","respondent":"藤村子ども育成課長","answer":"今回の委託でやっていくに当たりまして、そちらについての研修をしっかりやっていこうというところで考えております。そういった危機対応のところにつきましては、そちらを今回の委託会社とも共有していければというふうに考えております。","id":"exchange-022"},{"speaker":"ひがし委員","kind":"質問","question":"委託先がもしどこか決まっているのであれば、そちらもご共有をお願いいたします。小一の壁に対して対応するならば、参加人数によって増員も検討する必要があると考えますので、その点について区の見解を伺います。","respondent":"藤村子ども育成課長","answer":"増員につきましては、今回、事業を実施するに当たって、各学校と個別にお話ししていくことになります。そういった状況を考慮しつつ、各学校の個別の状況に対応して、増員等も柔軟に考えていきたいというふうには考えております。","id":"exchange-023"},{"speaker":"ひがし委員","kind":"確認","question":"委託先はこれからということで確認をさせていただきました。時間がありませんので、後半の部分については、またほかの款のときに質問します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問・要望","question":"やはり使用料を払って使っているわけですから、伺いたいのですが、苦情や改善を求める声は届いているのでしょうか。それとあと、点検して普通にマイクでしゃべったら、その声が聞こえるように必要な改修をするよう求めますけれども、いかがか尋ねました。","respondent":"小林地域産業振興課長","answer":"それについては施設のスタッフにお問合せいただくと、そちらのほうで設定変更ですとか、音量の変更というものも対応しています。そういうような必要性があるかどうかということも含めて、引き続き対応も考えていきたいと思います。","id":"exchange-025"},{"speaker":"安藤委員","kind":"確認","question":"ここで１月２６日に自衛隊防災フェア、自衛隊防災フェアですから。伺いますけれども、品川区の後援の有無、水族館の会場使用料は誰が負担しているのか伺いたいと思います。","respondent":"大友公園課長","answer":"平成３０年からの実施となっておりますが、一時開催していない期間がありますけれども、計５回の開催となっています。イベントの当日は、トウチ君のグリーティングに合わせまして、しながわ水族館の公式キャラクターによるグリーティングを実施しています。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問","question":"館内全体貸切か、一部のスペースか、区民公園の公園部分はどうだったのか伺いたいと思います。併せて、当日、自衛官募集のチラシやグッズの配布などはあったのか伺います。","respondent":"大友公園課長","answer":"の交流をきっかけに、しながわ水族館のほうでも実施をという話が進み、実施されていた経緯があるです。水族館の前のところのイベントスペースを使って実施をしたものです。","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問","question":"戦車に乗っているという話も聞きましたので、そこら辺の内容をお伺いします。迷彩服の試着と防災意識向上とどのような関係があるのか伺います。","respondent":"大友公園課長、伊藤災害対策担当課長","answer":"ＶＲ体験の内容ですけれども、上空から降下する映像体験と、戦車内に乗った映像体験の２種類があります。こちらは、自衛隊による災害時の活動状況への理解も深めていただき、区民の防災意識の向上につながったと考えているところです。ただいまの答弁に加えまして、区民の防災意識の向上ということでは、やはり自衛隊の皆さんは、災害時にも防災活動に活躍されるということもございまして、この部隊で一緒に活動されたと伺っております。","id":"exchange-028"},{"speaker":"筒井委員","kind":"質問・要望","question":"一般会計予算の１％、約２０億円の財源を捻出されたということで、本当に求められているものに充てていくということが必要だと考えています。いろいろ工事の関係とか、ぜひお示しをいただきたいと思っているのですけれども、この点はいかがお考えか尋ねました。","respondent":"吉岡政策推進担当課長","answer":"５つの項目をお示しいたしまして、約３０項目、それぞれ削減額は幾らかというところでお示しをしたところです。職員の負担軽減、こういった部分も兼ね合いながら、引き続き分かりやすいお見せの仕方については工夫をしていきたいというふうに考えております。","id":"exchange-029"},{"speaker":"筒井委員","kind":"質問・要望","question":"区民の方からのご要望もあったのですけれど、それと事務事業評価シートとのひもづけをしていただきたいということです。事務事業評価のページのＰＤＦにリンクをつけていただきたいということなのですけれども、そうしたことについていかがお考えか尋ねました。","respondent":"吉岡政策推進担当課長","answer":"区民の皆様に事務事業評価の結果を分かりやすくお示しする、これは非常に重要なことだと考えています。そういったシステムの改修ですとか技術的なところもありますので、どのようなことができるかは、引き続き検討していきたいと思います。","id":"exchange-030"},{"speaker":"筒井委員","kind":"質問","question":"理由としまして、昨日の令和６年度最終補正のところでもご答弁があったとおり、特別区民税などの税収増ということも１つ理由なのでしょうか。そうしたら、今、比較的余裕のある財政状況なのかをお伺いいたします。","respondent":"加島財政課長","answer":"なので、システム標準化というものが、この令和７年度に充てた理由ということになります。それから特別区交付金の伸びがございましたので、今回、２,３４７億円の予算を組むことができたというふうに考えております。","id":"exchange-031"},{"speaker":"筒井委員","kind":"質問・要望","question":"関連しますけれども、就職氷河期世代の方、様々５つの想定するライフステージに当てはまらない方がいらっしゃいます。その点、いかがお考えか尋ねました。","respondent":"崎村企画課長","answer":"施政方針でも示している５つのライフステージのご紹介がございましたけれども、また、所得制限なく提供するというものです。高齢者、行政としての施策をしっかりと行っていける財源を確保するといった観点で施策を進めているところですので、ご理解いただければと思います。","id":"exchange-032"},{"speaker":"筒井委員","kind":"提案","question":"本当に皆さん、５つのライフステージのカテゴリーに当てはまることがあるかと思います。区長の考えられた５つのライフステージというのは、ここは支援の１つの例としてご提案したいのは、いかがお考えか尋ねました。","respondent":"加島財政課長","answer":"区が独自で行政を進めていくために必要な財源でして、税金につきましては、区でも国に対しまして不合理な税制改正を訴えている最中です。今の収入が欠かせないと考えておりますので、一律、一足飛びに減税とは今は考えておりません。","id":"exchange-033"},{"speaker":"筒井委員","kind":"質問・要望","question":"本当にこれをどう一律公平に、不公平感をなくしていくのかということがこれから必要だと思いますので、ぜひお考えいただきたいと考えております。例えば、しながわ水族館で導入するなどありますけれども、ネーミングライツについて、いかがお考えか尋ねました。","respondent":"加島財政課長","answer":"１つの収入の確保手段として依命通達にネーミングライツの例を出させていただいたところです。委員から、しながわ水族館という例もいただきましたけれども、今後何ができるかということは考えていく余地はあるかなと考えています。","id":"exchange-034"},{"speaker":"せらく委員","kind":"質問・要望","question":"次年度は、６,７５０万円の補助金を利用予定となっておりますが、こちらは何園分か内訳を教えてほしいと求めました。区立幼稚園の実績報告が２月、報告についてはホームページで公開されるということでしたが、こちらのスケジュールも説明するよう求めました。","respondent":"中島保育施設運営課長","answer":"令和７年度につきましては、区立が５,７００万円、公設民営が１,０５０万円ということで計上させていただいているところです。幼稚園の件でお尋ねいただきましたが、保育園も含めまして、３月の下旬には公開していきたいというふうに考えてあります。","id":"exchange-035"},{"speaker":"せらく委員","kind":"質問","question":"聞き方が悪かったかもしれないですけれども、何園分、施設数を教えてほしいと求めました。事例を動画で紹介しているものを見かけまして、品川区でもそういった紹介をしていく予定でしょうか、説明するよう求めました。","respondent":"中島保育施設運営課長","answer":"当初、令和６年度は８６園で予定しておりましたので、それより１４園増えているところです。ホームページで考えておりますが、その他の効果的な手法につきましては、今後考えてまいりたいというふうに思っております。","id":"exchange-036"},{"speaker":"せらく委員","kind":"確認","question":"合計１００園になるということで確認いたしました。区でまとめているものとしては入っていないと思うのですけれども、園独自で利用されたなどの実績は把握されていますか尋ねました。","respondent":"佐藤保育事業担当課長","answer":"すくわくプログラムにおきます私立幼稚園および認可外保育施設においての実施ですけれども、まず、認可外保育施設は対象外となっています。区としては、実施を周知はしたということは聞いているのですけれども、どの程度の園が参加されているのかについては把握しておりません。","id":"exchange-037"},{"speaker":"せらく委員","kind":"質問・要望","question":"こちらは歳入のところに記載があるものなので質問させていただきたいと思うのですが、過去に過料を徴収したことがありますでしょうか。取り締まる方法について、誰がどこで、時間帯、何時くらいで行っているのか、そういうところの想定を伺いたいと思います。","respondent":"河合生活安全担当課長","answer":"しかしながら、今、段階を踏んでのことですので、いまだこれまでに徴収実績はございません。時間帯につきましては、おおむね１８時から２２時までの間、適宜行っている状況になっております。","id":"exchange-038"},{"speaker":"せらく委員","kind":"質問","question":"こちらは条例で定めていて過料を示しているから、毎年予算案にも載ってくるものなのかなという認識なのですけれども、間違っていたら教えてください。この条例の制定のきっかけと、あと、過料を定めているところの理由はお聞きできますか尋ねました。","respondent":"河合生活安全担当課長","answer":"歳入のほうに記載されておりますのは、委員おっしゃるとおり、条例で定めておりますので、１件というところで計上しているものです。","id":"exchange-039"},{"speaker":"せらく委員","kind":"質問","question":"法令の規制がかからない部分を区でやっているということなのですけれども、区でもやったことで、発生件数だったり、区民からの意見に変化がありましたか尋ねました。","respondent":"河合生活安全担当課長","answer":"都内の盛り場の中でも五反田地区につきましては、ない地区としてなっておりますので、やはり一定の効果があるものと認識しております。","id":"exchange-040"},{"speaker":"せらく委員","kind":"確認","question":"令和４年辺りから、周辺環境の改善が見られるということを確認できましたので、これで質問は終わりたいと思います。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"横山委員","kind":"質問","question":"私からは、１０１ページ、感染症予防費、時間があれば、同ページの地域生活支援事業費についてお伺いいたします。１点目に、感染症予防費についてお伺いいたします。","respondent":"五十嵐保健予防課長","answer":"ホームページ等では、区内の感染症の発生状況を品川区内の医療機関から報告いただく感染症法に基づく感染症発生動向調査を実施しておりますが。東京都内などで感染症の流行などが見られた際には、区のホームページやＳＮＳ等でも周知を行っているところです。","id":"exchange-042"},{"speaker":"横山委員","kind":"質問・要望","question":"非常時の感染症対策についてもお伺いします。平時から換気への意識および空気清浄機を含めた避難所の環境整備が求められる。","respondent":"五十嵐保健予防課長、羽鳥防災体制整備担当課長","answer":"そこで、院内感染対策に留意しつつ、面会を実施する流れの例示を示し、可能な範囲で工夫して面会の対応を検討するよう通知をしているところです。区内の主要医療機関の面会制限の現状につきましては、区としては把握しておりません。現在、各避難所に大型の扇風機２台を備蓄しています。さらに、来年度以降、導入を予定しております温風機能つきのサーキュレーター、こちらは空気清浄機能がついたものを検討しています。","id":"exchange-043"},{"speaker":"横山委員","kind":"質問・要望","question":"避難所のほうについては、温風のサーキュレーターに空気清浄機の機能がついているということで確認できました。区民への被害の最小化を図ってほしいと考えますが、また、今後の対策について区の見解をお伺いいたします。","respondent":"豊嶋生活福祉課長","answer":"私からは、生活に困っている方の現状についてご説明させていただきたいと思います。自立相談支援員という専門の職員を配置して、それから不安等々の解消についてお伺いして、適切な支援につなげているところです。","id":"exchange-044"},{"speaker":"横山委員","kind":"質問・要望","question":"最後、時間がありませんが、途中まで質問したいのですけれども、２点目に、地域生活支援事業費についてお伺いいたします。当事者研究の取組を進めていただきたいと考えていますので、今日は要望だけします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"せお委員","kind":"確認","question":"１３１ページ、１４７ページ、とうきょうすくわくプログラム、１４７ページ、エデュケーションアシスタント配置支援事業補助金を伺います。３点目、こちらは、園とかの職員だけで、準備から実施、報告とかを行っているのか尋ねました。","respondent":"中島保育施設運営課長、中谷指導課長","answer":"保育園のところについて、まず説明します。区立幼稚園の二葉幼稚園で行いました、やわらかさのボールに触れたり、子どもたちが繰り返し行うことでわくわくを重ねることができたと。移動水族館みたいなもの、そういうところを取り組んでいる園もありまして、ふだんできない探求活動ができているというふうに認識しております。","id":"exchange-046"},{"speaker":"せお委員","kind":"提案","question":"今回も提案するのですけれども、１４７ページのとうきょうすくわくプログラムが、保幼小連携推進事業となっているのです。１点、しっかり計画を今後立てていただきたいなと思うのですが、そこら辺の見解を説明するよう求めました。","respondent":"中谷指導課長","answer":"参考とするというところが１つと、保育園の連携というところでは、合同研修を行うなどして保幼小連携の土台をつくってきたところです。区内の幼稚園、また保育園に対しても、共有を図っていくというところをやってまいりたいと考えています。","id":"exchange-047"},{"speaker":"せお委員","kind":"質問・要望","question":"学習のところを幼少期から進めていくと決まったわけであれば、やはり切れ目のない継続性のある計画的な支援を考えていただきたいと要望いたします。時間がなくなってしまったので、エデュケーションアシスタントについては、どこかの款で触れします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"つる委員","kind":"質問","question":"５６ページ、１４７ページ、公立学校給食費負担軽減事業補助金について伺いたいと思います。ここについて、事業者としても収支上いいのかというところがあると思うのですが、この辺の今の割合について説明するよう求めました。","respondent":"佐藤経理課長","answer":"自動販売機の各施設における設置にかかりまして、経理のほうでまとめて１２月に公告しまして、一番高い金額をつけた自販機のベンダーが落札して設置するという仕組みになっております。","id":"exchange-049"},{"speaker":"つる委員","kind":"質問","question":"その辺も伺おうかと思ったのですが、通常より少し高めで、それで来年度については１,０８５万円ぐらいを見込んでいるというところがあると思います。品川区で１４５台、災害救助ベンダーになっている台数は、何台中何台なのか説明するよう求めました。","respondent":"佐藤経理課長、川崎土木管理課長","answer":"全体の台数につきましては１４５台ということで委員よりご紹介がありました。先ほど委員おっしゃいましたように、都市公園法第５条の公園施設設置許可により土木管理課で設置の許可をしております。行政財産の貸し付けの部分については、災害対応をする自販機を条件にしておりますので、対応しております。","id":"exchange-050"},{"speaker":"つる委員","kind":"質問・要望","question":"昨年でしょうか、それがしっかりと協定に基づいた災害時に活用できるかどうかというようなところも含めて教えていただきたいのと、例えば。自動販売機、これは災害時の支援ベンダー前提ですけれど、設置の拡大についての考え方も説明するよう求めました。","respondent":"佐藤経理課長、川崎土木管理課長、大友公園課長","answer":"貸付けで設置しておるところにつきましては、災害時の対応といたしましては、発災時にはそちらのほうで対応するという対応をとっております。原則、新規設置、また改修を伴う自販機については災害対応とするということで締結の中に盛り込んではあります。公園に対して増設の一定の考えなのですけれども、広い面積で一定滞在が長くなるような公園に現在設置しています。","id":"exchange-051"},{"speaker":"つる委員","kind":"質問","question":"もう１つの質問については、国がどういう基準を設けてくるか分かりませんけれども、教育費とかでいろいろ伺っていければなというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"おぎの委員","kind":"質問","question":"１３５ページ、１４７ページ、学校給食費負担軽減事業補助金についてお聞きします。参加する枠組みとしては、こちらのみどりの食料システム戦略でお間違いはありませのか尋ねました。","respondent":"柏木学務課長","answer":"昨日答弁させていただきました農林水産省の取組につきましては、先ほど委員お示しのみどりの食料システム戦略で間違いございません。","id":"exchange-053"},{"speaker":"おぎの委員","kind":"質問","question":"品川区立の小学校が約１万８,０００食、中学校が約５,５００食、どちらから仕入れるのかお聞きします。有機給食については、量と質を担保する目的ではないとのご答弁でしたが、成長期、食べ盛りの小中学生にしっかりと量も担保されるのかお聞きします。","respondent":"柏木学務課長","answer":"直ちに丁寧な説明や意見交換を行い、市場の動向や現実の実態に耳を傾けながら、円滑かつ持続可能な供給が図れる方策を検討してまいります。過去５０円程度引き上げてありますし、来年度につきましても引き上げの予定ですので、そちらのほうで質、量の担保をしていく考えです。","id":"exchange-054"},{"speaker":"おぎの委員","kind":"質問・要望","question":"１人で無言で食べるのか、いろいろな角度から子どもたちのおいしいということを検討してほしいと求めましたが、いかがでしょうか。お考えを説明するよう求めました。","respondent":"柏木学務課長","answer":"単一的な食品だけではなくて、やはり様々な食育という観点からも進めているところです。そういう部分については、栄養士、調理する方の研修等を通じて実施していきたいと考えています。","id":"exchange-055"},{"speaker":"おぎの委員","kind":"意見","question":"見守りおむつ定期便も、それぞれ毎回違う人がやってくるというと、しっかり伴走しようと……との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-056"},{"speaker":"吉田委員","kind":"質問","question":"ひがし委員も質問させていただいていて、私の質問は、まずは居場所のことを伺います。居場所についても、今、モデル事業として３校を調整中ということで理解してよろしいか尋ねました。","respondent":"藤村子ども育成課長","answer":"居場所の試行についても３校ということで結構です。","id":"exchange-057"},{"speaker":"吉田委員","kind":"質問","question":"もう３月で、４月から事業開始、最初のモデルとして調整中のところとの契約はもう進んでいるということなのでしょうか。それについて伺いたいと思います。","respondent":"藤村子ども育成課長","answer":"契約に向けて準備を進めているというところですので、どういった仕様にしていくかというところを検討している内容になっております。こちらは子ども育成課のほうで進めていく事業ですので、学校と事業者ではなくて、あくまで区と事業者の契約というような形になっております。","id":"exchange-058"},{"speaker":"吉田委員","kind":"質問","question":"区と事業者との契約ということで、そうすると、事業の責任主体といいますか、それは、例えば、現場での責任がありますよね。そこは、やはり現場での責任を誰が負うかということは決めておく必要があると思うのですけれども、その辺の検討はどうなっていますか尋ねました。","respondent":"藤村子ども育成課長","answer":"事業を検討するに当たって、学校側ともお話ししする中で、やはり責任の所在ですとか、そういったところは議論の俎上に上がったところです。こちらの一義的な責任は子ども育成課という形で考えて事業展開してまいろうと考えております。","id":"exchange-059"},{"speaker":"吉田委員","kind":"質問","question":"子ども育成課が最終的な責任は負うということは分かるのですけれども、毎日の現場の責任者は、どういう形になるのでしょうか。受託した事業者としても少し不安が残るかなと思うのですけれども、その辺についていかがか尋ねました。","respondent":"藤村子ども育成課長","answer":"当初の何かトラブルがあったときの対応は、現場で対応し切れない問題に関しましては、すぐ対応できるような体制を整えてまいりたいと考えております。","id":"exchange-060"},{"speaker":"吉田委員","kind":"確認","question":"よく把握できていなくてということで少し混乱が起きているので、この朝の居場所現場ではなくて、学校現場の声はどのように確認されているのか。その内容は、今後、締結される契約の中にきちんと反映されているのか、その辺についても確認したいと求めました。","respondent":"藤村子ども育成課長","answer":"先ほども答弁させていただいたのですけれども、学校のほうには、校長先生全体が参加する会で１回説明させていただいています。１１月で説明させていただいて、全体校長会の中で説明させていただいて、その上で事業の進捗を図っていきますというようなお話をしています。","id":"exchange-061"},{"speaker":"吉田委員","kind":"質問","question":"ふざけたりして、けがとかもあると思うのですけれども、そういうときの対応はどうするのでしょうか。その方たちに負担をかけるべきではないのではないかと思うのですけれども、いかがか尋ねました。","respondent":"藤村子ども育成課長","answer":"学校のほうで新入生に向けての説明会ですとか、保護者への説明会が、そのように既に対応しています。先ほど、子ども育成課で全て対応というところで申し上げたのですが、朝の居場所事業も展開してまいりたいというふうに考えているところです。","id":"exchange-062"},{"speaker":"吉田委員","kind":"質問・要望","question":"これだけの人員の配置が必要だというふうになれば、子どもの安全を確保するという視点で、その辺もしっかり見ていっていただきたいなと思います。もう４月に始まる事業で、最後、確認したいと求めました。","respondent":"藤村子ども育成課長","answer":"こちらは様々契約、他自治体も含めてあるかと思いますので、そういった事例を参考に金額は検討していきたいと思います。今の検討している段階のスタートの期日に間に合うように契約は結んでまいりたいと考えていますので、そちらについては問題ないかと考えております。","id":"exchange-063"},{"speaker":"吉田委員","kind":"質問・要望","question":"これは繰り返しになるので、要望でとどめます。これはもう単純な質問で、４年間だったか、伺いたいと思います。","respondent":"小林新庁舎建設担当課長","answer":"残りの部分につきましては、出来高であったり、最後の精算であったりするときに使う費用ということで予算計上させていただいたところです。今回この建物は区分所有建物ですので、それら相当分の負担額ということを見込みまして、今回の債務負担行為を設定したところです。","id":"exchange-064"},{"speaker":"吉田委員","kind":"質問・要望","question":"分かりましたと言っていいのかどうか少し自信がないのですけれども、これは１つ、私たちがずっと求めてきたことが実現したからなのですけれども。もう１回、区民の方たちに、こういう説明をすれば納得していただけるよみたいなものがいただければ伺いたいと思います。","respondent":"小林新庁舎建設担当課長","answer":"どういったご説明というところかと思うのですが、今回、７００億円余というところがまず大きな枠としています。その残金６３０億円余につきましては、債務負担行為といった考えですので、予算を要求しているといったところです。","id":"exchange-065"},{"speaker":"吉田委員","kind":"質問","question":"ただ、具体的な事業というと、今のところ、相談できる窓口の設置ということと、月に１回対面相談会ということなのでしょうか。やはりぜひ居場所とか、そういう事業があったらいいなと思うのですけれども、その点についてはいかがか尋ねました。","respondent":"柴田子ども施策連携担当課長","answer":"相談窓口の設置、現在の実施状況としましては、児童センターで実施をしています。様々区の需要、それから他の自治体の動向等を研究しながら、様々な課題を認識し、施策に反映させていきたいと考えているところです。","id":"exchange-066"},{"speaker":"吉田委員","kind":"質問・要望","question":"いい方向に進んできているのかなというふうに思っています。３５０人が、もっともっとこういう場を求めている人はいらっしゃるのかなと思うのですけれども、そういうものがあったら説明するよう求めました。","respondent":"柴田子ども施策連携担当課長","answer":"チャット機能の中で、そういったところで意見を聴取していきたい、そこのいただいた意見を反映させるということをまず考えております。月に１回実施している対面相談会、定期的に同じ場所でやったりとか、そういったことも工夫しながら展開をしていきたいと考えています。","id":"exchange-067"},{"speaker":"のだて委員","kind":"質問・要望","question":"５０ページから始まる歳入全般における増収について、１６１ページ、訪問介護事業所への支援を求めて質問をします。午前中の質疑でご説明がありましたけれども、３０代から５０代の方が増えているということで、なぜこの世代が増えているのか伺います。","respondent":"吉野税務課長、加島財政課長","answer":"３０代から５０代の方たちの課税標準額ですけれども、こちらは、やはり昨今の経済状況といったところで、安定的な収入が増えているような状況です。１か月プラス１１か月分、１２か月分を歳入するということで、この予算額を編成させていただきました。こちらにつきましては、調整税の伸びと、それから配分割合の変更が５５.１％から５６％に変更になったことによるものです。","id":"exchange-068"},{"speaker":"のだて委員","kind":"質問","question":"消費税のところでは、結局、今回は１２か月分が入っているということでよろしいか尋ねました。","respondent":"加島財政課長","answer":"説明が足りなくて申し訳ございません。令和６年１２月分の１か月分と、令和７年１月から１１月まで、合わせて１２か月分が地方消費税交付金、こちらの予算額です。","id":"exchange-069"},{"speaker":"のだて委員","kind":"質問・要望","question":"この消費税の減税も、物価高対策としては、ぜひ国に求めていただきたいと、これは要望しておきたいと思います。１９３人、約３,９００万円が返済中だということで答弁されておりますけれども、現在がどうなっているのか伺います。","respondent":"飛田子育て応援課長","answer":"大体平均でいうと、一番多いところでは平成２５年ぐらいの方から３０年、そのくらいの方がまだ返済途中というふうになっております。債権の放棄の基準に該当するかどうかの確認など、債務者の現状の生活に応じて無理のない返済方法や解決策を提案しています。","id":"exchange-070"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひこの奨学金貸付金の返済、これを一部または全額免除をしてほしいと求めましたが、いかがでしょうか。以前に求めた際に、区は他区を注視していきたいということで言っておりましたけれども、その注視状況がどうなったか伺います。","respondent":"飛田子育て応援課長","answer":"返さない方が得をするというのは、いかがなものかと考えておりますので、また引き続き無理のない返済等を相談しながらやっていきたいと思います。そこのことについては、ご理解いただければと思います。","id":"exchange-071"},{"speaker":"のだて委員","kind":"質問","question":"他区の状況を注視しているということで、以前、答弁がありましたけれども、今の状況をお伺いします。","respondent":"飛田子育て応援課長","answer":"今のところ、他区のところでも、同じように返済は、こつこつと返している方がいるということで、品川区と同じような状況であるということを認識しております。","id":"exchange-072"},{"speaker":"のだて委員","kind":"質問・要望","question":"一番長い人では３０年ですか、返すことが困難になっているという人もいると思いますので、そこは免除をしていってほしいと求めました。もう１つ、やはりこの４月に報酬が引き下げられて、ぜひ区として直接支援してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-073"},{"speaker":"中塚委員","kind":"提案","question":"６５ページ、それぞれ子どもの利用料無償化と、プールのロッカーの返却式による無償化を求めて質問したいと思います。子どもからは取らない、直ちに無償と改めて提案いたしますが、いかがか尋ねました。","respondent":"大森文化観光戦略課長、大友公園課長","answer":"区内の小学生、区外の小中学生に関しては、通常大人の１００円の半額の５０円ということで拝観料をとっているところです。決算特別委員会でのご報告をさせていただいたとおりなのですけれども、受益者負担の考えのもと、使用料を設定させていただいているところです。","id":"exchange-074"},{"speaker":"中塚委員","kind":"質問・要望","question":"それならば、なぜ歴史館とプールは、子どもについても受益者負担を求めるのか。子どももお金を払うのか、子どもも自己責任なのか、これが区長の考えなのか伺います。","respondent":"大森文化観光戦略課長、大友公園課長","answer":"繰り返しの答弁にはなるのですけれども、歴史館につきましては、区内の小中学生については無料としています。サービスではないところにおきまして、無償化におきましては、誰もが必要としているサービスを無償化しているところだと考えているところです。","id":"exchange-075"},{"speaker":"中塚委員","kind":"質問","question":"だったら、なぜプールは誰もがではないからとなるのか、改めて伺いたいと思います。改めて伺います。","respondent":"大森文化観光戦略課長、大友公園課長","answer":"小学校の社会科見学等でご利用いただいているというところもあるのですけれども、それが生活におけるものではないというふうに考えてありますので、妥当な受益者負担と理解しています。利用者が限られる施設におきましては、やはり受益者負担の考えのもと、使用料を設定させていただいているところです。","id":"exchange-076"},{"speaker":"中塚委員","kind":"質問・要望","question":"１人の方が複数使用するとロッカーが不足する、１０か所借りたら１００円ですから、そのような乱暴な使い方をしている人はいないわけです。これは区長の施政方針に引くまでもなく、区民の利便性の向上と、このような簡単なことをなぜすぐできないのか伺いたいと思います。","respondent":"大友公園課長","answer":"初めに申し上げました答弁と重なるところがありますけれども、予約数とロッカーの数が、現状、一緒となっているところが原因となっています。","id":"exchange-077"},{"speaker":"西村委員","kind":"質問","question":"１１９ページ、１３３ページ、とうきょうママパパ応援事業補助金から産後ケア事業について伺ってまいります。その後、宿泊型、日帰り型と伺ってまいりたいと思いますのでお願いいたします。","respondent":"石橋品川保健センター所長","answer":"私からは、産後ケアの拡充についての思いについて回答します。出産後間もなくから産後とその家族に寄り添った支援をしたいという強い思いのもと、今回の大幅な拡充をさせていただきたいと考えております。","id":"exchange-078"},{"speaker":"西村委員","kind":"質問","question":"宿泊型なのですが、利用日数等が拡充されまして、どのような産後のお母さんたちからの声があって、今回の拡充に至ったのか伺いたいと思います。これは各保健センターで行うと伺っております。","respondent":"石橋品川保健センター所長","answer":"夜間ゆっくり休みたいというお声もありまして、今回、６泊７日というところで期間の延長をすることにしました。荏原保健センターでの実施になりますが、そちらをよく考えながら、今後の日帰り型の個別についてもしっかり検討してまいりたいと思っています。","id":"exchange-079"},{"speaker":"西村委員","kind":"質問","question":"助産師の仕事について伺ってまいりたいと思いますが、乳房ケアに特化した助産師が訪問する事業だと理解しております。これ以外に区内の助産師たちが活動していらっしゃるお仕事について、改めて伺えればと思います。","respondent":"石橋品川保健センター所長","answer":"その声も踏まえまして、今回、ケアメニューにこちらの乳房ケアの特化したものも追加するということで進めしています。その後の毎日の生活のプランを一緒に考えたりですとか、お子様の体重測定、助産師に多くの役割を担っていただいているところです。","id":"exchange-080"},{"speaker":"西村委員","kind":"質問","question":"これらの助産師の支援がありまして、今後さらに新しくＭｙ助産師制度が始まるということで、こちらは子ども育成課が担当する理由と、児童センターでも保健センターと連携してすくすく赤ちゃん訪問など産後の支援を展開していただいておりますので。","respondent":"藤村子ども育成課長","answer":"年齢も性別も様々なターゲットを対象に、親育ち支援事業を行っておりまして、中でも父親の子育てスキルのアップに力を入れているところです。２００人以上、こちらにパートナーへの支援というものを組み込む形で課題の解消が見込めるのではないかと、提案したところです。","id":"exchange-081"},{"speaker":"西村委員","kind":"質問・要望","question":"父親支援を私も要望していきたいのですけれども、この地域の助産師たちとの築いてきた長年の関係性と、新しく始まるＭｙ助産師制度をどう融合させていくのか伺います。","respondent":"藤村子ども育成課長","answer":"既存事業も当事業と並行して包括的に進めていくものではないかというふうに考えております。保健センター事業のほか、様々なそういった親育ち支援事業のほうにつなげられることで、シームレスなサービス展開が可能になるのかなと思っています。","id":"exchange-082"},{"speaker":"西村委員","kind":"意見","question":"どう下ろしていくのかという連携と、既存の助産師たちの声が最も重要だと思いますので、今後の展開など区のお考えがあれば説明するよう求めました。","respondent":"藤村子ども育成課長","answer":"リアルで支援が必要だなというような判断がある方には、さらに子ども未来部や保健センター一体となって対応したいと考えています。既存の事業との情報共有というところですが、そちらも個別ケースに沿って検討してまいりたいと思います。","id":"exchange-083"},{"speaker":"塚本委員","kind":"質問・要望","question":"１０３ページの社会資本整備総合交付金、１４７ページ、５６ページの交通安全対策特別交付金について伺っていきたいと思います。１２時というか、こういったことについて、どのように捉えていらっしゃるのかお伺いしたいと思います。","respondent":"柏木学務課長","answer":"その中では、当然、ふぞろいのものもございましたけれども、そういう部分では、これまでもそういうもので対応できているという部分はあります。改めて、今回、有機農産物等を調達する際には、そういう部分の負担軽減がさらにできるような調達方法等について検討をしてまいります。","id":"exchange-084"},{"speaker":"塚本委員","kind":"質問","question":"青果店の方から伺いましたけれども、品薄になったりとか、いろいろリスクがある。そういった柔軟な対応をぜひお願いしたいと、ぜひご見解をいただければと思うのですけれども、いかがか尋ねました。","respondent":"伊崎教育長","answer":"直ちに地元の事業者の方や、関係する皆様に丁寧なご説明や意見交換を行ってご理解をいただき、進めていきたいと考えております。きちんと検品をするような納入条件の設定なども含めて、様々な方策を検討してまいりたいと考えております。","id":"exchange-085"},{"speaker":"塚本委員","kind":"質問・要望","question":"水道と言ったらいいのですか、飲み水とかが出る水道の設備がない公園が、品川区には幾つかあるかと思います。この数がどれぐらいあるのか分かれば教えていただきたいのと、しないの基準、こういったものはどういうところにあるのか最初にお伺いいたします。","respondent":"大友公園課長","answer":"区で管理する全２７６公園・児童遊園等のうち、水道設備が設置されていない公園数は２０公園となっています。整備されていない２０公園につきましては、主にポケットパークのような小規模な公園が中心となっているところです。","id":"exchange-086"},{"speaker":"塚本委員","kind":"質問","question":"基本的には設置ということがある中で、２０公園、主に小さな公園ということですかね、雑駁に言うと。これは、今後、設置に向けての考え方は、どういう状況なのか尋ねました。","respondent":"大友公園課長","answer":"現在、整備されていない公園におきましては、公園ごとに整備されていない理由があるところではあります。護岸の上であったり、公園の改修時などを機に水道設備の新設ができないかというところを改めて検討してまいりたいと考えています。","id":"exchange-087"},{"speaker":"塚本委員","kind":"質問・要望","question":"ある区民の方から要望がありまして、具体的にどういうやり取りだったか詳しくは聞いていませんが、高齢者なのです。これは品川区の権限で変えられるものであるのか、検討をできればしていただきたいなと思いますけれども、いかがか尋ねました。","respondent":"山下交通安全担当課長","answer":"昭和３０年から昭和４０年ほどにかけまして、交通が多くなってきて、根絶を期して宣言されたものと伺っております。また、この宣言の趣旨に沿って交通事故防止対策を区としましても引き続き実施していきたいというふうに考えているところです。","id":"exchange-088"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"答弁として課題が多いということは伺っておりますが、その際に、改正を国に機会を捉えて要望するということもおっしゃられていました。その後の経過はいかがか尋ねました。","respondent":"築山戸籍住民課長","answer":"各種社会保障制度等の改定についての検討と、当事者の関係を適切に反映した新たな表記の設定と対応という要望について、賛同した９区とともに国に対して申し入れを行ったところです。","id":"exchange-089"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"区としても要望しているということでよろしいか尋ねました。","respondent":"築山戸籍住民課長","answer":"ジェンダー平等と性の多様性を尊重し合う社会を実現するための条例を今年度４月に施行しておりますけれども、誰もが自分らしく生きられる社会の実現に向けて取り組んでいきたいという思いから、今回の国への要望に至っているものです。","id":"exchange-090"},{"speaker":"やなぎさわ委員","kind":"質問","question":"２３区では１１月から世田谷区、なぜそこまで今たどり着けていないのかというところが非常に疑問なのですけれども、その点をお伺いします。","respondent":"築山戸籍住民課長","answer":"当事者に寄り添うため検討をしてきたところだったのですけれども、住民基本台帳法とその要領に基づいて全国統一的な対応が求められるべきだという通知が発信されまして、少し難しいという判断をせざるを得なかったです。","id":"exchange-091"},{"speaker":"やなぎさわ委員","kind":"質問","question":"では、お伺いします。先行自治体に対して、何か不都合が出ているのかとか、問題があるのかということを調査研究等はされていますか尋ねました。","respondent":"築山戸籍住民課長","answer":"今回、国に対して申し入れを行う際に、近隣の自治体とも意見交換をしながら進めてきたところです。２３区でいきますと、中野区と世田谷区がございまして、そこの自治体に対して課題を幾つか聞いているところです。","id":"exchange-092"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"それこそ昨年の１２月２３日に、東京都の１０の区長と一緒に、ぜひこれを前に進めるようにしていただければという要望で終わらせていただきます。","respondent":"吉野税務課長","answer":"ですので、寄附額は、例えば１万円であれば３万円。こういった経費は５割ルールとなりまして、半分、１万５,０００円以内に収めるようにというようなルールがあります。","id":"exchange-093"},{"speaker":"やなぎさわ委員","kind":"提案","question":"そこで、また提案なのですけれども、品川区出身で日本を代表するプロ野球選手がいることを皆さんご存じでしょうか。シーズンオフに野球教室などを催してはいかがかと思いますけれども、親子野球教室ですね、いかがか尋ねました。","respondent":"吉野税務課長","answer":"現在、野球の選手の方がどこに住んでいるのかというところもやはり大きなあれになってくるかなと思いまして、品川区でのものになりますので、例えば、品川区で、そこで活動されている方であればできるかなと。","id":"exchange-094"},{"speaker":"やなぎさわ委員","kind":"質問","question":"ＮＰＢ、９００人しか現役選手はいないのですけれども、その中でもトップクラスの選手が品川区出身というのは非常に大きな財産だと思います。改めていかがか尋ねました。","respondent":"吉野税務課長","answer":"今のご提案、検討します。このほかに品川区では返礼品の開発を進めておりますので、よろしくお願いいたします。","id":"exchange-095"},{"speaker":"松永委員","kind":"提案","question":"実績を確認し、ここ３年では約３割前後であり、完了または廃止という方向で考えていると先ほどの答弁で伺いました。横の区民公園と連携して、そうした広場をつくってみてはどうかという意見なのですが、いかがか尋ねました。","respondent":"築山戸籍住民課長","answer":"建物としては、まだ継続的な活用ができますので、現時点では、建て替えるというようなことも含めて、これから検討することになってきます。","id":"exchange-096"},{"speaker":"松永委員","kind":"提案","question":"例えば、避難場所としても使えるのではないかという提案だったので、ぜひそうしたところも含めてご検討いただければというふうに思います。次に、８３ページの動物死体処理手数料について伺いますとの意見を述べました。","respondent":"篠田品川区清掃事務所長","answer":"来年度の歳入予算ですけれども、１７０頭の根拠です。令和３年度が１６１頭ということで、ここ数年は１６０頭から１７０頭程度で推移をしているところから、来年度の予算を１７０頭で組んだものです。","id":"exchange-097"},{"speaker":"松永委員","kind":"質問","question":"こうした取組がある中で、本区においてどういった方法をとられているのでしょうか。伺います。","respondent":"篠田品川区清掃事務所長","answer":"私どもでは、民間の事業者、ペット霊園に委託をいたしまして、各ご家庭からお預かりした動物のご遺体に関しましては、そちらのほうで対応させていただいているところです。","id":"exchange-098"},{"speaker":"松永委員","kind":"質問","question":"そうした提携をしているところは、１か所のみですか尋ねました。","respondent":"篠田品川区清掃事務所長","answer":"私どもで提携しているというか、委託をかけているのは、民間の事業者１社と契約を結んでいるところです。","id":"exchange-099"},{"speaker":"松永委員","kind":"質問・要望","question":"最後の看取りというところも、ぜひ一緒にさせていただきたいということで、ご要望もいただいております。区内には、ペット葬儀、また、火葬、霊園をされているところがありますので、そうしたところについて伺いたいと思います。","respondent":"篠田品川区清掃事務所長","answer":"その他の可能性として、何か区内の事業者と連携できることがあれば、またその辺については随時検討していきたいというふうに考えております。その辺に関しましては、随時、私どもも注意を払いながら対応してまいりたいと考えるところです。","id":"exchange-100"},{"speaker":"松永委員","kind":"質問","question":"そこで、不適正管理状態の空き家について、把握されている空き家について、どのくらい存在しているのでしょうか、伺いたいと思います。約１００件の空き家が改善されていると伺っておりますけれども、その後どういった形になっているのか伺いたいと思います。","respondent":"川原住宅課長","answer":"住宅課の職員と連携してホットラインの相談についてもしっかりと取り組んでいるところでございまして、現地調査をしっかり行っているところです。３３１件ほど現地に把握をさせていただきまして、しっかりと空き家の所有者の調査から始めまして、適正管理を促しています。","id":"exchange-101"},{"speaker":"松永委員","kind":"質問","question":"やはりなかなか家を借りたいけれども借りられないという方に対してのご相談を結構受けています。空き家の活用について、区としては、どのように考えておられるのか説明するよう求めました。","respondent":"川原住宅課長","answer":"外部に委託をして店舗を設けて相談を受け付けしていただいているところですが、こちらも１月の段階で２８件のご相談をいただいているところです。","id":"exchange-102"},{"speaker":"松永委員","kind":"質問","question":"最後に、１５９ページの国際交流推進基金繰入金のうち、地域住民と外国人の交流について伺います。こういったものがあるよというようなセミナーとかをしっかりとした形で周知をしてほしいと求めましたので、その考えについて示すよう求めました。","respondent":"勝亦総務課長","answer":"外国人の方、品川区内に、今１万７,０００人ぐらい、４％ぐらいまで増加しています。やさしい日本語、そういったものを周知・啓発して、外国人の方に生活等のご理解をして地域住民との共生を図っていきたいと考えております。","id":"exchange-103"},{"speaker":"高橋（伸）委員","kind":"質問","question":"５２ページ、特別区たばこ税、１０５ページ、空き家等対策事業についてお伺いいたします。民間公衆喫煙所設置、維持に関する助成を行うということで私は認識しておりますけれども、そういう考え方でよろしいか尋ねました。","respondent":"河合生活安全担当課長","answer":"委員のご説明のとおり、来年度は民間公衆喫煙所を主軸といたしまして整備を進めてまいります。そして、そこで足りない部分について等は、コンテナ喫煙所等を、そのときに場所の選定等を検討してまいりたいと考えております。","id":"exchange-104"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"１０分の１０という要望もさせていただき、１０分の１０、どうもありがとうあります。目標件数として、どのぐらいを目標としているのか、まずお知らせをしてほしいと求めました。","respondent":"河合生活安全担当課長","answer":"当初予算では、新規設置につきましては、現在３件、維持管理のほうです。なお、制度が開始になりまして、状況に応じて、申請等が多いようであれば、補正で対応したいというところで財政とも検討しています。","id":"exchange-105"},{"speaker":"高橋（伸）委員","kind":"確認","question":"確認させていただきました。もう１回、再確認したいと求めました。","respondent":"河合生活安全担当課長","answer":"区が設置するコンテナ喫煙所等につきましては、足りないところを含めて検討いたしまして、そこで足りないところでは、地域の方々のご協力をいただくような形の説明が必要になりますので、そういったことを進めながら検討してまいりたいと考えております。","id":"exchange-106"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"この１年間、４月以降、その辺についてお伺いさせてほしいと求めました。","respondent":"河合生活安全担当課長","answer":"コンビニエンスストアにありましても、やはり周辺の民間公衆喫煙所の整備が進んでいるところ、コンビニの件数が多くなっております。民間公衆喫煙所の助成を拡大していく方針になった際にも、事前に、また個別にオーナーのほうにも依頼をかけていきたいと考えております。","id":"exchange-107"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"何かそういう取組もあってもいいのかなと私は思っているのですけれども、ぜひそれはやっていただきたいと要望をさせていただきたいと考えています。その辺についてお尋ねをさせてほしいと求めました。","respondent":"河合生活安全担当課長","answer":"そういったところを踏まえまして、その必要性は、バランスをとりながら検討していきたいと考えております。","id":"exchange-108"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひ検討してほしいと求めました。区として、これから要綱をつくったりとか、そういうお考えがあるのかお尋ねをさせてほしいと求めました。","respondent":"若生健康課長","answer":"実際、こちらが適用された事例は、区においては今までないところではあります。は東京都の条例、こちらで明確に規定されているところから、区のほうで独自に設定するという考えは現在のところございません。","id":"exchange-109"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"私は、行ったこともあるのですけれども、そういうことが見受けられるのです。そういうときは、定期的に指導したりとか、それは定期的にやっておられるものかどうかということを確認させてほしいと求めました。","respondent":"若生健康課長","answer":"現在、通報に基づいてといいますか、いろいろなお問い合わせがあった際に現地を確認したりというところで対応しています。現在のところは、定期的に職員が回る、あるいは業者が回るというところまでは、現在やっていないところです。","id":"exchange-110"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"続きまして、１０５ページの空き家等対策事業についてお伺いします。その辺についてお伺いしたいのと、あともう１点が、どれが一番多いのかということをお知らせほしいと求めました。","respondent":"川原住宅課長","answer":"１点目は、所有者および近隣の方からの相談件数についての回答です。相続人の方が、そこに建て替え、リフォームをして住むよりかも売却をするという判断になる方が非常に多い状況です。","id":"exchange-111"},{"speaker":"高橋（伸）委員","kind":"意見","question":"１年、２年かけて調査するというのは大変なご苦労と作業もあると思います。これからの方向性について、最後にお答えをお願いしたいと思いますとの意見を述べました。","respondent":"川原住宅課長","answer":"今後の方向性につきましては、引き続き、相続人調査もしっかりと行いながら、空き家の適正管理を促しながら、また、相続人の方への空き家となるひどい状態になる前の管理の予防というところを発信してまいりたいと思います。","id":"exchange-112"},{"speaker":"石田（し）委員","kind":"質問","question":"私は、歳入全般で、いわゆる税収増に見る区内経済についてお伺いしていきます。品川区では、今どのような税収の推移があったのか、また、どのような要因でそのようになっているのか示すよう求めました。","respondent":"吉野税務課長","answer":"ご説明させていただいたとおり、経済的な部分もありまして、皆さんのそういった課税標準額が上がっております。ですので、ちょうど３０代から５０代の方たちが、そういったところの底上げをしているような状態です。","id":"exchange-113"},{"speaker":"石田（し）委員","kind":"質問","question":"いわゆる国は６年連続最高記録を更新しているのですよね。その辺について区はどうなのか尋ねました。","respondent":"吉野税務課長","answer":"品川区も、令和元年度からずっと税収は伸びております。令和４年度から令和５年度に関しましても、２０億円ぐらいずつ増えてきている現状です。","id":"exchange-114"},{"speaker":"石田（し）委員","kind":"質問","question":"つまり、納税者が約６,０００万人ですから、６人に１人が今これを利用して、いわゆる節税、還付、税制優遇制度ということで利用している。どのように対策をとっていこうと思っているのか説明するよう求めました。","respondent":"加島財政課長","answer":"令和７年度予算案の中では、これからご審議いただく款に入ってまいりますけれども、高齢者の方の無償化や負担軽減も図っているところです。ここがどのような動きをたどっていくかというのは、ぜひ議員の皆様にも見ていただきたいと考えております。","id":"exchange-115"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"今からやらないと、これは耐えられないから、もうぜひやっていただきたいけれども、その自己責任論でいけば、その点はどうですか。説明するよう求めました。","respondent":"加島財政課長","answer":"１０年後、２０年後を考えたとき、今、若い世代が同じ苦しみを味わってほしくないというふうに思っております。そのことによって、品川区として、分かち合い、満たし合いの社会を実現していきたいと考えております。","id":"exchange-116"},{"speaker":"こんの委員","kind":"質問・要望","question":"併せて、そもそも拡幅工事をするときに、移設についてはどのように行っているのか、取り扱いや移設の費用などを確認させてください。移設されない場合の課題などは何が課題となっているのか、以上、お聞かせほしいと求めました。","respondent":"森建築課長","answer":"２項後退で道路が広がっても電柱が残ってしまうというような課題があるということは、区といたしましても認識しています。やはり区のほうで強制的に移動させることもできませんので、区の職員も出向いて、ご同意いただけるように努めているところです。","id":"exchange-117"},{"speaker":"こんの委員","kind":"質問・要望","question":"こうした仕組み、介護保険や子どもの医療なども、こうした国保のような反映ができる仕組みはできないのでしょうかといったところです。いかがか尋ねました。","respondent":"築山戸籍住民課長","answer":"現在、国のほうで様々な検討が進んでおりますので、今後できる手続が増えてくるというふうに考えております。手続に数日かかるといったようなものがありまして、現状といたしましては、それぞれの窓口に行ってもらっているような状況です。","id":"exchange-118"},{"speaker":"鈴木委員","kind":"質問・要望","question":"源氏前小学校の父母の方からご要望をいただいたのですけれども、なぜ屋上に屋根なしプールをつくるのかということで伺いたいと思います。４６校のうち２６校が改築済みだったりとか、２６校中、それぞれ何校なのかという状況について伺いたいと思います。","respondent":"荒木学校施設担当課長","answer":"申し訳ないのですけれども、改築校において、屋外プールで屋根なしについては、手元に資料がないので、回答は控えします。冒頭申し上げましたとおり、コスト面や維持管理面というところを優先して検討し、決定しています。","id":"exchange-119"},{"speaker":"鈴木委員","kind":"質問・要望","question":"その点いかがでしょうかということと、これ、平成１４年なのです。こういうものをどういう学校の校舎にするのかということの基準みたいなものはどう考えるのか、その点についても伺います。","respondent":"荒木学校施設担当課長","answer":"もう１点のプールの差ですが、区としても、こちらは課題というふうには認識をしております。プール授業の実施の方法なども含めまして、今後、在り方について検討を進めてまいりたいというふうに考えてあります。","id":"exchange-120"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そういうところで、源氏前小学校については、検討はされたのかどうなのかなというふうな思いがしているのですけれども。説明もしてもらいたいというご要望もいただいているのですけれども、源氏前小学校の改築に対して、いかがか尋ねました。","respondent":"荒木学校施設担当課長","answer":"現在の２４クラスであれば、十分屋外においてもプールの授業は実施できるというふうに考え、屋内化はしなかったところです。説明会の実施状況ですが、令和５年８月に近隣住民を対象とした計画説明会を実施しており、また近隣住民を対象として工事説明会を実施したところです。","id":"exchange-121"},{"speaker":"田中委員","kind":"質問","question":"私、そして時間がありましたら、１４７ページの公立学校給食費負担軽減事業補助金に関連して有機野菜についてお伺いしたいと思います。","respondent":"菅野高齢者福祉課長","answer":"法人のほうにお聞きしたところ、こちらの派遣の職員率は、令和６年度もう少し減少しているというようなお話は伺っております。決してそのような意識はなく、今回も慢性的な人材不足に備えて、決してそういう認識はないということでご理解いただければと思います。","id":"exchange-122"},{"speaker":"田中委員","kind":"質問","question":"もう１つ言うと、そこもお伺いしたいのですけれども、選定理由の評価項目として記載されております。外国人職員を採用せざるを得ない、そのことこそ介護人材が不足している状況だと考えていますが、改めて認識をお伺いします。","respondent":"菅野高齢者福祉課長","answer":"例えば、こちらの三徳会におきましても、令和４年度に９人の外国人が採用されたという事例があります。ある施設で手を挙げて３人の方を採用したところ、今では１３人の方がいらっしゃるということで、決して悪い事例ではないというふうに捉えております。","id":"exchange-123"},{"speaker":"田中委員","kind":"質問・要望","question":"最低５日間とれば法律的にはクリアされているのですけれども、そのほとんどが５日しかとれていないのが現状でもあると私は思っております。環境整備、労働環境の確認という視点でも取り組んでほしいと求めましたが、最後に。","respondent":"菅野高齢者福祉課長","answer":"労働環境のチェックの部分につきましては、指定管理者制度のモニタリングの中でも労働環境チェックを５年のうちに１回、実施していますので、その中でしっかりと確認はしていきたいと思います。","id":"exchange-124"},{"speaker":"えのした委員","kind":"質問","question":"私からは、６７ページ、公園運動施設使用料についてお伺いします。暑さ対策、熱中症対策はどのように取り組まれていますでしょうか、説明するよう求めました。","respondent":"三井スポーツ推進課長","answer":"当日であっても、使用前であれば、熱中症予防を理由に急なキャンセルでもキャンセル料を免除とする対応をとっているところになります。","id":"exchange-125"},{"speaker":"えのした委員","kind":"確認","question":"確認がとれました。キャンセルの件数などが分かれば示すよう求めました。","respondent":"三井スポーツ推進課長","answer":"昨年の数値になりますが、熱中症予防を目的にキャンセルされた方は２２０件となっております。","id":"exchange-126"},{"speaker":"えのした委員","kind":"意見","question":"抽せん申込みが３か月前、そして空き予約が１か月前など、使用者にとっては大変ありがたく助かる取組だと評価をいたします。実際の公園では、暑さ対策について、どのような取組がされているのか説明するよう求めました。","respondent":"大友公園課長","answer":"公園内の熱中症対策ですけれども、公園内のパーゴラによしずを設置して日陰を設けることや、一部の公園ではミストを設置しております。区が管理する全公園に熱中症への注意喚起の看板を設置しまして、注意喚起を行っているところです。","id":"exchange-127"},{"speaker":"えのした委員","kind":"質問","question":"こちらは既に実施されたのでしょうか。実施されていれば、受講者数と、学校教員も含まれていたのか示すよう求めました。","respondent":"勝亦総務課長","answer":"大塚製薬と連携協定を締結いたしまして実施しました熱中症対策アンバサダー講座についてです。こちらの講座につきましては、令和６年６月から８月の期間に、オンラインで実施しています。","id":"exchange-128"},{"speaker":"えのした委員","kind":"確認","question":"ホームページを確認したところ、開講に取り組まれており、区民の方へ向けた実施は考えておられますでしょうか。こちらは進められていますでしょうか、説明するよう求めました。","respondent":"勝亦総務課長","answer":"地域の方ですとか、そういった方への受講対象につきましては、今後、検討してまいりたいと考えています。連携しております大塚製薬とご相談しておりまして、連携しながら、積極的に熱中症の啓発に努めていきたいと考えています。","id":"exchange-129"},{"speaker":"えのした委員","kind":"質問","question":"ついつい忘れてしまうこともあり、ペットボトルの水をいただけるのであれば本当に助かると、多くの声を伺いました。子どもたちの施設、子育て世代についての周知啓発はされていますでしょうか、説明するよう求めました。","respondent":"勝亦総務課長","answer":"それから保育園、幼稚園等に、大塚製薬と連携して作成した啓発ポスターを掲出しています。今後、ＳＮＳの活用など、より広く避暑シェルターについて、区民の方にお知らせしていきたいと考えています。","id":"exchange-130"},{"speaker":"若林委員","kind":"確認","question":"それをベースに、例えば、１１月６日の喫煙状況実態調査では、迷惑性や危険性を否定できない喫煙状況が確認されたと。そこで、来年度に向けて、この対策方針、規制強化、喫煙所整備の考え方の取組を確認します。","respondent":"吉野税務課長、河合生活安全担当課長","answer":"令和６年度の見込みも、こちらは減る見込みでおります。それに見合いまして、実績見合いとしまして、令和７年度も減収の見込みで立てております。規制強化と喫煙所の整備促進というところで進めておりまして、来年度の方針ですが、条例の規制強化が制定されましたら、７月施行予定です。","id":"exchange-131"},{"speaker":"若林委員","kind":"質問・要望","question":"地域や公衆喫煙所の形態ですか、業態というのでしょうか、お聞かせほしいと求めました。禁止の条例ということで、さっきの答弁と重なる部分は結構ですが、そのほかに指導強化に取り組むお考えを確認したいと思います。","respondent":"河合生活安全担当課長","answer":"公衆喫煙所の新規設置３件、新規３件につきましては、２社といろいろ話をして能動的にいきたいとお話しいただいているところ。苦情といいますか、禁止ということで明確な指導ということで指導できますので、そういった効果が得られるというところになっております。","id":"exchange-132"},{"speaker":"若林委員","kind":"確認","question":"２回、一定期間後の成果というものもしっかり確認する必要が私はあると思いますので、何とか調査というもののお考えを聞きたいと思います。餡子と皮の部分をもう１回確認をさせていただいて、また、喫煙所の配備をするというところの考え方を確認したいと求めました。","respondent":"河合生活安全担当課長","answer":"規制強化が制定されましたら、やはり公共の場所というところで、そういった事業名も変わるところになっております。今後の規制強化も検討する上でも、やはり時期を見て、そういったところは検討する必要があると考えております。","id":"exchange-133"},{"speaker":"西本委員","kind":"確認","question":"なぜこの動議をかけたかというと、やはり区の態度をしっかりと確認をしていかないと、まともな審査ができないと思ったからなのです。冒頭に、どうしてこういうことになったのかということを聞く、確認をするということが私の趣旨です。","respondent":"與那嶺戦略広報課長","answer":"西本委員から、プレス発表の前に、今回の予算の内容について報道があったことについてのご質問です。日々、独自の取材や編集などを行っているですので、区として関与するところではございません。","id":"exchange-134"},{"speaker":"西本委員","kind":"質問","question":"これ、どう説明するのですか。誰がやったのか尋ねました。","respondent":"與那嶺戦略広報課長","answer":"先ほどと少し繰り返しになりますが、報道については、メディアの各社において、それぞれ積極的に取材などが行われているものと認識しております。あくまでこれは品川区で独自のところではなく、いわゆる一般的に起こり得るところかという形で考えてあります。","id":"exchange-135"},{"speaker":"西本委員","kind":"質問","question":"この予算の説明の中で説明があって、プレス発表の前に新聞報道になって、これだけの、全社です、全紙です、されたことはないですから。それをどう説明するのか尋ねました。","respondent":"與那嶺戦略広報課長","answer":"今回の報道に関しても、各報道機関、積極的に取材活動を行っていただいたものと認識しています。取材源の秘匿の原則がありますので、そちらについては、区のほうで誰がというところの関知をするものではないと認識しています。","id":"exchange-136"},{"speaker":"西本委員","kind":"質問","question":"誰に聞いたのですかと言えば分かりますよね。だから守っていたではないか尋ねました。","respondent":"與那嶺戦略広報課長","answer":"繰り返しのご答弁になり恐縮です。あくまで今回のプレス発表につきましては、各報道機関において、日頃からの積極的な取材の帰結であるというふうに認識しています。","id":"exchange-137"},{"speaker":"西本委員","kind":"質問","question":"守るべきことをしっかり守って、なのに、行政側のほうから約束を破っているではないですか。こういう行動をこれからも続けるのか尋ねました。","respondent":"與那嶺戦略広報課長","answer":"２月５日の発表以前に、このプレス発表の資料自体は、あまねく配布をしておるところです。自治体であったりとか、国政、都政においても起こり得るようなところであるという形で認識しています。","id":"exchange-138"},{"speaker":"西本委員","kind":"質問","question":"この原因、どうしてこういう経緯になったのかということを議会運営委員会にかけていただきますので、きちんと答えてください。責任者は区長なのですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-139"},{"speaker":"澤田委員","kind":"質問・要望","question":"１５６ページ、ふるさと納税寄附金について伺います。ふるさと納税寄附金の一般分を１億円と計上されていますが、金額の理由を説明するよう求めました。","respondent":"吉野税務課長","answer":"ふるさと納税の返礼品なのですけれども、こちらは、返礼品と体験型を含めたものの予算になります。品川区には、まだ潜在的な魅力がたくさんありますので、こちらのものを返礼品として掘り起こしをしていきたいと考えております。","id":"exchange-140"},{"speaker":"澤田委員","kind":"質問・要望","question":"２点目は、国に対し、特別区への支援制度を要望すること。３点目は、体験型と同様に、返礼品の企画開発の推進、地域貢献の寄附型の推進、これらを要望してまいりました。","respondent":"吉野税務課長","answer":"これは今年度も実は実施したのですけれども、こちらはもう少し力を入れまして、拡充を図っていきたいと考えています。それから、団体応援寄附金、こちらも実施したいと考えています。","id":"exchange-141"},{"speaker":"澤田委員","kind":"質問・要望","question":"例えば、議会として、また例えば私として、どのようなことができるとお考えでしょうか。なぜこのようなことをお伺いしたかといいますと、その問いに対して、どう返答することができるのか。","respondent":"吉野税務課長","answer":"先ほど少しお伝えしたのですけれども、企業とか、個人事業主の方から、横のつながりが少しずつできつつあるのです。ですので、やはり情報提供といいますか、いろいろといただけると、大変助かります。","id":"exchange-142"},{"speaker":"高橋（し）委員","kind":"質問","question":"この理由についてお伺いします。ともあれ、計上がないことについてご説明をお願いします。","respondent":"加島財政課長","answer":"都市計画交付金についてですけれども、現在の交付要綱上、素直に交付対象であると判断できる事例ではないとの見解を都側から示されております。そのため、東京都のほうに事業の概要について情報共有を行いまして、現在、具体的な相談を行っているところです。","id":"exchange-143"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"そうすると、区の主張と、東京都の主張を、簡潔で結構ですので教えてほしいと求めました。何があってもというのは、言い方があれですけれども、全額認めてもらうべきだと思いますけれども、その辺りはいかがか尋ねました。","respondent":"加島財政課長","answer":"ただ、今後の使用イメージですとか、しつらえ等の質疑について、具体的にやり取りを始めたところとなっております。過去、区側の主張を粘り強く都へ届けながら、都市計画交付金の獲得に向けて調整を進めてまいりたいと考えております。","id":"exchange-144"},{"speaker":"高橋（し）委員","kind":"質問","question":"３３億円にかかることですから、きちんと説明して、都の解釈を区の解釈に合わせていただくということが必要だと思います。次には、特別区債４１億５,０００万円についてお伺いします。","respondent":"加島財政課長","answer":"令和１２年度の償還時に借り換えを行う予定ですけれども、減債基金を活用いたしまして、元金の一部の償還に充ててまいります。令和７年度以降、新庁舎整備分として２５億円を減債基金のほうに積み立てまして、約４１３億円の返済に充てていく考えです。","id":"exchange-145"},{"speaker":"高橋（し）委員","kind":"意見","question":"ということは、単純に割っても９０億円をあと４回やらなければいけない。それが全て２０年かかって償還していくという、９０億円という金額は少し置いておいて、考え方がそれで正しいかどうかお願いしますとの意見を述べました。","respondent":"加島財政課長","answer":"令和８年度から１１年後の払いにつきましては、また支払額が変わってまいりますので、借入額も決定してまいりたいと考えております。もちろん予算編成前にはきちんと見込額をお示ししたいと考えています。","id":"exchange-146"},{"speaker":"松本委員","kind":"質問","question":"引き続きの中で、今度は私のほうでは、将来世代との関係で伺いたいと思います。３０年、あるいは５０年ぐらいの財政のシミュレーションが、品川区の中で数字としてお持ちなのかお伺いいたします。","respondent":"加島財政課長","answer":"５年先の財政収支というところでは、行政サービスの需要等の上昇によりまして、同様に増加見込みでおります。大変大きな課題認識を持っておりまして、区の財源の確保にも寄与するものというところで取組を進めてまいりたい、そのように考えております。","id":"exchange-147"},{"speaker":"松本委員","kind":"質問","question":"どうなったかと言ったら、２０３０年までのお話をされましたけれども、２０３０年から年間１００億円が足りなくなるというふうな結果になったのです。２０４０年、２０５０年までやったほうがいいと思うのですが、いかがか尋ねました。","respondent":"加島財政課長","answer":"委員からご提案がございました１０年、２０年先を見据えての財政シミュレーションというところですけれども、今の時代において福祉サービスの充実を図るとともに、ご提案のあった財政シミュレーションにつきましても、研究して取り組んでまいりたいと、そのように考えております。","id":"exchange-148"},{"speaker":"松本委員","kind":"質問・要望","question":"これだけやってほしいなと思うけれども、将来の子どもたちのことを考えたら、それは要望できないよねというふうな形も生まれてくると思います。なので、ぜひともこれは、改めて強く財政シミュレーションをやっていただきたいというふうに要望したいと思います。","respondent":"小林新庁舎建設担当課長","answer":"新庁舎につきましては、実施設計を進めている最中で、間もなくまとまるところです。今の段階では、どうなるかというところについては、手持ちでは持っておりません。","id":"exchange-149"},{"speaker":"松本委員","kind":"質問","question":"どんどん建設費は上がっていますので、そこの部分はきちんとした負担をしていただくようにお願いして、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-150"},{"speaker":"藤原委員","kind":"質問","question":"１６７ページ、区史等有料頒布収入、品川歴史館資料等となっているのですけれども、「等」とは何ですか。社会福祉法人にいらっしゃって、次長としてやっているそのキャリアを活かしていくと考えていますので、その辺についてお伺いしたいと思います。","respondent":"高梨都市計画課長、三ツ橋荏原保健センター所長","answer":"区史等頒布収入の中に含まれているものですが、例えばという一例になりますけれども、都市計画課のほうから発行している都市計画図であるとか、品川のまちづくりといった冊子等の収入が入ってあります。こちらにつきましては、順調に進んでいるところです。おかげさまで、令和８年５月に荏原保健センターは移転する予定はそのまま変わらず、遅滞なく実施しています。","id":"exchange-151"},{"speaker":"藤原委員","kind":"質問・要望","question":"せっかくですから伺いたいというのと、歴史館で売っているものとか、区政資料室で売っているものとかあるのです。いかがか尋ねました。","respondent":"福地大井保健センター所長、大森文化観光戦略課長、勝亦総務課長","answer":"これまで保健師として長年にわたり区民の皆様一人一人の健康と幸せを第一に考え、相談者や、そのご家族に寄り添って支援活動に従事してまいりました。私からは、歴史館のキャッシュレスのことについて、頒布資料が約１００種類程度ございまして、令和６年度、１２０万円弱を売上げています。総務課でも区史等有料頒布収入、まさに区史等も販売しています。","id":"exchange-152"},{"speaker":"藤原委員","kind":"質問","question":"どういう形でなったかというのは、総括質疑のときに副区長にお伺いしますので、まず特別区財政調整交付金が１点。上がった。","respondent":"加島財政課長","answer":"委員がおっしゃるとおり、特別区民税、それから特別区財政調整交付金につきましては伸びまして、こちらが歳入を押し上げている１つの要因となっております。","id":"exchange-153"},{"speaker":"藤原委員","kind":"質問","question":"これ、なぜ入れなかったのですか。いや、私は施政方針に入れるべきだと思いますよ。","respondent":"崎村企画課長","answer":"施政方針の記載につきましては、特に区としての重点的な取組事例等も挙げさせていただきながら書かせていただいています。予算の部分の記載として、今お話にあった事務事業評価で１％を満たした、これは令和６年の施政方針のときでもお示しをさせていただきましたけれども。","id":"exchange-154"},{"speaker":"藤原委員","kind":"質問","question":"品川区なのだから、品川区の人口がどうなりますとか、品川区の出生率がどうなるとか、そういうことを施政方針に書くべきですよね、品川区なのだから。","respondent":"崎村企画課長","answer":"なかなかお答えしづらい部分はありますけれども、区民の皆さんに、日本の社会経済情勢がどのようなものになっているのか。品川区のことを第一に考えていかなければいけませんけれども、国の事例等々も挙げさせていただきながら施政方針に書かせていただいたところです。","id":"exchange-155"},{"speaker":"藤原委員","kind":"確認","question":"８ページ、特別区税なのですけれども、税務課長、徴収率は２３区でトップですよね。それの確認をします。","respondent":"吉野税務課長","answer":"現在ですけれども、令和６年度を見ますと、前年よりも収納は多くなってあります。まだ順位等は出ていないのですけれども、このまま収納率を伸ばしていきたいと考えております。","id":"exchange-156"},{"speaker":"藤原委員","kind":"質問・要望","question":"本当に徴収率、それを求めるわけではないですけれども、対面でお客様と会うわけですから大変だと思いますが、職員の方、労ってあげてください。本当に大変だと思いますので、こういう数字が出てくるわけですから、お願いします。","respondent":"吉野税務課長","answer":"たばこ税なのですけれども、こちらは、税制大綱が発布されまして、令和８年の４月と１０月の２段階で引き上げは決まっております。","id":"exchange-157"},{"speaker":"藤原委員","kind":"質問","question":"生活安全担当課長、たばこを吸う場所をつくってくださいと言っても、いい返事をいつもくれないではないですか。いかがか尋ねました。","respondent":"河合生活安全担当課長","answer":"喫煙所の整備につきましては、税収というところもあるのですけれども、環境と課題に即したところでやっていくですので、また、たばこ税でというところは、その必要性については研究してまいりたいと思います。","id":"exchange-158"},{"speaker":"藤原委員","kind":"質問","question":"生活安全担当課長、今日、これで終わらないですから。今日はこれで終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-159"},{"speaker":"石田（ち）委員","kind":"質問","question":"私からは、１５４ページの物品売払収入の防災ラジオ売払代金と、あと、１７８ページの議会費から、行政視察について伺いたいと思います。防災行政無線について、聞こえづらい点の改善は何かされてきているのか伺いたいと思います。","respondent":"羽鳥防災体制整備担当課長","answer":"そういった課題も踏まえ、平成２４年度から防災ラジオを導入いたしまして、室内でも防災行政無線の音声が聞けるような体制をとっているところです。しなメール、ＬＩＮＥ等でも防災行政無線と連携いたしまして、文字情報で確認をできるというような体制をとっているところです。","id":"exchange-160"},{"speaker":"石田（ち）委員","kind":"質問","question":"区民の方からは、とてもクリアに聞こえたという声も寄せられておりまして、他区の防災行政無線の仕組みと違いはあるのでしょうか。ビルの高さとか、そういうところもあると思うのですけれども、そもそもの仕組みの違いはあるのか尋ねました。","respondent":"羽鳥防災体制整備担当課長","answer":"現在の防災行政無線は、令和４年度以降、デジタル化をいたしまして更新を図っているところです。それに合わせまして、防災ラジオも更新をしています。","id":"exchange-161"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"その防災ラジオについて伺っていきたいのですけれども、６５歳以上の高齢者は１,０００円、そして非課税世帯にも１,０００円で販売されていると。本体価格と、あと販売実績、新しくなってからの防災ラジオの販売実績を教えてほしいと求めました。","respondent":"羽鳥防災体制整備担当課長","answer":"金額といたしましては４１５万円。金額といたしましては１１４万８,０００円、４,７２４台、金額といたしましては５２９万８,０００円という状況です。","id":"exchange-162"},{"speaker":"石田（ち）委員","kind":"確認","question":"きちんと情報が入ってくるのだなということが確認できたわけですけれども、港区は住民税非課税と生活保護世帯は無償で配布されております。１０倍とまではいかないのですけれども、この無償の枠を設けていただけたらと思うのですけれども、いかがか尋ねました。","respondent":"羽鳥防災体制整備担当課長","answer":"「妥当」とご回答いただいた方が５０％、こちらを合計しますと、９６％の方が「安い」方等々ということでご回答をいただいたところです。今後そういった取組をしていきたいというふうに考えてあります。","id":"exchange-163"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"これまで経年的な行政視察の経費を伺いたいと思いましたけれども、時間もなくなってきていますので。この報告書を、やはり税金をかけていますので、区議会ホームページに掲載すべきということを求めてきておりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-164"},{"speaker":"あくつ委員","kind":"質問・要望","question":"後ほど質問と答弁を求めますので、その前提で、少し所見を述べますので、委員長、少しご容赦ください。これ、言っていませんけれども、財政課長、企画課長、この本はお読みになられましたか尋ねました。","respondent":"崎村企画課長、加島財政課長","answer":"昨年の施政方針の中にも書かせていただいたように、区長が井手教授のお話をお聞きしたということを伺いまして、私も井手教授の本を購入しまして、自席の横に置いてあります。私のほうでも書籍を拝読させていただきました。","id":"exchange-165"},{"speaker":"あくつ委員","kind":"質問","question":"議会質問等で真剣にお伝えしてまいりました多胎児の保育園の入園点数加算、大胆かつ積極的に実行されてきた森澤区政をこの目で見てまいりました。今回の施政方針および令和７年度予算案、つまり、提唱者である井手教授はどのようにご覧になられたのか伺います。","respondent":"森澤区長","answer":"施政方針、施政方針に示されている令和７年度予算案につきまして、社会像が調和しているというふうに評価をいただいております。施政方針で示したそういった予算案につきまして、石破首相が何度か答弁をするというような、そういった場面もありました。","id":"exchange-166"},{"speaker":"あくつ委員","kind":"提案","question":"相互の議会質問において、深まりを求めてまいりましたので、首長同士の早速のトップ交流を大変に頼もしく思っております。その後の検討状況について伺いますとの意見を述べました。","respondent":"勝亦総務課長","answer":"具体的には、区としましては、早川町、山北町、水と緑の交流、それ以外にも、福井県坂井市、それから高知県との連携交流等を行っております。そういった中で、双方で一緒に具体的に、どのように効果的な交流ができるか、一緒に考えていきたいと考えております。","id":"exchange-167"},{"speaker":"あくつ委員","kind":"提案","question":"私ども会派の代表質問において、元旦号の新春対談で、佐藤市長から、疎開保険のご提案があったことを取り上げました。佐藤市長の提案に対し、そういった意味で、よい取組ではないかと応じておられましたとの意見を述べました。","respondent":"勝亦総務課長","answer":"特産品をお送りするような、そういった交流を促進する保険の形をとっていたと思います。どういった形の特産品を送ったら喜ばれるのかですとか、一緒になって、一生懸命、それぞれにメリットのある疎開保険にしていきたいと考えております。","id":"exchange-168"},{"speaker":"あくつ委員","kind":"提案","question":"このような提案を私どもから単発で議会から申し上げ確認するということも重要だと思います。いかがか尋ねました。","respondent":"勝亦総務課長","answer":"それから議員の方のご支援、双方が一緒に考えて、効果的なものを進めてきたというのが実感です。そういった中で、飯田市とも交流していきたいと思います。","id":"exchange-169"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"ですので、やはり議会として、事実関係はしっかりと確認して、第一会派として、責任ある政策提言を行っていきたいと考えております。","respondent":"伊崎教育長","answer":"私から、学校給食への有機特別栽培野菜導入に至った背景として、その考え方についてご説明します。農地が全くない品川区であるからこそ、政府の方針と軌を一にする形で、子どもたちに地球環境に優しい食材を利用してまいります。","id":"exchange-170"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"丁寧な対応が絶対に必要ですし、声を聞く、必ず声を聞いていただきたいと思っています。既存の納入業者、栄養士には、当たり前ですけれども、真摯に向き合っていただくことを強く求めますが、ご見解を説明するよう求めました。","respondent":"伊崎教育長","answer":"例えば、万が一にでも野菜に虫が混入することが決してないような納入要件の設定など、様々な方策を検討してまいります。もとより市場の動向や現場の実情を踏まえながら、こうした関係する皆様とともに進めていける持続可能な方策を適切かつ柔軟に検討してまいります。","id":"exchange-171"},{"speaker":"まつざわ委員","kind":"質問","question":"給食の中では財源のお話も出ました。これは１７億円のうち２,８００万円ぐらいですか、約１.６％になると思いますが、どこから捻出する予定なのか説明するよう求めました。","respondent":"伊崎教育長","answer":"なお、今回の給食費予算についてですが、有機食材の導入とは別に、１食当たりの単価を５０円程度の引き上げを予定し、予算案に計上しております。物価高騰対策はもとより、学校給食の質と量の充実、そして日本の農業の持続性に資する環境に優しい給食の提供をしてまいります。","id":"exchange-172"},{"speaker":"まつざわ委員","kind":"提案","question":"それで、また提案ですけれども、○○○こうやって進めていくよりも、例えば、すみません、言葉を間違えました。例えば、試行期間で少しチャレンジしてみるとかいって、そういった感覚も必要かなと思いますけれども、すみません、時間がなくてとの意見を述べました。","respondent":"伊崎教育長","answer":"は今回の取組、新規施策ですので、トライアルと捉え、柔軟かつアジャイルに進めていく、こうした形で随時改善を図っていきたいと思います。","id":"exchange-173"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/619855?Template=document&Id=7003#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":129343,"voices":411}},{"id":"r07-20250305-10","meetingId":"r07-cm03","date":"2025年3月5日","dateIso":"2025-03-05","committee":"議会運営委員会","time":"午後 ７時３０分～午後 ７時４４分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を2件整理しています。","topics":[{"id":"topic-01","title":"品川区議会個人情報の保護に関する条例施行規程の一部改正","agenda":"品川区議会個人情報の保護に関する条例施行規程の一部改正","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"議長決定ではあるのですが、今日この場で１回目、初めて出されたということなので、決定については次回の議運で質問させてほしいと求めましたが、いかがか尋ねました。","respondent":"大澤区議会事務局長","answer":"施行日を２４日と考えているのですが、いかがでしょうか。","id":"exchange-001"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"確認ですが、先ほど終わりました予算特別委員会の中で、西本委員の最後、質疑の中で議運に対して意見を言いたいということの表明があったのですが、今の時点では来ていないということなのか、それはどのような形で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/350163?Template=document&Id=6977#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":5376,"voices":33}},{"id":"r07-20250307-3","meetingId":"r07-c-budget","date":"2025年3月7日","dateIso":"2025-03-07","committee":"予算特別委員会","time":"午前 ９時３０分～午後 ５時１０分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を182件整理しています。","topics":[{"id":"topic-01","title":"令和７年度品川区一般会計予算","agenda":"令和７年度品川区一般会計予算","exchanges":[{"speaker":"高橋（伸）委員","kind":"質問","question":"同じく１８９ページ、２０７ページ、荏原町安全安心ステーション運営経費についてお伺いします。初めに、１８９ページの新年賀詞交換会経費についてお伺いいたします。","respondent":"勝亦総務課長","answer":"区では毎年、関わり合いの深い地域団体ですとか各種団体、官公署の方々をお招きいたしまして実施しています。新年の挨拶と日頃の感謝を伝えるとともに、親睦を兼ねて連携を深める機会として実施しています。","id":"exchange-001"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"コロナ禍のときには開催していなかった時期もあったかと考えています。恐らく１,０００人ぐらいの方にご案内をしているかと思うのですけれども、令和５年度、令和６年度の出席人数を教えてほしいと求めました。","respondent":"勝亦総務課長","answer":"新年賀詞交換会ですが、例年２,０００人程度の方にご招待状を出しています。出席人数ですけれども、令和５年度が５４２人、それから、令和６年度が５６８人となっています。","id":"exchange-002"},{"speaker":"高橋（伸）委員","kind":"質問","question":"すみません、２,０００人ということで、失礼いたしました。令和５年度が５４２人、今年度が５６８人という人数に対して、この出席人数についてはどのようにお考えになっておられますか尋ねました。","respondent":"勝亦総務課長","answer":"４０％から５０％の方のご出席をいただいていたところですけれども、直近２年間で５００人台ということで、３割を切る出席になっている状況です。出席者がやはりコロナ禍を経て減少しているという傾向と見てあります。","id":"exchange-003"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"何名かお話をお聞きしますと、一定数ですが、あるのは事実です。本当の軽食でいいと思うのですけれども、今後検討していただきたいという声が要望としてあるのですけれども、どのように考えておられるか尋ねました。","respondent":"勝亦総務課長","answer":"コロナ禍を経まして、令和５年度以降につきましても、やはり新しい生活習慣という部分も含めまして、飲食の提供は取りやめてあります。","id":"exchange-004"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"次に、同じく１８９ページ、坂井市区民交流ツアーについてお尋ねします。こういった動画を含めて、来年度、具体的にどういうふうに坂井市と関わっていくのかというのをお尋ねさせてほしいと求めました。","respondent":"大森文化観光戦略課長","answer":"坂井市と連携したＰＲ動画作成ということで、次年度も作成する予定になっております。こちらのほう、品川区から声をかけまして、高知県と坂井市と３自治体連携ということで作成している動画となっております。","id":"exchange-005"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"続いて、２０７ページの荏原町安全安心ステーション運営経費についてお伺いいたします。初めに、荏原町安全安心ステーションについてのご説明をお願いいたします。","respondent":"河合生活安全担当課長","answer":"平成１９年、いろいろ落とし物の受け取りとか、何かあったときの１１０番通報等をしていただく防犯拠点として立ち上がったものです。","id":"exchange-006"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"毎年更新のご案内が１１月に来るところですが、今もって案内が来ていないということで、協力者の方からどうなっているのだろうという声もあります。","respondent":"河合生活安全担当課長","answer":"そういったことと、今猛暑日とか、推進員の方々の体の負担等もありますので、今後どうあるべきかということで検討いたしました。詳細につきましては、区民委員会でも報告をさせていただきまして、決定したいと考えております。","id":"exchange-007"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"それで、２２９万円余という予算がついています。これについては、今後、１０月までということなのですが、どういうふうな使い方というか、どういう方向性でいるのかお知らせほしいと求めました。","respondent":"河合生活安全担当課長","answer":"恐らく９月末、上半期終了後というところで検討しているところですが、廃止となったところで差額となるような形で考えております。源氏前交番の近くにあるという現状もありますので、そういったことも踏まえて決定しております。","id":"exchange-008"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"例えば、荏原町支え愛・ほっとステーションなどという手法もあるかと思いますので、併せて要望させていただいて終わりにしたいと思います。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"新妻委員","kind":"質問・要望","question":"会派からも要望しております授乳室で搾乳をしたい方がお一人でも気兼ねなく利用ができるよう、この状況を併せてお伺いいたします。そして、防犯カメラ、インターホンのみではなく、もう少しメニューを広げてほしいと求めましたが、見解を伺います。","respondent":"長尾施設整備課長、河合生活安全担当課長","answer":"区有施設の授乳室における防犯ブザーの設置状況について、まずご説明いたします。利用者の方に分かりやすく案内できるように、こちらのほうとしても、施設側と協力して案内を進めていきたいと考えております。なお、区も都の助成事業を受けまして、当然、都のほうで２万円、２分の１というところで、そこに上乗せする形で検討しています。","id":"exchange-010"},{"speaker":"新妻委員","kind":"質問・要望","question":"区議会では、先日の本会議で、選択的夫婦別姓について議論を尽くすことを国会及び政府に求める意見書が賛成多数で可決されました。夫側のチェックを外し、どちらかにチェックをとするように改定をしてほしいと求めましたが、見解を伺います。","respondent":"築山戸籍住民課長","answer":"婚姻届の記入例についてです。委員ご指摘の点を踏まえまして、記入例の見直しについて検討してまいります。","id":"exchange-011"},{"speaker":"新妻委員","kind":"質問・要望","question":"早急にご検討をお願いをいたしまして、改訂を求めたいと思います。これは国へ求めることですけれども、呼びかけも行ってほしいと求めましたが、いかがか尋ねました。","respondent":"築山戸籍住民課長","answer":"品川区含めて１０区が賛同して国に申し入れを行ったところですが、そうでない区につきましては、それぞれの区のご判断かと認識をしています。今後の動きですが、国の動向を注視しながら、品川区としてできる施策について考えてまいりたいと思います。","id":"exchange-012"},{"speaker":"新妻委員","kind":"質問","question":"分かりました。３つほど、各自治体で進めることができるのではないかと私は受け止めたのですが、そこら辺の見解はいかがか尋ねました。","respondent":"築山戸籍住民課長","answer":"委員がおっしゃられるように、当事者の方に事前の説明をしまして、同意書を書いてもらった上で対応しているです。やはり今回の件でいきますと、国から全国統一的な対応が求められるということで、難しい状況かと考えております。","id":"exchange-013"},{"speaker":"新妻委員","kind":"質問・要望","question":"引き続き、品川区民でも求めている方が多くいらっしゃると思いますので、区でできることの対応をしっかりとご検討を続けてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"ひがし委員","kind":"質問","question":"私からは、１９５ページ、ジェンダー平等推進事業、そして、２２１ページの戸籍・住民基本台帳関係費について順不同でお伺いいたします。そこでお伺いいたします。","respondent":"築山戸籍住民課長","answer":"オンライン請求およびコンビニ請求等で対応は可能となっております。一方、法人請求、士業に対しては、現在、オンライン請求等の対応は行っておりません。","id":"exchange-015"},{"speaker":"ひがし委員","kind":"確認","question":"個人ではオンライン化が進んでおり、士業、法人については、まだオンライン化はできていないということが確認ができました。取扱い通数についてお伺いします。","respondent":"築山戸籍住民課長","answer":"それぞれの回答になりますが、全体が１１万１,７４９通、これは令和５年度の実績です。法人および士業による職務上請求の割合ですが、窓口で申請される方は１１％、郵送で請求される方は８９％となっております。","id":"exchange-016"},{"speaker":"ひがし委員","kind":"質問・要望","question":"さらに、その都度申請者への電話確認が必要となり、電話がつながらなければ何度もかけ直すということになるそうです。なかなか個人情報の確認などの点があり、士業、法人が参入できていないというような課題が残っております。","respondent":"築山戸籍住民課長","answer":"一方、法人や士業の場合は、本人確認ができるものがなく、紙で要件を確認しています。その書類確認とキャッシュレス決済を結びつけるためのシステムが必要になってくるといったような課題がありまして、現状は対応していないです。","id":"exchange-017"},{"speaker":"ひがし委員","kind":"質問・要望","question":"まだですかというお問合せを多分区としてもいただいていると思うのですが、また、最後にそちらについてお答えください。東京２３区ではまだ導入している実態はないのですが、ぜひそちらについても検討を進めてほしいと求めました。","respondent":"築山戸籍住民課長","answer":"企業が収益事業として行うことに対して、区がどこまで負担すべきかといった課題がありますので、ここはもう少し検討が必要だと考えております。","id":"exchange-018"},{"speaker":"ひがし委員","kind":"質問・要望","question":"品川区の職員の業務改革という視点でも、ぜひ前向きに進めていただきたいなと思います。検討していくというようなお話がありましたが、現在の検討状況、進捗があれば説明するよう求めました。","respondent":"築山戸籍住民課長","answer":"どなたでもご自由に記念撮影にご利用くださいという看板を設置しまして、利用しやすい環境のほうを設置させていただいたところです。区の独自サービスですので、この辺りにつきましては、同性パートナーにも交付ができるよう検討を進めていきたいと考えております。","id":"exchange-019"},{"speaker":"ひがし委員","kind":"質問・要望","question":"ぜひ前向きに進めていただきたいと思うのと、あと１点、なかなか受け取るタイミングは難しいのかなと思います。例えば、東京都のパートナーシップ宣誓制度の書類を持っている方々とかにもご案内をしてもらって、その点についていかがか尋ねました。","respondent":"築山戸籍住民課長","answer":"今、記念品等のお渡しは、戸籍の届出の窓口で行っているところです。どういった方法でやるのかにつきましては、今後検討していきたいと思います。","id":"exchange-020"},{"speaker":"ひがし委員","kind":"質問","question":"次に、ジェンダー平等推進事業についてお伺いいたします。こちらについての予算の内訳について説明するよう求めました。","respondent":"木村人権・ジェンダー平等推進課長","answer":"委員お尋ねのところのＤＶ・カウンセリング・にじいろ相談の内訳になります。ＳＮＳ相談委託が６１８万２,０００円、にじいろ相談が１２３万７,９００円、４６万６,０００円を計上しております。","id":"exchange-021"},{"speaker":"ひがし委員","kind":"意見","question":"このこころのカウンセリングＳＮＳ相談の実績がどのぐらいなのか、また、品川区では、品川区版あなたのいばしょチャット相談も始まっております。そちらとのすみ分け、違いについても説明するよう求めました。","respondent":"木村人権・ジェンダー平等推進課長","answer":"こちらは令和６年７月から開始しておりまして、ＳＮＳ相談の件数が３０件になっております。友人、自分の体のことですとか、いろいろな相談を受けている状態です。","id":"exchange-022"},{"speaker":"ひがし委員","kind":"提案","question":"若い世代も相談がしやすいかなということで、前回も提案させていただきましたので、ぜひ進めていただきたいなと考えています。さらに幾つかご要望いただいておりまして、日付を変えたりとか、時間帯を夜にもしてほしいというようなご要望もいただいておりますとの意見を述べました。","respondent":"木村人権・ジェンダー平等推進課長","answer":"基本的に今、第２・第４土曜日の１０時から１６時半までやっておりまして、その時間にいらしていただける方ということで対応しております。心の診療的な話、カウンセリングの専門家等も必要になりますので、そちらに対応できる方をお願いしている状態です。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問","question":"伺いますが、５種類の新聞・雑誌を個人に購入というのは行き過ぎで、いかがでしょうか。削減すべきと思いますけれども、いかがか尋ねました。","respondent":"木村人権・ジェンダー平等推進課長","answer":"こちら、全ての方々にきちんと理解をしていただく必要があるというところが、購入している理由になります。特に管理職に関しましては、常に意識をしていただかないといけないというところがありますので、こちらを購入しているという理由になっております。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問・要望","question":"この３行目の会計年度任用職員給与費１人、５１５万２,０００円とは、これは同和生活相談員だと事前に伺っております。相談の実態について幾つか伺いますが、この３６８件は、相談者の実人数は何人か伺いたいと思います。","respondent":"木村人権・ジェンダー平等推進課長","answer":"電話が２１６件、来所が７８件、出張が７４件ということです。税金・金融に関しては３件、差別事象については４件、その他が２５０件余ということになっております。","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問","question":"相談の記録は取られているのかいないのか伺います。なぜ相談室を見せることができないのか伺いたいと思います。","respondent":"木村人権・ジェンダー平等推進課長","answer":"そういったことに関わっているというか、どういう相談をここでしていて、どういう形で対応しているというのが分かってしまう。プライバシーの保護も含めて、詳細について公表することができないと考えております。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"伺ったら、週５日ということでしたので、相談者もここへ来る心配はないのです。同和生活相談は、一般の人権相談に統合して、抜本的に解消するよう求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"筒井委員","kind":"質問・要望","question":"１期目から、会議録を公開してほしいということをずっと主張してきておりましたし、昨年の一般質問でも公開を求めさせていただきました。その辺り、やはり少し注意されたのか、その公開に当たって何かそうした課題とかはあったのか尋ねました。","respondent":"勝亦総務課長","answer":"これについては、より透明性のある議論の公開という考え方で公開を行ったものです。やはり委員の自由な発言を確保する観点から、それぞれの委員の発言については、特定できないように伏せさせていただいているものです。","id":"exchange-028"},{"speaker":"筒井委員","kind":"質問","question":"去年の一般質問でも、これに関連して質問させていただいたのが、女性比率は４０％以上になっておりますでしょうか。特別職報酬等審議会以外でも、女性比率が４０％以上ということは達成されているのか尋ねました。","respondent":"勝亦総務課長","answer":"特別職報酬等審議会の女性委員の比率ですけれども、現在２０％という状況です。他の会議体につきましては、把握している限りにおきましては、現状４０％を超えているものが４会議体あります。","id":"exchange-029"},{"speaker":"筒井委員","kind":"質問・要望","question":"そのお考え、特別職報酬等審議会を含めて、女性比率の４０％以上の達成のほどよろしくお願いを申し上げます。すなわち、障害者・高齢者の方々の観光に当たっての合理的配慮を都市型観光プランに記載して、現在の進捗状況はどうなっていますか尋ねました。","respondent":"大森文化観光戦略課長","answer":"こちらは、品川区の都市型観光プランの見直しの際には入れていくというようなことで回答した記憶があります。どういったツアー造成が、誰もが楽しんでいただける観光の実現になるのかという環境づくりをよく検討して進めてまいりたいと思います。","id":"exchange-030"},{"speaker":"筒井委員","kind":"質問・要望","question":"そうした観点から、東京都で「２０５０東京戦略」ということで、ナイトタイム観光を推進するということが明記されました。ぜひナイトタイム観光という視点を今後の品川区の観光施策に反映していってほしいと求めましたけれども、その点、いかがお考えか尋ねました。","respondent":"大森文化観光戦略課長","answer":"「２０５０東京戦略」にも、ナイトライフ充実度で３０位だった東京都が、８位に上がったというような記載も確認しています。東京都の助成制度等が出た際には、関係団体に周知をしながら、一層のにぎわいを図ってまいりたいと考えています。","id":"exchange-031"},{"speaker":"筒井委員","kind":"質問・要望","question":"そして、まちも明るくしていってほしいと求めましたので、よろしくお願いします。なぜこの予算特別委員会でそのロゴマークとかキャッチフレーズを発表できなかったのか、その辺りをお伺いします。","respondent":"與那嶺戦略広報課長","answer":"しかるべきところでということで検討してきたところではあったのですけれども、現状、３月下旬の日程という形で準備をしています。改めて、出来上がったデザインなどにつきましては、議会の皆様にもご説明をさせていただきたいと考えています。","id":"exchange-032"},{"speaker":"筒井委員","kind":"質問","question":"本当は議員の皆さんも意見がいろいろあったかと思うのですけれども、そういった現状でしたらもう仕方がないので、ロゴを楽しみにしております。適宜区民の皆さんの反応を確かめる必要があると思うのですけれども、その辺り、できた後のことはいかがお考えか尋ねました。","respondent":"與那嶺戦略広報課長","answer":"委員おっしゃるとおり、やはりこの新しくできるブランドデザインやメッセージをしっかりと周知して理解を深めるということは大事だと考えています。区で関わる団体の方や企業の方にも使っていただくであるとか、そういった広がりを持った活用を考えてあります。","id":"exchange-033"},{"speaker":"せらく委員","kind":"質問","question":"こちらのＤＶについてなのですけれども、毎月４日程度相談の日程が設けられていますが、こちらの予約状況を伺いたいと思います。近年の傾向を説明するよう求めました。","respondent":"木村人権・ジェンダー平等推進課長","answer":"令和６年度、こちら、２月末までの時点ですけれども、６５件ありまして、内訳としては、面接４４件、電話２１件となっております。特にＤＶに関しては身体的な暴力ですとか、複合して相談を受けることが多いので、モラルハラスメントのみの集計は取っておりません。","id":"exchange-034"},{"speaker":"せらく委員","kind":"質問","question":"学校教育では人権についても学んだりするのですけれども、大人は、知識があるかもしれないけれども、より意識していくべきだと思っています。","respondent":"木村人権・ジェンダー平等推進課長","answer":"ＤＶの相談を受けたいですとかというように、話の中でご自身の気持ちが固まってくることがありますので、様々なところで受けるようになっております。","id":"exchange-035"},{"speaker":"せらく委員","kind":"確認","question":"様々な相談をお受けしているということなのですけれども、加害者からの相談も受け付けているか、いま一度確認したいと求めました。","respondent":"木村人権・ジェンダー平等推進課長","answer":"モラハラの加害者からの相談も受けているかということなのですけれども、加害者からの相談もお受けします。ただ、実際の件数としてはかなり少なくて、今のところ、近年では、昨年１件、ご自身からご相談があったという記録がありました。","id":"exchange-036"},{"speaker":"せらく委員","kind":"質問","question":"港区では、ＮＰＯなどの団体が行う更生プログラムの初回面談費用を、上限１万円なのですけれども、助成していて、担当者からお話を伺ってきました。こちらについて見解を伺えればと思います。","respondent":"木村人権・ジェンダー平等推進課長","answer":"大体年に１人程度と先ほどおっしゃっておられましたが、効果ですとか取組方法として考えていかなければいけないところかなとは考えております。グルーミングについての講座を実施しましたところ、フォーラムですとか、そういった形のところでも周知啓発に努めてまいります。","id":"exchange-037"},{"speaker":"せらく委員","kind":"質問・要望","question":"ジェンダー平等推進センターで開催されたとお聞きしまして、あと、託児の工夫もされていらっしゃるとホームページで確認をいたしました。後日の視聴ができるように、ぜひアーカイブ映像なども残していただけるといいと思うのですけれども、いかがか尋ねました。","respondent":"木村人権・ジェンダー平等推進課長","answer":"先週、男性のための生き方講座ということで、先生をお呼びして、「これまでとこれからの男性学」という講座を実施いたしました。できるだけ時間帯についても、今年から夜の時間帯で固定をして実施しておりますが、引き続き考えていきたいと思います。","id":"exchange-038"},{"speaker":"横山委員","kind":"質問","question":"私からは、１８９ページ、グローバル人材育成海外派遣事業、２０９ページ、しながわツアー造成補助についてお伺いいたします。１点目に、グローバル人材育成海外派遣事業についてお伺いいたします。","respondent":"勝亦総務課長","answer":"グローバル人材育成海外派遣事業についてお答えします。今回グローバル人材育成の海外派遣につきましては、事業名のとおり、グローバルな社会に対応する人材を育成するという目的で設定しています。","id":"exchange-039"},{"speaker":"横山委員","kind":"質問","question":"詳しくお伺いしてきたいのですけれども、なぜアントレプレナーシップ教育で、その理由と背景を教えてください。事前のオリエンテーション、事前学習や報告会などは実施するのか尋ねました。","respondent":"勝亦総務課長","answer":"事前の学習ですとか事後学習、報告会は実施する予定ですけれども、詳細なスケジュールについては、今後決定してまいります。部門との連携等ですけれども、実施事業者のほうにも、区内の団体との連携を盛り込んだ内容とするよう求めております。","id":"exchange-040"},{"speaker":"横山委員","kind":"質問・要望","question":"２点目に、しながわツアー造成補助についてお伺いいたします。忍者になれるまちを目指すべきビジョンとして、水口岡山城跡で忍夜討２０２４を開催したり、周遊プランを展開した事例をお伺いしました。","respondent":"勝亦総務課長、大森文化観光戦略課長","answer":"本事業は、来年度実施させていただきたい新規の事業です。これを継続していく中で、他の団体ですとか、後の後輩の方々、そういった方への展開、継続的な実施を考えてまいります。それをツアーに組み込んでいっていただいた、その旅行事業者に支払う補助金ということで、そういったことで掘り起こしを図っていきたいと思います。周知については、観光協会等の力を借りて周知を図ってまいりたいと思います。","id":"exchange-041"},{"speaker":"えのした委員","kind":"質問","question":"私からは、２０１ページ、地域振興事業、２１５ページ、少年少女スポーツ普及事業についてお伺いします。少年少女スポーツ普及事業についてお伺いします。","respondent":"三井スポーツ推進課長","answer":"子どもたちがスポーツに親しむことや、体力の向上をはじめ、子どもたちの健全育成を図ることを目的としております。","id":"exchange-042"},{"speaker":"えのした委員","kind":"確認","question":"確認が取れました。各種スポーツ大会の開催やスポーツ活動の場の開放をしているということで、そちらの概要や参加者人数、利用者数を示すよう求めました。","respondent":"三井スポーツ推進課長","answer":"こちらは少年少女スポーツ団体と共催で実施している区長杯や教育長杯といった大会のことになりまして、野球、バスケットボールの４種目となります。次に、ひらさん広場や学校の校庭などの開放をしておりますが、昨年度の利用者数は約３万６,０００人ほどとなっております。","id":"exchange-043"},{"speaker":"えのした委員","kind":"質問・要望","question":"このような評価ですから、令和６年度も夏季期間の利用が減っていると予想されると考えます。各種スポーツ団体から私たち会派のほうにも要望がありましたけれども、熱中症対策について、こちらは進んでいますか尋ねました。","respondent":"三井スポーツ推進課長","answer":"区と各少年少女スポーツ連盟と共催で実施しているところになりますので、屋外で実施している区長杯や教育長杯といった大会の際に、熱中症予防のための物品を購入する経費の支援ができるように準備を進めているところです。","id":"exchange-044"},{"speaker":"えのした委員","kind":"確認","question":"確認が取れました。次に、地域振興事業、地域課題の自主的解決支援についてお伺いします。","respondent":"宮澤地域活動課長","answer":"ご相談や助言などを行いながら伴走的に支援するもので、令和４年度からこれまで１６町会を支援してきたところです。今年度は、マンションとの関係づくりに関しましては、今月にはこのガイドブックの活用について町会向けに説明を行うといったところです。","id":"exchange-045"},{"speaker":"えのした委員","kind":"質問・要望","question":"青少年委員、民生委員等々、これを丸々受け持って活動している団体がほかにあるでしょうか。マンションとの関係構築と併せて必要なのが、若い世代の方々を町会・自治会活動に巻き込んでいくということが必要と考えますが、いかがか尋ねました。","respondent":"宮澤地域活動課長","answer":"個別の特定のマンションと町会との接点というのを結びつけるような個別のコーディネート支援というのを進めていきたいと考えているところです。もしくは担い手としての参画、そういったところ、財政的な面も含めて後押しをしていきたいと考えているところです。","id":"exchange-046"},{"speaker":"えのした委員","kind":"意見","question":"とても活動のヒントにもなります。こういった活動に焦点を当て、各町会・自治会の活動の参考となるような取組があれば示すよう求めました。","respondent":"宮澤地域活動課長","answer":"これ以外にも、品川区では、町会自治会連合会のホームページで、イベントの紹介について載せています。各地域センターでも、地域ニュースということで、地域の情報も発信しているというところで、引き続き情報発信には努めていきたいと考えています。","id":"exchange-047"},{"speaker":"えのした委員","kind":"質問・要望","question":"好事例の横展開について、やはり引き続き取り組んでほしいと求めましたが、いかがでしょうか。こちらの概要などを説明するよう求めました。","respondent":"宮澤地域活動課長","answer":"続いて、これは東京都が実施しております町会・自治会向けの支援でございまして、町会・自治会が実施する地域の課題を解決するための取組を推進し。","id":"exchange-048"},{"speaker":"えのした委員","kind":"質問","question":"現状、この事業に申請している町会・自治会は、どの程度ありますでしょうか。申請は毎年可能なのか示すよう求めました。","respondent":"宮澤地域活動課長","answer":"令和５年度は９件、今年度につきましては、現在のところ１６件申請していると聞いております。申請自体は、毎年可能です。","id":"exchange-049"},{"speaker":"えのした委員","kind":"質問","question":"以前は申請していたのだけれども、品川区の助成事業とは違って、非常に手続が難しくてやめてしまったという町会もあると伺っております。ぜひ品川区でも多く活用してほしいというお話を伺ったので、区の施策、活用の実績などがありましたら示すよう求めました。","respondent":"宮澤地域活動課長","answer":"こちら、令和５年度５件、令和６年度は４件ということで、この東京都への申請に関しても受けているところです。","id":"exchange-050"},{"speaker":"つる委員","kind":"提案","question":"そうした中で、昨年の第４回定例会での一般質問、被爆ピアノの平和コンサートを提案させていただきまして、次年度事業の予算を盛り込んでいただいたとの意見を述べました。","respondent":"勝亦総務課長","answer":"今後予算をお認めいただいてから、予定としましては、来年の１２月に実施したいと考えています。具体的なピアニストなどについては、これから検討してまいりたいと考えています。","id":"exchange-051"},{"speaker":"つる委員","kind":"質問・要望","question":"ぜひ、３００人から１,０００人を超える方が直接集えるような平和の式典にできるような、そうした拡充を求めていきたいなと思います。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"中高生１０人程度を選定してまいりますが、これから具体的に検討してまいりますが、この辺りを重視してまいりたいと考えております。イベントの実施のような事業については、それから、翌年度も見据えた事業計画を子どもたちと一緒につくってまいりたいと考えているところです。","id":"exchange-052"},{"speaker":"つる委員","kind":"質問・要望","question":"例えば、そういう声かけも面白いのではないかというような懇談もさせていただいたところでありますので、こうした考えをぜひ伺いたいと思います。","respondent":"三井スポーツ推進課長","answer":"本当に区として応援が盛り上がるように、デフリンピック認知度１２０％以上プロジェクトを進めていきたいと考えています。日本代表選手を呼んでくるとか、イベントでそういった盛り上げができないかなど、方策を探ってまいりたいと思います。","id":"exchange-053"},{"speaker":"おぎの委員","kind":"質問","question":"２１１ページ、２２１ページ、戸籍・住民基本台帳関係費から振り仮名法制化対応についてお聞きいたします。次回の入学説明会は４月１８日となっていますが、近年の参加者数と応募状況について説明するよう求めました。","respondent":"大森文化観光戦略課長","answer":"近年のシルバー大学の参加者ということで、まずふれあいコースといきいきコースという２種類のコースがあります。令和６年については、ふれあいコースが１３９人、いきいきコースが３１６人ということになってあります。","id":"exchange-054"},{"speaker":"おぎの委員","kind":"質問・要望","question":"発表会には、ぜひ多くの方に来てほしいと、シルバー大学の学生から要望が出ています。事務事業評価では評価がＣとなっておりますが、その理由と、検討している改善策等があれば、併せて説明するよう求めました。","respondent":"大森文化観光戦略課長","answer":"それから、始まってから様々な生涯学習というところで、講座や体験型の講座等を進めてきているところです。そういったところを今後見直しまして、皆様に分かりやすいシルバー大学の全容をご提示していけるようにということで取り組んでいるところです。","id":"exchange-055"},{"speaker":"おぎの委員","kind":"質問・要望","question":"一般席の当日参加者には１回５００円ほどご負担いただいて、運営収入の一部にしたらどうか。他区にはないシルバー大学の存在をもっと広く知ってほしい。","respondent":"大森文化観光戦略課長","answer":"やはり内容等によって、シーズン的に皆さんのお忙しい時期というところがあって、人数がなかなか読めないところがあるです。そういった一般の方を受け入れるというところも今後検討していくというところになるのかなとは思うのですけれども、また部屋が狭くなるというような。","id":"exchange-056"},{"speaker":"おぎの委員","kind":"質問・要望","question":"これ、今年大変な作業かなと思うのですが、しっかりやってほしいと求めました。戸籍情報の取扱いは、厳密な運用を。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"吉田委員","kind":"質問","question":"それから、もう一つが、これ、企画費のどこかに入っているべきだし、入っていてほしいなと思って、法令のチェック機能について伺いたいと思います。これ、どこがチェックしているのか、まず伺いたいと思います。","respondent":"與那嶺戦略広報課長","answer":"ホームページの更新日についてのお尋ねです。こちらの更新につきましては、更新日の日付については、いずれにしろ公開された日と直接リンクしているわけではないというのがシステム上の形です。","id":"exchange-058"},{"speaker":"吉田委員","kind":"質問","question":"これ、どうにかすべきなのではないですか。伺いたいと思います。","respondent":"與那嶺戦略広報課長","answer":"ホームページのシステムの部分につきましては、こちら、運用事業者に確認しながら、改善できることはないか考えていきたいと思います。","id":"exchange-059"},{"speaker":"吉田委員","kind":"提案","question":"たくさん集めてほしいなということで意見を言ったのですが、区としては、あらかじめの周知はしないということを確認いたしました。このホームページのここを見てくださいと言うと、区民の意見が集めやすくなるかなと思うのですが、見解を伺いますとの意見を述べました。","respondent":"與那嶺戦略広報課長","answer":"広報紙は紙面が非常に限られているところもありますので、全体の編集の中で掲載というところは検討していく形かなです。例えば、周知の仕方の部分になるかと思いますので、こちらは今後我々のほうでも検討してまいりたいと思います。","id":"exchange-060"},{"speaker":"吉田委員","kind":"質問・要望","question":"この件については、後でもし何か見解があれば伺いたいと思いますが、もう一つの質問に入ります。品川区の条例が法との整合性が取れているかなどのチェックの機能は、現在どこが担っているのか伺いたいと思います。","respondent":"勝亦総務課長","answer":"国の法令、それから、条例等との整合性等の管理です。総務課文書係におきまして、区の例規の管理、それから、法令等との整合性のチェックを行っているところです。","id":"exchange-061"},{"speaker":"吉田委員","kind":"質問","question":"そういう機能を、今は文書係がちゃんと担っているということで、法律との整合性をもうちゃんと取っているということでよろしいのか尋ねました。","respondent":"勝亦総務課長","answer":"今回の分につきましても、こちらのほうでも一定認識はございましたけれども、改正ができていなかったという部分です。申し訳ございません。","id":"exchange-062"},{"speaker":"吉田委員","kind":"質問","question":"では、認識していながらそのままというのは、どういうことなのでしょうか。他区では、ちゃんと明記して法務部門として持っているところもあると聞くのですが、品川区では、あくまで文書係ということなのか尋ねました。","respondent":"勝亦総務課長","answer":"条例、規則のほうは確認はしていますけれども、今回そこで漏れた部分があったです。今後、そういった全体的な精査も常々しておりますけれども、引き続き、しっかりやっていきたいと考えています。","id":"exchange-063"},{"speaker":"吉田委員","kind":"質問","question":"それは戦略広報課が担うのでしょうか。どうしても市とか政令市とか、２３区とかが特に、その辺についてはいかがか尋ねました。","respondent":"勝亦総務課長","answer":"区民に分かりにくいという部分につきましては、基本的に全体を統括しているのは総務課文書係になります。それは文書係でも各所管でも、お問合せがありましたら、そういったものについてはご対応していくという考え方です。","id":"exchange-064"},{"speaker":"吉田委員","kind":"質問","question":"では、ここはおかしいのではないのと思ったときには、文書係も受け付けてくれるよというふうにご案内して大丈夫ということでしょうか。次年度急にというのは、もう３月ですので無理だと思いますけれども、検討はいただけないか尋ねました。","respondent":"勝亦総務課長","answer":"法律、それから、条例、規則等のお問合せにつきましては、該当の所管、もしくは総務課文書係をご案内いただいて結構です。","id":"exchange-065"},{"speaker":"吉田委員","kind":"質問・要望","question":"専門性を高めていただきたいのは、これからはそういうふうになるよということを生活者ネットワークとしてみんなに広報しても大丈夫ということですね。最終的にご答弁ほしいと求めました。","respondent":"勝亦総務課長","answer":"各所管において専門的な事務を進めていく中で、法令、規則等、理解をした上で専門的な事務を進めていくのは当然です。所管にお問合せいただいてもしっかりと対応いたしますし、そこの部分につきましては、総務課文書係で全体を統括してまいります。","id":"exchange-066"},{"speaker":"吉田委員","kind":"質問・要望","question":"文書係ということが確認できましたので、明確に、ここが法令部門は担いますということを伝えることをしてほしいと思います。だから、こういう機会に全体を見直すということは考えられないのか尋ねました。","respondent":"勝亦総務課長","answer":"法令等と条例、規則について、漏れ等がないか全体の見直し、今後事務を進めていく中で、しっかり確認していきたいと思います。","id":"exchange-067"},{"speaker":"吉田委員","kind":"質問・要望","question":"ただ、これはやはり責任者としてのそこの長とか区が担うべき問題ではなかったのかなということを思います。その辺についていかがでしょう。","respondent":"勝亦総務課長","answer":"具体的な事案は別といたしまして、法律等々の専門的な解釈の部分、所管ともしっかり連携して進めていきたいと考えております。","id":"exchange-068"},{"speaker":"中塚委員","kind":"質問・要望","question":"１９５ページ、人権啓発事業より部落解放同盟の機関紙解放新聞の大量購入と管理職への無料配布の中止を求めて質問したいと思います。その内訳について、例えば、解放新聞全国版では１年間で総額幾らか、総部数は何部か伺います。","respondent":"木村人権・ジェンダー平等推進課長","answer":"「明日を拓く」増刊号が１万７,６００円、「水平東京」が４,０８０円、「狭山差別裁判」が６万８,４００円などになります。総部数に関しましては、１万６１７部数になります。","id":"exchange-069"},{"speaker":"中塚委員","kind":"質問","question":"効率化、効率化と述べておりますが、ならば、この１５０部の購入を事務事業評価ではどのように評価しているのか伺いたいと思います。私は費用対効果をちゃんと検証すべきだと思いますが、いかがか尋ねました。","respondent":"木村人権・ジェンダー平等推進課長","answer":"管理職への研修というか、学びに関しましては、各区で考え方があると思いますので、そちらにつきましては、各区の考えというふうに理解します。事務事業評価につきましては、人権啓発事業という形で評価をしておりまして、これ単体で評価をしているものではございません。","id":"exchange-070"},{"speaker":"中塚委員","kind":"質問","question":"この２３区で最も多い解放新聞の異常な大量購入をどのように思っているのか、これが効果的だと、効率的だと本当に思っているのか伺いたいと思います。税金を使って解放新聞の大量購入、研修会の繰り返し、こうしたことはやめるべきだと思いますが、いかがか尋ねました。","respondent":"木村人権・ジェンダー平等推進課長","answer":"こちら、人権課題につきましては、効率ですとか、そういうところで測る話ではないのかなと考えております。事務事業評価につきましては、トータルでの評価をしているというところで、決してこちらのものについて評価をしていないということではございません。","id":"exchange-071"},{"speaker":"中塚委員","kind":"質問・要望","question":"税金を原資に、部落解放同盟の運営のための収入に税金を環流させている、これが狙いではないのか伺いたいと思います。部落解放同盟との利権に手を切るべきだと思いますが、いかがか尋ねました。","respondent":"木村人権・ジェンダー平等推進課長","answer":"丁寧に、必ず忘れずにいなければいけない問題だということで、新聞で常に皆様に理解を求めているところです。","id":"exchange-072"},{"speaker":"中塚委員","kind":"質問・要望","question":"年間で３２０万円、見直さないとする、その姿勢は正さなければいけないと思います。ぜひとも利権と手を切って、区民のための品川区政を強く求めておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-073"},{"speaker":"澤田委員","kind":"質問","question":"本日は、２０７ページ、住まいの防犯対策助成金、１８１ページ、全庁共通プロジェクト推進経費の公有地活用検討等についてお伺いいたします。区としては、戸建て、集合住宅を含めて、録画機能付きインターホンの設置状況を把握されているのか尋ねました。","respondent":"河合生活安全担当課長","answer":"認識につきましては、委員の認識と同じように、築年数が古いところがやはりついていないという認識はあります。インターホンが１６２件、計３１８件というところで、それだけニーズがあるという認識をしております。","id":"exchange-074"},{"speaker":"澤田委員","kind":"質問・要望","question":"録画機能付きインターホンを設置されまして、誰が訪ねてきたのかをモニター越しに確認することができて大変心強いと、大変好評でした。住民の８割以上が集合住宅に住んでいる状況を踏まえますと、私からも、この集合住宅への拡充というのを要望したいと思います。","respondent":"河合生活安全担当課長","answer":"区民の防犯意識、関心を高める、底上げを図るためにも必要な事業だと考えております。品目につきましても、委員の挙げていただいた品目、こういったところを上限額内で複数選択できるような形で、助成の方向で検討しています。","id":"exchange-075"},{"speaker":"澤田委員","kind":"質問・要望","question":"続きまして、１８１ページ、全庁共通プロジェクト推進経費の公有地活用検討についてお伺いします。公有地の活用として求められているものは、発災時には避難場所ともなる公園など、多様なニーズがあります。","respondent":"吉岡政策推進担当課長","answer":"民有地におきましても、確保、また活用を進めてきたところです。既存の区有地を活用・検討するほか、各所管と共に連携しながら、必要な施設需要に着実に対応できるよう努めてまいります。","id":"exchange-076"},{"speaker":"澤田委員","kind":"質問・要望","question":"買取基準額を上げるなど、様々な方法でご検討もいただければと要望して、次に移ります。この好事例のような公共施設や土地の活用について、区としてはどのようにお考えか尋ねました。","respondent":"吉岡政策推進担当課長","answer":"一定規模の建設までいかないような土地につきましても、可能な限り有効活用できるようにというところで、個別に検討してきたところです。費用対効果など、総合的に勘案しながら、区民サービスの向上につながるような検討をしてまいりたいと思います。","id":"exchange-077"},{"speaker":"澤田委員","kind":"意見","question":"しっかりとご希望に添ったというか、調整しながら、このような土地の活用をしてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-078"},{"speaker":"塚本委員","kind":"質問","question":"１９３ページの住民参加型デジタルプラットフォーム経費、時間があれば、２０３ページの町会・自治会館建設等補助について伺っていきたいと思います。","respondent":"與那嶺戦略広報課長","answer":"こちら、デジタルプラットフォームに関しての仕組みは、昨今、様々な事業者でサービスの展開などがされているということは把握しております。","id":"exchange-079"},{"speaker":"塚本委員","kind":"確認","question":"そういうエビデンスに基づいた政策というものを決定していくツールとして使っていこうということにおいて、いわゆるアンケートとの違いがあるのか。いや、そうではなくて、これはもっと進んだ形のものがあるのかというところでの確認をお願いいたします。","respondent":"與那嶺戦略広報課長","answer":"それに対して回答していただくというところ、それはＱとＡみたいな形で、一方向の流れであったかなというふうに把握しています。さらにそこにコメントをつけるなどして、デジタルの中で議論が喚起されていくような仕組みということを意識して考えてあります。","id":"exchange-080"},{"speaker":"塚本委員","kind":"質問","question":"都度都度返信してお答えを、区に対してこれはどうなのですかというようなことに対しての返信をしていくような運用を考えているのか。この辺をお願いしたいと思います。","respondent":"與那嶺戦略広報課長","answer":"昨年実施した防災訓練についての意見募集であったり、投稿者の名前については、登録しなくても大丈夫というような形で受け付けてあります。区が返信をするかどうかというところの部分なのですけれども、そういった選定の中で、仕組みについては検討してまいりたいと考えています。","id":"exchange-081"},{"speaker":"塚本委員","kind":"提案","question":"そういった位置づけであるべきというか、そういったところに関しての区の見解をお伺いしたいのと、今後の活用についてお願いします。予算措置を伴うような施策についても一つ提案をして、現状でどのような見解をお持ちであるのか、お伺いしたいと思いますとの意見を述べました。","respondent":"與那嶺戦略広報課長","answer":"デジタル民主主義を進めていくというところと、それぞれ補完し合うものという認識は、我々も同じ形で持ってあります。仕組みを検討している最中と先ほど申し上げましたけれども、その上で、今後の活用については考えていきたいと思います。","id":"exchange-082"},{"speaker":"やなぎさわ委員","kind":"質問","question":"八潮ですけれども、昭和５８年にまち開きをしたということで、私も昭和５８年生まれということで、同級生の八潮についての質問です。八潮地区を含めた品川５地区の高齢化率を説明するよう求めました。","respondent":"今井八潮まちづくり担当課長","answer":"大崎については１６.７％、大井地区については１８.５％、荏原地区については２０.８％。八潮地区については３６.５％ということになっておりまして、ほかのエリアと比べまして、１.５倍以上の高齢化率といったような状況です。","id":"exchange-083"},{"speaker":"やなぎさわ委員","kind":"質問","question":"さらに言うと、八潮は７０代の方が最もボリュームゾーンになっておりまして、介護サービスを利用される方は今後も増えることが予想されます。","respondent":"今井八潮まちづくり担当課長","answer":"それとは別に、通常の分譲マンションもあるところです。自治会数なのですけれども、八潮全体で現在２８の自治会が存在するということで認識しております。","id":"exchange-084"},{"speaker":"やなぎさわ委員","kind":"質問","question":"結構１０分ぐらいロスをしてしまうことがあったりして、そのせいで、時間が足りなくてサービスをお断りするという事例が実際に発生しております。こういった相談が区に寄せられているかとか、もしくは、把握しているかというのをお伺いしたいのですが、いかがでしょう。","respondent":"今井八潮まちづくり担当課長","answer":"こちらの施設長の方ですとか、現場の担当者の方と定期的に意見交換のようなものも実施させていただいているところです。こういった中で、八潮地域の特殊性に起因するようなサービス事業者のご苦労みたいな話も聞いているところです。","id":"exchange-085"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"これは要望です。昨年、「さらば青春の光」、調査研究しますというふうに一応お答えをいただいているのですけれども、その後お調べにはなっていただけたのか尋ねました。","respondent":"吉野税務課長","answer":"こちらの総務省の認可に当たりましては、いろいろな基準がありまして、全部で１９項目の基準があります。今、そういった内容を精査しまして、条件に照らして確認・検証しています。","id":"exchange-086"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"一昨日の質疑で確認した、１万５,０００円が、利益というような感じになると思うのです。この返礼品由来の区の歳入は、直近で幾らぐらいになりますか尋ねました。","respondent":"吉野税務課長","answer":"先日も答弁させていただいたのですけれども、税務課内だけでいきますと、寄附金が５３５件、１,６１０万３,０００円になります。","id":"exchange-087"},{"speaker":"やなぎさわ委員","kind":"提案","question":"１０分の１だとしても、１０分の１でも３,０００万円の歳入になるということで、体験型の提案をさせていただきました。よろしかったら、その検討をさらに前に進めていただけたらと思うんですが、いかがか尋ねました。","respondent":"吉野税務課長","answer":"先ほどもお伝えしましたが、内容等を条件に照らしまして確認して、研究してまいります。","id":"exchange-088"},{"speaker":"やなぎさわ委員","kind":"質問","question":"第１回に先駆けて、ぜひ課長の意気込みを伺えればと思うのです。","respondent":"三井スポーツ推進課長","answer":"もうあと２日ということで、関係団体と協議を重ねてまいりまして、警備体制を整えてまいりました。まだあと２日ありますので、気を引き締めて、当日皆さんが楽しんで安全に大会が開催できるよう準備を進めてまいります。","id":"exchange-089"},{"speaker":"鈴木委員","kind":"質問・要望","question":"１９４ページの人事管理費から会計年度任用職員の待遇改善と、それから、保健師の増員を求めて質問をしたいと思います。代表質問の中で、品川区も１年ごとの公募をやめて継続雇用にしてほしいということで求めたのに対して、国の動向を踏まえて検討するという答弁でした。","respondent":"宮尾人事課長","answer":"継続雇用の方向の検討ですけれども、他自治体の動向も見ながら、導入に向けて検討してまいりたいと考えています。来月の４月１日は枠がもう固まっており、できるだけ早い段階で制度の導入に向けて検討してまいりたいと考えています。","id":"exchange-090"},{"speaker":"鈴木委員","kind":"質問・要望","question":"均等待遇に向けて、自治体としてどう認識され、どういうふうに取り組んでいこうとしているのかについて伺いたいと思います。特に５年以上働いているという方が３３％もいるにもかかわらず、何年働いても新入職員と同じという状況では、その点についてもどう考えるか伺います。","respondent":"宮尾人事課長","answer":"ただ、これにとどまらず、状況に応じて、しっかりと周りの状況なども見ながら、今後も検討してまいりたいと考えています。こちらを検討していく中で、併せて、どういったことができるのかというところを考えてまいりたいと考えています。","id":"exchange-091"},{"speaker":"鈴木委員","kind":"質問","question":"そこにプラス地域手当というのが２０％つくということなので、実際は十七、八万円安いというのが実際の賃金になっている。保健師なのに、准看護師と同じ等級というのがおかしいのではないかと思うのですが、その点、いかがか尋ねました。","respondent":"宮尾人事課長","answer":"職の給与額の設定の考え方というのは、これまでにご説明を申し上げているとおりです。これからも、状況に応じて適宜しかるべき見直しは行ってまいりたいと考えております。","id":"exchange-092"},{"speaker":"石田（し）委員","kind":"質問","question":"それと、１８２ページ、デジタル推進費についてお伺いをします。昨年の第３回定例会でも、私は一般質問で質問しましたが、東京都でカスタマー・ハラスメント防止条例が制定されて、来月から施行されます。","respondent":"石井コンプライアンス推進担当課長","answer":"そうしたものを受け、品川区としても、職員の対応要領について策定途中です。４月１日に発出できるように準備を進めているような段階です。","id":"exchange-093"},{"speaker":"石田（し）委員","kind":"質問","question":"ここにいわゆるカスタマー・ハラスメントは入っていない。第３回定例会でも、この件については改正をするべきではないかと言ったのですが、どのように進めているのか説明するよう求めました。","respondent":"石井コンプライアンス推進担当課長","answer":"それに向けて、品川区でも職員対応要領を定めることで、その職員対応要領の中で。現行ハラスメント防止対策の品川区の方針については、現状は、それを二本立てで対策を取っていくというところで考えております。","id":"exchange-094"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"東京都が条例を施行する中で、品川区としてもしっかりと対応していっていただきたいなと思いますので、これは要望でとどめておきます。来年度の予算について、これまでと、そして、今回のこの予算案、どこが大きく違うのか、推進をしているのか、説明するよう求めました。","respondent":"西澤ＤＸ戦略担当課長","answer":"これまでの取組とどう違うかという話ですが、来年度、ＤＸ推進基本方針を改定しまして、これまで３か年ＤＸの取組をやってまいりました。その中で、仕事ＤＸでは、Ｍｉｃｒｏｓｏｆｔ３６５の導入などを含めて、職員の効率化というところを進めていこうと考えております。","id":"exchange-095"},{"speaker":"石田（し）委員","kind":"質問","question":"１年が終わってしまって、どうしようかな、それを区が導入できずに次に進んでしまう。その辺は、やはり一歩踏み込んでこれをやっていかなければいけないと思うのですが、担当課としてどのように考えているか説明するよう求めました。","respondent":"西澤ＤＸ戦略担当課長","answer":"ＧＰＴ－４ｏとかといったような、金額は変えずに、よりアップデートしたものを使えるようなものを採用しているというような状況になっております。これはＭｉｃｒｏｓｏｆｔ３６５でも同じような状況になっております。","id":"exchange-096"},{"speaker":"石田（し）委員","kind":"提案","question":"ＩＴの人たちと今一生懸命いろいろ区も進めようとしているわけですから、そこをどうやって活用していくかというのは、やはり大事だと思うのですとの意見を述べました。","respondent":"宮尾人事課長","answer":"その職員の人物像、能力等を見極めながら、職員一人ひとりに合った職場を考えているです。今後については、どのようなことがこの中でできているかというのは研究をしてまいりたいと考えています。","id":"exchange-097"},{"speaker":"石田（し）委員","kind":"提案","question":"職員の皆さんの仕事軽減にぜひ取り組んでほしいと求めましたので、提案にしますが、ぜひ研究をしてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-098"},{"speaker":"こんの委員","kind":"質問・要望","question":"１９９ページ、２０７ページ、ページ順不同で質問してまいります。現在の検討の進捗状況をお知らせいただきたいのと、基本的な活用の考え方というのが出てきたと思いますので、簡潔にご説明ほしいと求めました。","respondent":"泉広町事業調整担当課長","answer":"そして、学識経験者の皆様で構成される庁舎跡地等活用検討委員会を開催いたしまして、主に区民ニーズの把握に努めてきたところです。にぎわいの創出ですとか、こういったところの位置づけに向けまして、今後具体の検討を進めていくというところになってあります。","id":"exchange-099"},{"speaker":"こんの委員","kind":"質問・要望","question":"ぜひ、日頃の訓練が必要な消防団の訓練の場所の確保についてもご検討いただきたい、こういう要望の声が出ております。消防団の訓練を常設した場所でできるように何とかならないかというこの要望に対して、跡地活用、どのように考えますか尋ねました。","respondent":"泉広町事業調整担当課長","answer":"今、委員からご案内がございましたとおり、検討委員会の中では、災害対応力の向上というところ、重要な視点の一つになってあります。","id":"exchange-100"},{"speaker":"こんの委員","kind":"提案","question":"若者の生活事情や、何が若者の住宅に困難を擁しているのかということを把握していただきたい、このように提案をいたしました。いわゆる若者の住宅支援がなぜ必要なのかというと、改めて、この若者への住宅支援というところのご見解をほしいと求めました。","respondent":"與那嶺戦略広報課長","answer":"来年度予定する住民参加型デジタルプラットフォームの、まずテーマについてのご提案という形で説明します。昨年実施した試行実施におきましても、若い世代の方からの回答が全体の４割程度を占めるというところで、今後検討してまいりたいと思います。","id":"exchange-101"},{"speaker":"こんの委員","kind":"質問","question":"ぜひ、このデジタルプラットフォームの中で、若者の意見等々をお聞きしていただいて、若者の住宅支援というところを具体的に検討を進めていただくようお願いをいたしまして終わりとします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-102"},{"speaker":"こしば委員","kind":"質問","question":"品川区では、これまでも、そして、これからも、引き続き平和を願う取組が、この１年もそうですが、様々な場所で行われると認識をしております。戦後８０年を迎えまして、品川区の平和に対する考えについて教えてほしいと求めました。","respondent":"勝亦総務課長","answer":"戦後８０年ということで、まず、品川区は、非核平和都市品川宣言に基づきまして、平和事業を実施しております。戦後８０年に向けましては、まず来年度、戦後８０年を意識しました被爆ピアノを使った演奏会、こういったものを考えているところです。","id":"exchange-103"},{"speaker":"こしば委員","kind":"質問","question":"このカンナに囲まれました「平和の誓い」像についてお聞きしたいと思います。この「平和の誓い」像について、つくられました経緯と、当時のつくられたことへの思いについて教えてほしいと求めました。","respondent":"勝亦総務課長","answer":"まず大井町駅に一番大きいものが設置されてございまして、五反田文化センターですとか、大崎ニューシティにも設置をさせていただいているところです。土台には原爆のきのこ雲をイメージした台座で平和を訴えていくという像になってあります。","id":"exchange-104"},{"speaker":"こしば委員","kind":"質問・要望","question":"この「平和の誓い」像がなかなか目立たないのではないかという、周りの景観に埋もれてしまっているのではないかといったお話も聞いておりました。今回の質問がありましたので、そういったものをぜひご検討してほしいと求めましたけれども、いかがか尋ねました。","respondent":"勝亦総務課長","answer":"この平和への願いを込めた像、多くの方に見ていただくことは大事なことだと考えています。そういった意味で、今あります説明文ですとか看板を、より目立つといいますか、視認性の高くなるように工夫していきたいと考えます。","id":"exchange-105"},{"speaker":"こしば委員","kind":"質問・要望","question":"８月６日から終戦の日の８月１５日にかけて「平和の誓い」像を中心軸にしました取組というのを、今後ぜひ検討していただきたいと考えます。","respondent":"勝亦総務課長","answer":"非核平和都市品川宣言４０周年に当たりますので、今、動画として公開していきたいと考えています。そのほかにも、機会を捉えていろいろな声をお聞きして、後世に伝えていきたいと考えております。","id":"exchange-106"},{"speaker":"こしば委員","kind":"質問・要望","question":"この派遣された子どもたちは、８月６日の平和式典に参加をし、原爆投下の日に考える機会が与えられることになります。言葉をつなげていく役割があると考えますが、これらの事業を通じて派遣されました子どもたちの役割についてどのように考えているか説明するよう求めました。","respondent":"勝亦総務課長","answer":"３月２３日に実施いたしますけれども、長崎に参加した方たちのグループの発表、お話をするような場を設けてあります。今後後世に向かって、皆さんのお友達やお子さん、そういった方たちに続けてお伝えいただくようにお願いをしています。","id":"exchange-107"},{"speaker":"こしば委員","kind":"提案","question":"時期が１２月頃と伺っております。恐らく１２月ですと、多くの方が演奏に耳を傾けていただける機会もぜひ確保してほしいと求めましたが、お考えを教えてほしいと求めました。","respondent":"勝亦総務課長","answer":"今のところ、場所は、やはり中心のきゅりあんで実施できたらと考えています。そういったものと連携した形で、それから、戦後８０年というものを区民の方に周知啓発していきたいと考えております。","id":"exchange-108"},{"speaker":"こしば委員","kind":"質問・要望","question":"子どもの頃だからこそ、物事に対して純粋に学ぶことは大変大切だとは思います。その一方で、平和教育というものをぜひ伝えていってほしいと求めましたが、区のお考えについて教えてほしいと求めました。","respondent":"勝亦総務課長","answer":"多角的な平和のお伝えです。今年度から実施いたしました絵本を使ったワークショップですとか、被爆ですとか、戦後８０周年を考える機会をつくってまいりたいと考えています。","id":"exchange-109"},{"speaker":"こしば委員","kind":"質問・要望","question":"１８９ページの地域住民と外国人との交流促進です。国際理解の促進が盛り込まれておりますけれども、品川区が目指す外国人との共生社会の到達点、目標等がありましたら教えてほしいと求めました。","respondent":"勝亦総務課長","answer":"区内には１万７,０００人、史上最高と言えるぐらいの外国人の方にお住まいいただいております。それから、地域住民と共生し、地域の担い手として一緒に共存していける社会を築いていきたいと考えております。","id":"exchange-110"},{"speaker":"田中委員","kind":"質問・要望","question":"１９７ページ、新庁舎関係と、２０３ページ、地域センター関連についてお伺いします。そのことが、より多くの区民が来る新庁舎においての、今現在のお考えをお聞かせほしいと求めました。","respondent":"山下新庁舎整備課長","answer":"新庁舎の予定地につきましては、広町二丁目２番５号ということで、昨年の第１回定例会で位置の条例についてご議決を賜ったところです。その手段として、新庁舎でというところにつきましては、何ができるかというところを、今後その手段や方策について考えてまいりたいと存じます。","id":"exchange-111"},{"speaker":"田中委員","kind":"質問・要望","question":"ぜひ改めていただきたいですし、広町の品川区庁舎跡地等活用検討委員会の報告書の１－２というページに、品川地区と書いております。広町二丁目も権現町会の地域として共に活動していきたいという要望がもしあれば、そして、今現在のご見解をお聞かせほしいと求めました。","respondent":"宮澤地域活動課長","answer":"町会に関しましても、面しているところも全て権現町会になってあります。権現町会からも、マンション等ができた暁には、勧誘・加入等を進めていきたいというふうにもお聞きしています。","id":"exchange-112"},{"speaker":"田中委員","kind":"質問・要望","question":"名称板とともに、町会としても連携を取っていただいて、共によりよい地域にしてほしいと求めました。今回の新庁舎の完成に伴って、そこまで踏み込んだ形での取組をぜひお願いをしたいと思いますが、いかがか尋ねました。","respondent":"山下新庁舎整備課長","answer":"ただいまございましたように、新庁舎におきましてワンストップの窓口の検討ということで、現在進めてあります。このたびお示ししました実施設計概要にも記載をしておりますけれども、今、手続の選定に着手をいたしました。","id":"exchange-113"},{"speaker":"田中委員","kind":"質問・要望","question":"ぜひそういう方向で進めていただきたいのと併せて、新庁舎、やはり同様のサービスが受けられるような体制をぜひ整えてほしいと求めました。地域センターなのかどうかも含め、地域センターも含めた取組が必要だと思いますが、いかがか尋ねました。","respondent":"宮澤地域活動課長","answer":"新庁舎、ワンストップの窓口、ワーキンググループに私も参加しております。地域センターでできるところというところ、しっかり研究してまいります。","id":"exchange-114"},{"speaker":"松永委員","kind":"提案","question":"こちら、品川区が昭和６０年頃に自然の潤いということを求めて、平成２年４月１９日に「ふるさと交流協定」が結ばれたと伺っております。伺いますが、何か早川町と品川区でイベントまたは式典などは行われる予定はありますか尋ねました。","respondent":"勝亦総務課長","answer":"大きな式典等は今のところ検討してございませんが、従前からも夢さん橋ですとか宿場まつり、そういったものにご参加いただいていると思います。３５周年に当たって、より広くＰＲがどのようにできるか検討してまいりたいと思います。","id":"exchange-115"},{"speaker":"松永委員","kind":"質問","question":"この目標値についてでありますが、どのように決定されたのでしょうか。この宿泊施設のヘルシー美里、ヴィラ雨畑、それぞれどういった割合になっているのか説明するよう求めました。","respondent":"勝亦総務課長","answer":"バスツアーにつきましては、年間８回行っているものでございまして、参加者数の最大から考えまして、そのような目標設定としています。ヘルシー美里が中心になっておりまして、約３００件、ヴィラ雨畑が約１００件という状況になってあります。","id":"exchange-116"},{"speaker":"松永委員","kind":"質問","question":"その中で、当日キャンセルというのはあるのでしょうか。何で伺うかというと、キャンセル待ちのようなシステムを導入していただければと思うのですが、もしこうした取組があれば示すよう求めました。","respondent":"勝亦総務課長","answer":"やはり金曜日が平日ということもありまして、お仕事等の予定で急遽キャンセルになってしまうというケースがあります。予定の立てやすい土曜、日曜を中心に設定して、できるだけキャンセルの出ないように設定してまいりたいと考えております。","id":"exchange-117"},{"speaker":"松永委員","kind":"提案","question":"これは提案になるのですけれども、実は近年、４０代から５０代を中心とした層が行っている新たな人生のパートナーを求めて。中でも、特に観光と出会いを融合させた婚活バスツアーが注目されており、こうしたツアーについて、品川区としての考えを示すよう求めました。","respondent":"勝亦総務課長","answer":"早川町のバスツアーは様々な切り口で実施しています。今後、ご意見を参考にさせていただければと存じます。","id":"exchange-118"},{"speaker":"松永委員","kind":"質問・要望","question":"現在では１８歳以上の品川区民を対象に、環境問題の啓発などを学んでおられるようですが、この２つの事業のみなのか伺いたいと思います。こうした観点からも、区としてのご意見を伺いたいと思います。","respondent":"勝亦総務課長","answer":"「マウントしながわ」については、里山の再生を中心に実施しています。様々な活用方法について、今後も検討していきたいと思います。","id":"exchange-119"},{"speaker":"松永委員","kind":"質問","question":"ぜひ、こうした活動を進めてほしいと求めました。お伺いするのを忘れていたのですが、８回ということでありますが、分かりましたら教えてほしいと求めました。","respondent":"勝亦総務課長","answer":"基本的には年間を通じまして実施しておりまして、各回とも約３０名から４０名の方にご参加いただいている状況です。","id":"exchange-120"},{"speaker":"松永委員","kind":"質問","question":"いい時期はあまりないということでよろしかったでしょうか。例えば、夏休みとか、そうしたところで例えば２回やるとか、そういったところはないかなということだったのですが。","respondent":"勝亦総務課長","answer":"様々な企画を実施しております。例えば、田植えですとか、ホタル、そういったそれぞれの企画に合った時期を設定しています。","id":"exchange-121"},{"speaker":"松永委員","kind":"質問","question":"こうした非対面から対面式の犯罪が主流になりつつある中、本区として、どういった対策を進めていかれるのでしょうか。併せて伺います。","respondent":"河合生活安全担当課長","answer":"やはり来年度から東京都の助成が始まりますので、こういった設置の助成、設置促進というのは必要かと考えております。高齢者地域支援課の、突然の来訪者には絶対ドアを開けないでくださいとか、そういった対応は進めているところです。","id":"exchange-122"},{"speaker":"のだて委員","kind":"質問・要望","question":"私からは、１８７ページの非核平和都市品川宣言事業に関わって、核兵器廃絶と城南空襲の日を設置することを求めて質問します。国に核兵器禁止条約に参加を求めてほしいと求めましたけれども、いかがか尋ねました。","respondent":"勝亦総務課長","answer":"区では、この宣言に基づきまして、創意工夫を重ねて平和事業を継続的に実施をしております。そういった意味では、平和に向けた取組は果たしてまいりますけれども、国のほうで国会の場で議論を十分に尽くすべきものと考えています。","id":"exchange-123"},{"speaker":"のだて委員","kind":"質問","question":"国で議論すべきと言いますけれども、区の宣言には、いまだかつて開発された兵器で使われなかったものはないと。これを見ると、被爆者の皆さんと同じ立場にあると思うのですけれども、いかがか尋ねました。","respondent":"勝亦総務課長","answer":"非核平和都市品川宣言です。この宣言の理念に基づきまして、区は平和事業を実施いたしまして、恒久平和の確立について区民に意識啓発、周知を行っていくという考えです。","id":"exchange-124"},{"speaker":"のだて委員","kind":"質問・要望","question":"代表質問の答弁で、被爆者の声を聞く会を開いてほしいと求めましたけれども、いかがでしょうか。先ほども質疑がありましたけれども、ぜひ区長も一緒に参加をしてほしいと求めましたけれども、いかがか尋ねました。","respondent":"勝亦総務課長","answer":"日本原水爆被害者団体協議会の方につきましても、そういった思いに寄り添って、区として平和事業を進めてまいりたいと考えています。日本原水爆被害者団体協議会の方のお声を聞く機会を捉えまして、できるだけ考えていきたいと存じます。","id":"exchange-125"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ、被爆８０年のこの機会に、そうした日本原水爆被害者団体協議会の皆さんからも話を聞く機会をつくってほしいと求めました。例えば、荏原区役所があった荏原文化センターに設置するのはいかがか尋ねました。","respondent":"勝亦総務課長","answer":"現在、区のＹｏｕＴｕｂｅの公式チャンネルのほうでも空襲についての動画を公開しております。こういった空襲、そういった被害を後世に伝えていくべく、引き続き周知を図ってまいりたいと考えています。","id":"exchange-126"},{"speaker":"のだて委員","kind":"質問・要望","question":"様々取り組んでいただいて、その中に、この城南空襲の碑を設置するということも実施をしていってほしいと求めました。隣の港区には「山の手空襲」追悼碑というのもありますので、ぜひ品川区としても設置を検討してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-127"},{"speaker":"西本委員","kind":"確認","question":"そのときの答弁の確認をまずさせてください。この区長のプレス発表前の報道記事掲載は、記者の努力であるということで、これは容認するということか尋ねました。","respondent":"與那嶺戦略広報課長","answer":"一昨日の歳入の際にもご答弁差し上げたとおり、今回の報道の件につきましては、各メディアの記者の取材活動の中で行われているものと理解しています。","id":"exchange-128"},{"speaker":"西本委員","kind":"質問","question":"ですから、今回の問題は、区長のプレス発表の前には公表しないでくださいというのを私たちは言われています。それに対して、今の見解だと、それはご自由にどうぞということでよろしいですね。","respondent":"柏原区長室長","answer":"情報というのは、そういった編集権がマスメディア側にありますので、我々がそれを止めることはできないといった認識であります。具体的なところでは、そういったものから考えますと、そういったところでご理解いただければと思ってあります。","id":"exchange-129"},{"speaker":"西本委員","kind":"質問","question":"そういうことの理解でいいですかと先ほどから。容認でしょう。","respondent":"柏原区長室長","answer":"もう一度ご答弁しますけれども、先ほどのマスメディアの活動に対しては、我々は、出ることに対しては止められないというところがあります。容認云々というよりは、それが出たという事実を我々は認知したと、そういうところです。","id":"exchange-130"},{"speaker":"西本委員","kind":"質問・要望","question":"でも、２月５日のプレス発表があるからということで、そこはルール、義務ではないのですか。区長、どうなのか尋ねました。","respondent":"柏原区長室長","answer":"こちらのほうのプレス発表の前に、資料はお渡しをさせていただいているといったところです。その内容であったりとか、これまでの議論の中で感じているところですので、それについては再考・検討させていただきたいといったところです。","id":"exchange-131"},{"speaker":"西本委員","kind":"質問・要望","question":"反省して、ちゃんと手続、それから、信頼関係を壊すようなことはしないようにしますと、なぜ言えないですか。要望書を出します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-132"},{"speaker":"若林委員","kind":"質問","question":"２０９ページの観光資源整備事業について伺います。今年度は事業の本格的な展開をされてこられましたので、そういった今年度のトライしたこと等も含めて、一回総括をお聞きしたいと思います。","respondent":"大森文化観光戦略課長","answer":"乗船料金による収入は、７９０万円余ということになってあります。しながわ水族館や羽田の飛行機を見学するコースなど、そういったコースもつくりながら、いろいろと分析をしながら進めてきたです。","id":"exchange-133"},{"speaker":"若林委員","kind":"質問・要望","question":"２０１６年度から東京都が中心になって、２０１６年の第１回定例会において、こんな質疑もさせていただいたところでございました。そういった取組を今後、来年度以降取り組んでほしいと求めましたけれども、お話を伺います。","respondent":"大森文化観光戦略課長","answer":"先月の２月の運航は、そちらと天王洲の東品川二丁目桟橋をつなぎ、そこをぐるっと周遊したという形になります。２日間の平均で、大田区であったりというところも視野に入れて、どういった桟橋とつないでいけるかというところに取り組んでまいりたいと思います。","id":"exchange-134"},{"speaker":"若林委員","kind":"質問・要望","question":"要望として、最後に、これは河川下水道課の予算になりますけれども、来年度、目黒川の護岸等のライトアップを行うと伺っております。変わって、時間はありませんけれども、１８１ページの行政評価（事務事業評価）について伺います。","respondent":"吉岡政策推進担当課長","answer":"今後、削減額の見せ方というところで、さらに今より見やすいようにというところは、引き続き検討していきたいと思います。どうぞよろしくお願いいたします。","id":"exchange-135"},{"speaker":"西村委員","kind":"提案","question":"これまでもいろいろと質問が出ておりますが、保養所について、品川荘と光林荘、また、新しい提案について伺ってまいりたいと思います。保養所を自前で持っている自治体の数と、校外学習施設を自前で持っている自治体の数を伺いますとの意見を述べました。","respondent":"宮澤地域活動課長","answer":"区民保養所を保有している区につきましては、品川区を含めて９区、校外学習施設につきましては、１６区と聞いているところです。","id":"exchange-136"},{"speaker":"西村委員","kind":"質問","question":"光林荘、子どもたちの評判も大変いいと思うのですが、いかがでしょうかということも伺いたいと思います。野生の鹿に遭遇したというような子どもたちの声もよく聞きますけれども、改めて光林荘の魅力について伺いたいと思います。","respondent":"宮澤地域活動課長","answer":"光林荘、栃木県の日光市にあるということで、歴史と文化と自然が大変豊かなところというところで、日光東照宮を含めた世界文化遺産もあるです。","id":"exchange-137"},{"speaker":"西村委員","kind":"質問","question":"先ほどの例のように、２年連続で同じ場所に行くということは、教育的観点でも意義があると考えています。一般利用に向けては課題が多くあると思いますが、この辺り、課としてはどのようにお考えか尋ねました。","respondent":"宮澤地域活動課長","answer":"そういうところから、施設が大きくつくられているというところと、半分近くが、委員ご指摘のとおり、トイレがないお部屋もあるです。魅力については低い部分はありますが、レクリエーションホール等があることから、団体利用というのには活用方法があると感じているところです。","id":"exchange-138"},{"speaker":"西村委員","kind":"質問","question":"より多くの区民が泊まりに来られるような検討も考えましたときに、団体利用を拡充していただくというようなお考えはあろうかと思うのですが、今どういう団体が使っているか、改めて伺えればと思います。","respondent":"宮澤地域活動課長","answer":"区内の団体の利用ですけれども、例えば、私立保育園の団体であったり、区内のスポーツ団体、バレーであったり、ドッジボールであったり、そういった団体、また、高齢者クラブなども利用しているというふうに伺っているところです。","id":"exchange-139"},{"speaker":"西村委員","kind":"質問・要望","question":"団体利用の告知も積極的にしてほしいと求めましたので、よろしくお願いをしたいと思います。来年度は今後の方向性を検討していくとのことで、これまでかけてきた経費でしたり、今後考えられる懸念点を伺いたいと思います。","respondent":"宮澤地域活動課長","answer":"光林荘の修繕の見込みというお話です。今現在３０年近く経ちましたけれども、それらの経費につきましては、７億７００万円余というような形です。","id":"exchange-140"},{"speaker":"西村委員","kind":"質問・要望","question":"予算特別委員会の質問の中でも、老朽化が進んでいると、抜本的に大規模改修をする時期に来ているとのご答弁がありました。もし施設を手放すとするならば、他区の事例としてはどのような手法があるのかを伺います。","respondent":"宮澤地域活動課長","answer":"最近の動向としては特別区内で２区、どちらも土地建物を売却しています。売却する際には、５年間、区民が宿泊された際の宿泊補助を引き続き５年間するというような手法でやっていると聞いております。","id":"exchange-141"},{"speaker":"西村委員","kind":"質問・要望","question":"更地にして返さないといけないというようなことも様々あると思いますので、ぜひお考えほしいと求めました。区が２０年ほど前に借上げでホテルと連携していたというお話を先輩方から伺ったことがありまして、今。","respondent":"宮澤地域活動課長","answer":"民間の宿泊施設を、協定を締結する形で保養施設として位置づけるような形で行っているのも、９区あるというところは認識しております。","id":"exchange-142"},{"speaker":"西村委員","kind":"提案","question":"そこで、ワーケーション促進のご提案を差し上げたいと思っています。既に交流のある複数の自治体への宿泊助成の拡充と、ワーケーションの促進をご検討ほしいと求めましたが、お考えを伺いますとの意見を述べました。","respondent":"勝亦総務課長","answer":"こうした住民同士のつながりを広げることのできる取組については、ぜひ進めてまいりたいと考えています。坂井市の実施されているワーケーション事業の推進ですとか、宿泊助成なども、今後先方様のお考えを伺いながら、相談してまいりたいと考えております。","id":"exchange-143"},{"speaker":"西村委員","kind":"質問・要望","question":"区内事業者、区民の多様な働き方の実現に向けても、ぜひともご検討ほしいと求めました。先ほども質問にありましたが、公平性や多様性をどのように担保するのか、参考にされた取組があれば説明するよう求めました。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"参考にした他自治体の事例についてなのですけれども、群馬県が令和５年度から高校生を対象に同様の事業を実施しており、参考にしています。令和５年度はＬＧＢＴＱの当事者から、周知を幅広く行い、多くの中高生の方が手を挙げていただけるように努めてまいりたいと考えています。","id":"exchange-144"},{"speaker":"西村委員","kind":"質問","question":"私立でしたり、都立高校、本当に区内中様々な子どもたちに声をかけていただけるということで、お願いをしたいと思います。事業の目的としまして、それとも、全ての子どもの声をというところの包摂した事業として捉えておられるのかを最後に伺えればと思います。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"自ら考え、行動する、こちらの主権者教育につながるものだと捉えております。で、こども基本法にのっとりまして、子ども未来部や教育委員会事務局の取組と連携して進めていきたいと考えているところです。","id":"exchange-145"},{"speaker":"高橋（し）委員","kind":"確認","question":"令和６年度版の公表とともに、令和２年度版から確認できるようになって、大変公平性、透明性の確保に値していると思います。それに基づく職員の健康管理についてお伺いします。","respondent":"宮尾人事課長","answer":"新年度予算は健康管理費といたしまして、今回７,０００万円余、対前年で７％増の金額を今回ご提案させていただいているです。カウンセリング、健康指導会、こういったもので健康指導の対策を講じているところです。","id":"exchange-146"},{"speaker":"高橋（し）委員","kind":"質問","question":"このような休職する方が多い、今お話があったように、大体６０人を超えて、今７７人、もうすぐ８０人ということですから。お答えできる範囲で結構ですから、ご病気だったのか、それとも、そのほかの何かの原因だったのかということをお尋ねします。","respondent":"宮尾人事課長","answer":"今お話がありましたように、病気で亡くなった職員もおります。理由は様々あります。","id":"exchange-147"},{"speaker":"高橋（し）委員","kind":"質問","question":"ですから、職員の方々のメンタルの部分は、大変厳しい状態の方々がいらっしゃるのではないかと思います。令和６年度について、今度は分限処分を受けた休職の方が何人で、そういったメンタル、精神疾患の方は何人かということをお尋ねします。","respondent":"宮尾人事課長","answer":"令和６年度に休職を取った職員の数ですけれども、令和６年度は、すみません、今すぐに数字が出ないのですが、傾向としては、大体近年同様の数値と認識をしております。","id":"exchange-148"},{"speaker":"高橋（し）委員","kind":"質問","question":"不利益な身分上の変動をもたらす処分を受けることとなる、そういう経緯が一般的にどのような状況なのか、差し支えのない範囲でお尋ねします。それから、もう一つ、病状が回復して、職場に復帰なさった場合、どのような配慮が行われているかをお伺いします。","respondent":"宮尾人事課長","answer":"まずならし勤務という、１００％にいきなりではなくて、徐々に慣らしていくというようなことを必ずやっております。利用料の一部を助成するというような、そのような取組も行って、職員がしっかりと復帰できるようにサポートをさせていただいているという状況です。","id":"exchange-149"},{"speaker":"高橋（し）委員","kind":"質問","question":"この２０代、３０代が休職のパーセンテージを上回ったということがあるのですけれども、品川区の場合はどのような状況でしょうか。それはどのような原因によるものか、そして、区として、どのような、先ほどあったような配慮というか、フォローをしていくのかお尋ねします。","respondent":"宮尾人事課長","answer":"やはり２０代、３０代、その傾向は品川区においても同様です。こういった職員同士のつながりといいますか、そういうものを強められるような、そういう取組が我々は求められていると認識をしております。","id":"exchange-150"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"あるいは、うまく取れない方に対しては、担当からうまくそういったフォローをするということは必要だと思います。先ほど令和５年度で７７人、職員の方々のウェルビーイング、それが実現できるようにご尽力いただきたいという思いで質問させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-151"},{"speaker":"松本委員","kind":"質問","question":"１８９ページ、２０５ページ、区民保養所経費について伺います。営業していなかった日というのは、令和６年度で、今分かる範囲で何日ぐらいあるのか尋ねました。","respondent":"宮澤地域活動課長","answer":"今年度４月から１月末までで見ますと、３０６日ありますが、このうち、利用が全くない日というのは２０１日になります。学校が利用しているのは８４日、団体が利用しているのは２０日という形になっています。","id":"exchange-152"},{"speaker":"松本委員","kind":"提案","question":"もう３０年以上経っている施設ですから、実は子どもたちにとってもいい学習ができる可能性というのはあるのではないかと思っていますとの意見を述べました。","respondent":"宮澤地域活動課長","answer":"光林荘、品川荘も含めてになります。区民保養所という形の今後の方向性について検討していく中では、区長部局含めて、しっかりと検討していきたいと考えております。","id":"exchange-153"},{"speaker":"松本委員","kind":"提案","question":"ＳＤＧｓのほうですけれども、先日、一般質問の際に、やなぎさわ議員がしながわシティラボの株式会社マチルダについて取り上げられておりました。まず最初に、今回しながわシティラボの中でも、この実証実験提案型の趣旨・目的について改めて伺えればと思いますとの意見を述べました。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"現状といたしまして、区民ニーズが多様化する中で、社会や地域の課題は複雑化していて、行政だけで解決するのは難しい時代を迎えております。区が実証実験の場などを提供することによって、新たなソリューションを創出する、そういうものです。","id":"exchange-154"},{"speaker":"松本委員","kind":"提案","question":"そこで、区内事業者との関係、商店街などとの関係というのが出てきているので、これは、今も産官学という話はあったかと思いますが、例えば、商店街とか個人事業主が提案から排除されているわけではないというふうに伺ってよろしいか尋ねました。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"提案していただく事業者なのですけれども、当然、民間企業、ＮＰＯ等の団体、それから、大学、研究機関、それから、個人事業主の方も、皆様ご提案いただく要件を満たしているということになります。","id":"exchange-155"},{"speaker":"松本委員","kind":"提案","question":"この提案する人を、このメリットは、区内の事業者が守られるということかと思います。一方で、デメリットもあるかと思うのですが、区内事業者に提案者を限ってしまった場合のデメリットを伺えればと思いますとの意見を述べました。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"区外事業者を排除して、区内事業者に限定することによって、区の課題の解決への絶対的な絶対数、提案数が少なくなります。あるいは、もう課題解決ができないような状況になりまして、ひいては区民サービスの向上につながらなくなるということが考えられるかと思います。","id":"exchange-156"},{"speaker":"松本委員","kind":"提案","question":"今回のマチルダの件も、アイデアだけ例えばマチルダに出させて、あとは区内事業者がやりますと言ったら、もう誰も提案しなくなる。ぜひここは積極的にやっていただいて、いろいろな方が提案をしていただきたいと思うのですが、いかがか尋ねました。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"ＦＭしながわなどで周知するとともに、企画課以外も含めました区内事業者の方が集まるような区のイベントでチラシの配布等を行ってまいりました。ただ、委員がおっしゃられたような個人事業主などについては、周知を徹底してまいりたいと考えております。","id":"exchange-157"},{"speaker":"藤原委員","kind":"質問","question":"どうしてもこれは聞きたかったのでお伺いしますが、火葬されたご遺骨から金、銀、プラチナが出てきて、これが１年間で結構な額になると聞いたのです。私は初めてこういう質問をするのですけれども、それは事実か尋ねました。","respondent":"築山戸籍住民課長","answer":"金、銀、プラチナ、パラジウムが有価物として出ますが、これを売却すると、ある程度の金額となっております。","id":"exchange-158"},{"speaker":"藤原委員","kind":"質問","question":"その売却したお金は、どこにどう行ってしまうのか尋ねました。","respondent":"築山戸籍住民課長","answer":"臨海斎場の場合ですと、火葬にかかる経費との相殺をしておりますので、委託料と相殺をするような形となっております。","id":"exchange-159"},{"speaker":"藤原委員","kind":"質問・要望","question":"年間どのぐらい出るかということを教えていただきたいのと、今回亡くなった火葬する方は、歯の中に山ほど金歯が入っていますと。だから、その金歯だけは返してくださいと言えば、それで話は通るのか尋ねました。","respondent":"築山戸籍住民課長","answer":"２点目のご質問です。通常、もし形で金歯が残っているようであれば、骨つぼと一緒にお返しをするというような形になります。","id":"exchange-160"},{"speaker":"藤原委員","kind":"質問","question":"ですから、ほかの地域と比べても、東京ではなくて、自治体に比べても、火葬料というのは安価ですよね。いかがか尋ねました。","respondent":"築山戸籍住民課長","answer":"臨海斎場の火葬料の設定の方針ですけれども、これは適正な価格ということで、実際に火葬にかかる経費から割り出して、実費分をご負担いただくという考えで行っているところです。","id":"exchange-161"},{"speaker":"藤原委員","kind":"質問・要望","question":"そして、次が、１９３ページ、しながわ百景普及啓発事業、伺います。１つだけ確認です。","respondent":"與那嶺戦略広報課長","answer":"委員ご質問の西大井駅にあります百景の看板ですけれども、名称を「西大井駅とその周辺」と銘打っておりまして、西大井駅前のロータリー、喫煙所の横に設置しています。","id":"exchange-162"},{"speaker":"藤原委員","kind":"質問","question":"移転してしまえばいいではないですか。西大井のことを考えたら、抜本的に変えていかないといけないと思うのですけれども、いかがか尋ねました。","respondent":"河合生活安全担当課長、勝亦総務課長","answer":"やはりあの場所でないと、喫煙者の方々が入り切れない状況がありますので、ここはまずそれで対応したいと考えております。西大井の平和の花壇ですけれども、関係所管と調整いたしまして、現在、再々整備といいますか、リフレッシュに着手しています。水やりに関する問題につきましては、周辺の施設、関係課と協議を進めてまいりたいと考えております。","id":"exchange-163"},{"speaker":"藤原委員","kind":"質問・要望","question":"この７月の条例は、しっかりこうやっているというのを、生活安全担当課長に見ていただいて、確認していってほしいと求めました。いかがか尋ねました。","respondent":"河合生活安全担当課長","answer":"条例改正、施行が７月というところで、私の任期を含めてというところで、今質問があったと思うのですけれども。任期は３月末で、立場は変わりますけれども、私は携わった者ですので、状況を確認しながら、後任の者といろいろ話し合っていきたいと考えております。","id":"exchange-164"},{"speaker":"藤原委員","kind":"質問・要望","question":"もし警視庁へ戻られても、私は、この品川区でいろいろしていただいたことを、ぜひ今度は東京都民のために活かしていっていただきたいと思うのです。その辺について、もう常任委員会はありませんから、私に対しての最後の答弁をしていただければ幸いです。","respondent":"河合生活安全担当課長","answer":"基礎自治体と連携、連携などと机上でやっていたのですけれども、しっかり勉強させていただきました。私も今後また戻ってきたいところでもありますので、人事なので分からないですけれども、そういったところで今後頑張っていきたいと考えております。","id":"exchange-165"},{"speaker":"藤原委員","kind":"質問・要望","question":"ぜひ、この７月を過ぎたとき、どうなったかというのを見てほしいと求めました。それと、さっき西側のことを言いましたけれども、観光の立場として、西口改札口があったほうがいいと思いますか。","respondent":"大森文化観光戦略課長","answer":"西大井駅前の、西大井駅の元からの移動幅の多い複数路線が乗り入れているといったところも鑑みて、ポテンシャルが高いものと考えています。踏切で待たされることのない、待たなくてよくなったりとか、そういったことのメリットがあるかと思います。","id":"exchange-166"},{"speaker":"大倉委員","kind":"質問","question":"２０３ページ、区民まつり経費、２１７ページ、区民スポーツ大会を先に伺えればと思います。両イベントなのですが、以前も伺いましたが、この間の物価高騰、エネルギー高騰の中で、費用についてはどのようになっていますか尋ねました。","respondent":"宮澤地域活動課長、三井スポーツ推進課長","answer":"区民まつり、各１３地区の地域センター管内ごとに開催しているところで、実施計画に基づきまして補助をしています。区民スポーツ大会ですが、こちらは競技によっていろいろ変わっていますが、主に個人は３００円から５００円、団体は１,５００円から３,０００円等で実施をしているところになります。","id":"exchange-167"},{"speaker":"大倉委員","kind":"質問・要望","question":"ぜひ増額も含めて検討していただいて、区民の方がより満足できるような区民まつりにしていってほしいと求めましたが、いかがでしょうか。そういったところが重なってくると、結構運営費も大変になってくるのではないかというところで聞きましたので、お願いいたします。","respondent":"宮澤地域活動課長、三井スポーツ推進課長","answer":"その中で、例えば、防災訓練と一緒に実施するというような形で工夫しているというふうにも伺っているところです。区民スポーツ大会は、スポーツ協会と共催で実施しているところで、区は２,２００万円ほど分担金を予算で計上しているところになります。","id":"exchange-168"},{"speaker":"大倉委員","kind":"質問・要望","question":"今そこまで多く参加できていないという現状を相談者から伺っておりまして、今現状がどうなっているのかということを教えていただきたい。発表の機会というところを見据えてスポーツが体験できるような工夫をしていただきたいなと思うのですが、いかがか尋ねました。","respondent":"三井スポーツ推進課長","answer":"障害者フライングディスク教室も、こちら年３回実施しておりまして、延べ４０名の方にご参加いただいております。東京都でこういった障害者フライングディスク教室の大会もありますので、そちらのほうに出場できるように目標を立てて実施しているところになります。","id":"exchange-169"},{"speaker":"大倉委員","kind":"質問","question":"今、フライングディスクのほうは、小学生以上の知的障害者と関心のある方ということで、知的障害者の方の人数なのかなと思うのですが、障害者水泳大会のほうは、いろいろな方が参加できるというところでは、今言っていただいた数は。","respondent":"三井スポーツ推進課長","answer":"すみません、正確な数字までは把握できていないですが、主に知的障害者の方だと聞いております。","id":"exchange-170"},{"speaker":"大倉委員","kind":"質問","question":"分かりました。３つの競技しか今ないというところで言うと、これも２つの競技しかないのかなというところで、いかがか尋ねました。","respondent":"三井スポーツ推進課長","answer":"委員ご提案のとおり、区としましても、積極的にそこら辺の参加できるイベントは開催したいと考えております。年２回ほど、特に知的障害の方に限ってはいないのですが、実際に知的障害の方もご参加いただいているような状況になっております。","id":"exchange-171"},{"speaker":"大倉委員","kind":"意見","question":"やっているところはまだあるよということだと思うのですが、しっかりと、発表の場も含めて、検討していただけるとありがたいなというところです。周知も含めて、やってほしいと求めましたので、お願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-172"},{"speaker":"あくつ委員","kind":"提案","question":"令和８年度にかけて事業者選定に入るスケジュールになっているので、改めて、提案を含めて確認をしてまいりたいと思います。そこで、お伺いしたいのですけれども、区として、この施設整備において、コンセプトの中心に図書館を置いたのはなぜなのか説明するよう求めました。","respondent":"吉岡政策推進担当課長","answer":"そういったところがございましたので、図書館という声が非常に大きく出て、今回の方針にまとまったというところもあります。２３区でこういった複合施設の図書館ですけれども、今、品川区としても大きなチャレンジだと捉えているところです。","id":"exchange-173"},{"speaker":"あくつ委員","kind":"質問・要望","question":"１０年前の決算特別委員会の総括質疑で、次のように伺いました。区の意向が１２０％事前に伝わるような事業者選定と、指定されたＳＰＣとその後の十分な協議を行っていけるのかどうか、ここで確認したいと求めました。","respondent":"吉岡政策推進担当課長","answer":"委員からもご案内がございましたＰＦＩ方式のうちＢＴＯ方式を採用する方向で検討を進めているところです。区民の皆さんに愛され、そして、安心して使ってもらえる施設になるように全力を尽くしてまいりたいと考えております。","id":"exchange-174"},{"speaker":"あくつ委員","kind":"確認","question":"今のご答弁、また、これも確認をしていきたいと思います。次に、施設のデザインについて伺います。","respondent":"吉岡政策推進担当課長","answer":"そこが階高を高くして３階にするのか、４階にするのかというところは、高さ自体はあまり変えていかない方向で考えているところです。","id":"exchange-175"},{"speaker":"あくつ委員","kind":"質問・要望","question":"そこについて、デザインをどういうふうに。品川区はＳＰＣに裁量を大きく持たせる、分かるのですけれども、品川区としても譲れないコンセプトというものが今あれば説明するよう求めました。","respondent":"吉岡政策推進担当課長","answer":"しっかりと検討しながら、より皆様からも愛されるような施設、魅力的な施設をつくっていきたいと考えています。図書館だけでなく、ふだん交流し得ないような団体や区民の方が交わるような共用スペース、そういったものを目指してまいりたいと考えております。","id":"exchange-176"},{"speaker":"あくつ委員","kind":"質問","question":"７万冊以上という、非常に少ない、ゆたか図書館と同等のレベルの蔵書数が今書いてあるのですけれども、これで本当に足りるのかと。図書館としての特色について、何かここに書いていないものがあるのであれば、今考えているものを説明するよう求めました。","respondent":"吉岡政策推進担当課長","answer":"調べる、静かにする、そういうような図書館が多かったように思います。本を借りる人も借りない人も少しおしゃべりをしながら交流できるようなスペースもあって、そういった新しい図書館を目指しています。","id":"exchange-177"},{"speaker":"まつざわ委員","kind":"質問","question":"私からは、１８９ページの全国自治体との連携事業、市町村交流事業、２０７ページ、特殊詐欺対策プロジェクト経費についてお聞きします。","respondent":"勝亦総務課長","answer":"昨日もお話が出ましたけれども、未来のご近所、飯田市とも交流等々、今後検討しています。お互いの強みを活かした交流を行いまして、区民、住民へのメリットを提供していくことを目指しています。","id":"exchange-178"},{"speaker":"まつざわ委員","kind":"意見","question":"こういうのは、例えば、交流の中で、学校同士がつながってもいいのかなというのが１点。例えば、そういったものを構築するような長期的な交流プログラムを策定していくのも一つと考えますが、それぞれにご見解を説明するよう求めました。","respondent":"勝亦総務課長","answer":"そういった意味では、多角的な方法で連携・交流を図っていくというのは非常に効果的なものであると考えております。寄附を含めて、様々な角度で、それぞれの住民が参加できるような仕組みを考えてまいりたいと思います。","id":"exchange-179"},{"speaker":"まつざわ委員","kind":"提案","question":"だったら、こっちがお神輿を持っていくというのもすばらしい事業だと思うので、そういうのも提案したいと思います。今までないところにもしっかり助成することが、交流のさらなる拡大につながると考えますが、ご見解をお願いしますとの意見を述べました。","respondent":"勝亦総務課長","answer":"戸越銀座のお祭りですとか、しながわ花海道に坂井市のお祭りの踊り手の方に来ていただいて、踊りを披露していただいたりしております。様々、いろいろな方法を検討してまいりたいと考えています。","id":"exchange-180"},{"speaker":"まつざわ委員","kind":"意見","question":"やはり子どもという部分ではなくて、この地域交流、地域連携の部分からもやはりしっかり支援していく。そういうことが、さらなる交流制度に反映できるものだと考えますが、ご見解を説明するよう求めました。","respondent":"勝亦総務課長","answer":"行政を中心とした交流も含めまして、区民や団体の方が主体的に交流・連携されることは非常に重要な意義があることだと考えています。双方の自治体、それから、それぞれの団体の支援について、今後あり方を考えていきたいと思います。","id":"exchange-181"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"防犯カメラが終わったら、開口部に対する助成、次はまずそこをやってほしいなという要望です。防犯カメラ、次の新しい課長に対しても、しっかりと期待していきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-182"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/619855?Template=document&Id=7005#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":120325,"voices":402}}]);
